window.JASTROW_CHUNKS[49]={"19600":{"h":"סַמְמָן","r":"O01112","html":"<div class=\"sense\"> c. (v. <a href=\"#\" data-headword=\"סַם\">סַם</a>) <i>drug</i>, </div><div class=\"sense\"><b>1)</b> <i>ingredient of frankincense</i>. <span class=\"citation\">Y. Yoma IV, 41ᵈ</span> bot. (expl. <span dir=\"rtl\">חציים</span>) <span dir=\"rtl\">חצי כל ס׳ וס׳</span> a fraction of each ingredient.—Pl. <a href=\"#\" data-headword=\"סַמְמָנִית\">סַמְמָנִים</a>, <a href=\"#\" data-headword=\"סַמְמָנִית\">סַמְמָנִין</a>, <a href=\"#\" data-headword=\"סִימַנְטֵיר\">סַמָּנִ׳</a>. Ib. 41ᵈ; <span class=\"citation\">Ker. 6ᵃ</span> <span dir=\"rtl\">סַמְמָנֶיהָ</span>, v. <a href=\"#\" data-headword=\"חָסַר\">חָסַר</a>. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">אחד מסַמְמָנֵי הקטרת</span> one of the ingredients of the frankincense; a. fr.—<span class=\"citation\">Y. Sabb. XII, 13ᶜ</span> bot. <span dir=\"rtl\">ליטע סִימְמָנִין</span> to plant the spices for the frankincense.</div><div class=\"sense\"><b>—2)</b> <i>pl.</i> as above: <i>paint, dye, colors</i>; in gen. <i>artist’s material</i>. <span class=\"citation\">Gen. R. s. 1</span> <span dir=\"rtl\">צייר … שמצא ס׳ וכ׳</span> your god is a great artist, but he found good material which helped him. <span class=\"citation\">Num. R. s. 12</span>; <span class=\"citation\">Ex. R. s. 35</span>, a. e. <span dir=\"rtl\">אתה בסַמְמָנֶיךָ וכ׳</span> thou (paint it) with thy materials, but I appear in my glory myself; <span class=\"citation\">Yalk. Ex. 369</span> <span dir=\"rtl\">בסַמָּנֶיךָ</span>; Pesik. Vayhi, p. 5ᵃ <span dir=\"rtl\">בסימנך</span> (corr. acc.). <span class=\"citation\">B. Kam. 101ᵃ</span> <span dir=\"rtl\">שבח ס׳</span> the value of the dye (additional to that of the wool); a. fr.—[<span class=\"citation\">Tosef. Kel. B. Mets. III, 13</span> <span dir=\"rtl\">סממנין</span>, v. <a href=\"#\" data-headword=\"סִמְלוֹן\">סִמְלוֹן</a>.]</div>","alt":["סַמָּן"]},"19601":{"h":"סַמְמָנָא","r":"O01113","html":"<div class=\"sense\">—Pl. <a href=\"#\" data-headword=\"סַמְמָנִית\">סַמְמָנִין</a>, <span dir=\"rtl\">סַמְמָנַיָּא</span>, <span dir=\"rtl\">סַמְמָנֵי</span>, <a href=\"#\" data-headword=\"סִימַנְטֵיר\">סַמָּנ׳</a>. <span class=\"citation\">Targ. Y. I Gen. XLIX, 20</span>. <span class=\"citation\">Targ. Jer. XLVI, 11</span> (h. text <a href=\"#\" data-headword=\"רִפְאוּת\">רפאות</a>). <span class=\"citation\">Targ. Ez. XXIII, 14</span> (h. text <a href=\"#\" data-headword=\"שָׁשַׁר\">ששר</a>); a. e.—<span class=\"citation\">B. Kam. 101ᵃ</span> <span dir=\"rtl\">הב לי סַמָּנַאי</span> give me back my dyes. <span class=\"citation\">B. Mets. 85ᵇ</span> bot. [read:] <span dir=\"rtl\">הוה מותיב ליה גובתא דס׳ וכ׳</span> (Ms. M. <span dir=\"rtl\">סַמָּנָאֵי</span>) he placed the tube containing the medicine under his cushion.</div>","alt":["סַמָּנָא"]},"19602":{"h":"סַמְמָנִית","r":"O01114","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"סַמְמָנָא\">preced.</a>), pl. <span dir=\"rtl\">סַמְמָנִיּוֹת</span>, <a href=\"#\" data-headword=\"סִימַנְטֵיר\">סַמָּנִ׳</a> <i>writing colors, inks</i>. <span class=\"citation\">Sabb. XII, 3</span> (<span class=\"citation\">103ᵃ</span>) <span dir=\"rtl\">משתי ס׳</span> with two inks, v. <a href=\"#\" data-headword=\"סִימָנִית\">סִימָנִית</a>.</div>","alt":[]},"19603":{"h":"סָמַן","r":"O01115","html":"<div class=\"sense\"><i>Nif.</i>), <i>Pi.</i> <a href=\"#\" data-headword=\"סִימָן\">סִימֵּן</a> (denom. of <a href=\"#\" data-headword=\"סִימָן\">סִימָן</a>) <i>to mark</i>. <span class=\"citation\">Koh. R. to XII, 10</span>, [read:] <span dir=\"rtl\">שלש סימנים סִימַּנְתִּי לך בקבורתו וכ׳</span> (<span dir=\"rtl\">וסיימתי לך</span>, being a gloss) three signs did I mark out for thee with regard to the grave of Moses; <span class=\"citation\">Midr. Till. to Ps. IX</span> (not <span dir=\"rtl\">סימנתין</span>).—Part. pass. <a href=\"#\" data-headword=\"מְסוּמָּר\">מְסוּמָּן</a>; pl. <span dir=\"rtl\">מְסוּמָּנִים</span>, <span dir=\"rtl\">מְסוּמָּנִין</span>. <span class=\"citation\">B. Bath. X, 7</span> (<span class=\"citation\">172ᵃ</span>) <span dir=\"rtl\">אם היו מ׳</span> (Y. ed. <span dir=\"rtl\">אם היו בסימנין</span>; Ms. M. <span dir=\"rtl\">אם היו סימנין</span>, v. Rabb. D. S. a. l. note) if the two persons of the same name bear also the same marks.</div>","alt":[]},"19604":{"h":"סְמַן","r":"O01116","html":"<div class=\"sense\">, <i>Pa</i>. <a href=\"#\" data-headword=\"סַמָּן\">סַמֵּן</a> <i>to believe in</i> <a href=\"#\" data-headword=\"סִימָן\">סִימָן</a>, <i>be superstitious</i>. <span class=\"citation\">B. Mets. 27ᵇ</span> <span dir=\"rtl\">כיס וארנקי משום דמְסַמְּנֵי</span> people are not likely to lend a money bag or purse, because they are superstitious about it.—<i>Part. pass.</i> <a href=\"#\" data-headword=\"מְסַמָּא\">מְסַמַּן</a>; f. <span dir=\"rtl\">מְסַמְּנָא</span> <i>auspicious</i>. <span class=\"citation\">Kidd. 59ᵃ</span> <span dir=\"rtl\">ולא מס׳ מילתא</span> and it is inauspicious (to sell the first field one has acquired).</div><div class=\"sense\"><b>Ithpa. אִסְתַּמַּן</b> <div class=\"sense\"><i>to be marked</i>. <span class=\"citation\">Targ. Y. Num. II, 2</span> <span dir=\"rtl\">אתוון דמִסְתַּמְּנִין וכ׳</span></div></div>","alt":[]},"19605":{"h":"סַמָּן","r":"O01117","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"סַמְמָן\">סַמְמָן</a>, <a href=\"#\" data-headword=\"סַמְמָנָא\"><a href=\"#\" data-headword=\"סַמְמָנָא\">סַמְמָנָא</a>.</a></div>","alt":["סַמָּנָא"]},"19606":{"h":"סְמָנוֹן","r":"O01118","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אֲמָנָה II\"><span dir=\"rtl\">אֲמָנָה</span> II</a></div>","alt":[]},"19607":{"h":"סַמָּנִיּוֹת","r":"O01119","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"סַמְמָנִית\">סמְמָנִית</a></div>","alt":[]},"19608":{"h":"סמניירין","r":"O01120","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"סִמְלוֹן\">סִמְלוֹן</a></div>","alt":["סמננין"]},"19609":{"h":"סְמָנִים","r":"O01121","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אֲמָנָה II\"><span dir=\"rtl\">אֲמָנָה</span> II</a></div>","alt":[]},"19610":{"h":"סמס","r":"O01122","html":"<div class=\"sense\">, Y. Shek. V, 48ᵈ, v. <a href=\"#\" data-headword=\"סְמֵי\">סְמֵי</a>.—<span class=\"citation\">Yalk. Is. 263</span> <span dir=\"rtl\">שמסמסין</span>, v. <a href=\"#\" data-headword=\"מִסְמֵס II\"><span dir=\"rtl\">מִסְמֵס</span> II</a>.</div>","alt":[]},"19611":{"h":"סמפולינא","r":"O01123","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"סִמְפּוֹרְיָינָא\">סִמְפּוֹרְיָינָא</a></div>","alt":[]},"19612":{"h":"סִמְפּוֹן","r":"O01124","html":"<div class=\"sense\">, v. sub <span dir=\"rtl\">סִימְפּ׳</span>.</div>","alt":["סִמְפּוֹנָא","סִמְפּוֹנְיָא","סִמְפֹּנְ׳"]},"19613":{"h":"סִמְפּוֹרְיָינָא","r":"O01125","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (v. next wds., a. b. h. <i>lapis lazuli</i>, a jewel in the high priest’s breastplate. Targ. Y. II XXVIII, 18 (some ed. <span dir=\"rtl\">סמפול׳</span>).</div>","alt":[]},"19614":{"h":"סִמְפּוֹרִין","r":"O01126","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"> (<span dir=\"rtl\">ספר</span>; cmp. <a href=\"#\" data-headword=\"צִפּוֹרֶן\">צִפּוֹרֶן</a>) <i>nails</i>, <i>points</i>. <span class=\"citation\">Targ. Is. XLI, 15</span>. <span class=\"citation\">Targ. I Chr. XX, 3</span> (ed. Rahm. <a href=\"#\" data-headword=\"סִיפּוֹרִין\">סִיפּוֹרִין</a>).</div>","alt":["סִימְ׳"]},"19615":{"h":"סמפירונין","r":"O01127","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"סַמְפִּירִינוֹן\">next w.</a></div>","alt":[]},"19616":{"h":"סַמְפִּירִינוֹן","r":"O01128","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (σαπφείρινον) <i>sapphir-like</i>; in gen. (= lapis sapphirinus) <i>sapphire</i>, <i>lapislazuli</i> (v. Sm. Ant. s. v. Sapphir). Tanḥ. Ki Thissa 26 <span dir=\"rtl\">ושל סמ׳ היו וכ׳</span> and they (the tablets) were lapislazuli, and yet they were like a light object in his hands; <span class=\"citation\">Cant. R. to V, 14</span> [read:] <span dir=\"rtl\">מעשה נסים היו של סנ׳ היו וכ׳</span> they were a miraculous work: they were of sapphire, and yet could be rolled up. Tanḥ. <span class=\"citation\">B’shall. 21</span> <span dir=\"rtl\">המטה של סמפר׳ היה</span> the staff (of Moses) was of sapphire; <span class=\"citation\">Ex. R. s. 8</span>. Pesik. ʿĂniya, p. 135ᵇ <span dir=\"rtl\">נאה כס׳ הזה</span> beautiful like sapphire. Ib. <span dir=\"rtl\">סמפ י̇ר̇ו׳</span> (corr. acc.); <span class=\"citation\">Pesik. R. s. 32</span>; (<span class=\"citation\">Lam. R. to IV, 7</span> <a href=\"#\" data-headword=\"סַפִּיר\">סַפִּיר</a>); a. fr.—<i>Chald.</i> <span class=\"citation\">Targ. Y. Deut. IV, 13</span>. <span class=\"citation\">Ib. XXXIV, 12</span>.</div>","alt":["סַנְפִּי׳","סַמְפִּרִ׳","סַנְפִּרִ׳"]},"19617":{"h":"סְמֵק","r":"O01129","html":"<div class=\"sense\"> (v. <a href=\"#\" data-headword=\"סוּמַּק\">סוּמַּק</a>) <i>to be red</i> (interch. with <i>Pa</i>. in Targ. editions). <span class=\"citation\">Targ. Y. Num. XXXI, 18</span>. <span class=\"citation\">Targ. Gen. XLIX, 12</span> (Ms. <span dir=\"rtl\">יְסוּמְקוּן</span>); a. fr.—<span class=\"citation\">B. Bath. 84ᵃ</span> <span dir=\"rtl\">דקא סָמְקָא וכ׳</span> for it (the sun) is red in the morning and in the evening; a. e.</div><div class=\"sense\"><b>Pa. סַמֵּיק</b> <div class=\"sense\"><b>1)</b>  <a href=\"#\" data-headword=\"סַמְפִּירִינוֹן\">same</a>, v. supra.—2) </div><div class=\"sense\"><i>to redden</i>. <span class=\"citation\">Targ. Y. Gen. XLIX, 11</span>.—<span class=\"citation\">Lev. R. s. 12</span> (expl. <span dir=\"rtl\">כי יתאדם</span>, <span class=\"citation\">Prov. XXIII, 31</span>) <span dir=\"rtl\">ודאי מְסַמֵּיק ליה</span> (or <span dir=\"rtl\">מַסְמִיק</span> <i>Hif.</i>) the wine will surely make him red (excite him). Y. Ḥag. II, 77ᵈ bot.; Y. Snh. VI, 23ᶜ <span dir=\"rtl\">בגין דלא מְסַמְּקָא אפוי</span> (not <span dir=\"rtl\">מסמקי</span>) in order not to make his face red (put him to shame); a. e.—<i>Part. pass.</i> <span dir=\"rtl\">מְסַמַּק</span>; pl. <span dir=\"rtl\">מְסַמְּקִין</span>, <span dir=\"rtl\">מְסַמְּקֵי</span>. <span class=\"citation\">Targ. Ex. XXVI, 14</span>. <span class=\"citation\">Targ. Nah. II, 4</span>; a. e.</div></div><div class=\"sense\"><b>Af. אַסְמֵיק</b> <div class=\"sense\"><b>1)</b> <i>to become</i> or <i>be dark red</i>. <span class=\"citation\">Ḥull. 93ᵇ</span>; <span class=\"citation\">Pes. 74ᵇ</span> <span dir=\"rtl\">אומצא דא׳</span> a piece of meat which is dark red (from congested blood). <span class=\"citation\">Ib.</span> <span dir=\"rtl\">בין א׳ בין לא א׳</span> whether the fluid looks red; a. e.</div><div class=\"sense\"><b>—2)</b> <i>to make red</i>, v. supra.</div></div>","alt":["סְמֵיק"]},"19618":{"h":"סַמְקָא","r":"O01130","html":"<div class=\"sense\"> c. (<a href=\"#\" data-headword=\"סְמֵק\">preced.</a>) <i>reddish</i>. <span class=\"citation\">Targ. Y. Lev. XIII, 43</span>.—Pl. <a href=\"#\" data-headword=\"סַמְקִי\">סַמְקִין</a>; f. <a href=\"#\" data-headword=\"סָמְקָן\">סַמְקָן</a>. <span class=\"citation\">Targ. O. Lev. XIV, 37</span> (Y. <span dir=\"rtl\">סומקן</span>).—<span class=\"citation\">Lam. R. to IV, 3</span> <span dir=\"rtl\">דלא … סמקין וכ׳</span> (not <span dir=\"rtl\">סמקון</span>; some ed. <span dir=\"rtl\">סימוקן</span>, corr. acc.) lest they see their young red-colored and eat them up.—<span class=\"citation\">Yalk. Prov. 960</span> <span dir=\"rtl\">סמקן דעיינין</span> inflammation of the eyes (<span class=\"citation\">Lev. R. s. 12</span> <a href=\"#\" data-headword=\"שִׁמְשְׁמִין\">שמשמין</a>).</div>","alt":[]},"19619":{"h":"סַמְקִי","r":"O01131","html":"<p class=\"morphology\">pr. n. pl.</p><div class=\"sense\"><i>Samḳi</i>. <span class=\"citation\">Yeb. 121ᵃ</span> <span dir=\"rtl\">אגמא דס׳</span> the swamp of S.</div>","alt":[]},"19620":{"h":"סָמְקָן","r":"O01132","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"סַמְקִי\">preced.</a> wds.) name of a <i>red jewel, carnelian</i>. <span class=\"citation\">Targ. O. Ex. XXVIII, 17</span>. <span class=\"citation\">Targ. Ez. XXVIII, 13</span>; a. e.</div>","alt":["סַ׳"]},"19621":{"h":"סַמְקְרָיי","r":"O01133","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"סְמוֹקְרִי\">סְמוֹקְרִי</a></div>","alt":[]},"19622":{"h":"סִמֻּקְתָּא","r":"O01134","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"סִימּוּק\">סִימּוּק</a></div>","alt":[]},"19623":{"h":"סַמְקְתָא","r":"O01135","html":"<div class=\"sense\"> f. = <a href=\"#\" data-headword=\"סָמְקָן\">סָמְקָן</a>. <span class=\"citation\">Targ. Y. II, Ex. XXVIII, 17</span> (not <a href=\"#\" data-headword=\"סַמְקָא\">סַמְקָ׳</a>); Y. I <a href=\"#\" data-headword=\"סִמּוּקְתָּא\">סִמּוּקְתָּא</a>.</div>","alt":[]},"19624":{"h":"סָמַר","r":"O01136","html":"<div class=\"sense\"> [(b. h.) <i>to stand erect, bristle</i>.—Denom. <a href=\"#\" data-headword=\"מַסְמָר\">מַסְמֵר</a>; whence <a href=\"#\" data-headword=\"סָמַר\">סָמַר</a>] <i>to nail, fasten</i>. <span class=\"citation\">Y. Meg. IV, 75ᶜ</span> bot. <span dir=\"rtl\">זְמָרוֹ</span> he nailed it (against the door, in an inappropriate place).</div><div class=\"sense\"><b>Pi. סִימֵּר</b> <div class=\"sense\"><i>to stud with nails.</i> <span class=\"citation\">Kel. XIV, 2</span>.—Part. pass. <a href=\"#\" data-headword=\"מְסוּמָּר\">מְסוּמָּר</a>. <span class=\"citation\">Sabb. VI, 2</span>, a. fr. <span dir=\"rtl\">סנדל המס׳</span> a nail-studded shoe.</div></div>","alt":[]},"19625":{"h":"סְמַר I","r":"O01137","html":"<div class=\"sense\"><i>Pa</i>. <a href=\"#\" data-headword=\"סָמַר\">סַמֵּר</a> same.—Part. pass. <a href=\"#\" data-headword=\"מַסְמָר\">מְסַמַּר</a>, <a href=\"#\" data-headword=\"מַסְמָר ²\">מְסַמְּרָא</a>. <span class=\"citation\">Y. Ḥag. III, beg. 78ᵈ</span> <span dir=\"rtl\">עד … כיפא מ׳</span> to this day it is called the nail-studded rock.</div>","alt":[]},"19626":{"h":"סְמַר II","r":"O01138","html":"<div class=\"sense\"> (= h. <a href=\"#\" data-headword=\"שָׁמַר\">שָׁמַר</a>), <i>Ithpa.</i> <a href=\"#\" data-headword=\"סְבַר\">אִסְתַּמַּר</a>, <span dir=\"rtl\">אִסְטַ׳</span> <i>to take heed, beware</i>. <span class=\"citation\">Targ. O. Ex. XXIII, 21</span>. <span class=\"citation\">Targ. Josh. VI, 18</span> (some ed. <span dir=\"rtl\">אסט׳</span>). <span class=\"citation\">Targ. Job XXXVI, 21</span> (Ms. <span dir=\"rtl\">אסט׳</span>); a. fr.—[<span class=\"citation\">Ib. XXXIV, 17</span>, v. <a href=\"#\" data-headword=\"סַמְתֵּר\">סַמְתֵּר</a>.]</div>","alt":[]},"19627":{"h":"סְמָרָאֵי","r":"O01139","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"><i>S’maraë</i> or <i>Samraë</i>, name of a Cushite tribe, prob. named from <i>Sabrata</i> (Abrotonum), in northern Africa; cmp. <a href=\"#\" data-headword=\"זִינְגָּאֵי\">זִינְגָּאֵי</a>. <span class=\"citation\">Targ. Y. Gen. X, 7</span> <span dir=\"rtl\">סְמִדָּ׳</span>; <span class=\"citation\">Targ. I Chr. I, 9</span> (ed. Rahmer <span dir=\"rtl\">סמד׳</span>; h. text <span dir=\"rtl\">סבתה</span>).</div>","alt":["סַמְרָאֵי"]},"19628":{"h":"סמרון","r":"O01140","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"סִימִירוֹן\">סימִירוֹן</a></div>","alt":[]},"19629":{"h":"סִמְרוֹסִי","r":"O01141","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"סִבְרוֹסִי\">סִבְרוֹסִי</a></div>","alt":[]},"19630":{"h":"סְמַרְטוּט","r":"O01142","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (Saf. of <a href=\"#\" data-headword=\"מָרַט\">מרט</a>; cmp. <a href=\"#\" data-headword=\"מַרְטוּט\">מַרְטוּט</a>) </div><div class=\"sense\"><b>1)</b> <i>rag, lint.</i> <span class=\"citation\">Sabb. XIX, 2</span>. <span class=\"citation\">Ib. XXI, 2</span>.—Pl. <span dir=\"rtl\">סְמַרְטוּטִין</span>. <span class=\"citation\">Shebu. 31ᵃ</span> <span dir=\"rtl\">אחד לבוש ס׳</span> one (of the contestants) clad in rags. <span class=\"citation\">Tosef. Bets. II, 11</span> <span dir=\"rtl\">לא יקרע לה ס׳</span> he must not tear rags (to dress the wound after circumcision). <span class=\"citation\">Tosef. Sabb. II, 1</span>; a. fr.</div><div class=\"sense\"><b>—2)</b>  (adj.) <i>ragged.</i>—<i>Pl.</i> as ab. <span class=\"citation\">Cant. R. to I, 5</span>; <span class=\"citation\">Yalk. ib. 982</span>.</div>","alt":[]},"19631":{"h":"סְמַרְטוּטָא","r":"O01143","html":"<div class=\"sense\">—Pl. <span dir=\"rtl\">סְמרְטוּטֵי</span>. <span class=\"citation\">Ber. 51ᵇ</span>, v. <a href=\"#\" data-headword=\"כַּלְמְתָא\">כַּלְמְתָא</a>.</div>","alt":[]},"19632":{"h":"סְמַרְטִין","r":"O01144","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"סְמַטְרְיָה\">סְמַטְרְיָה</a>) <i>Sarmatians</i>. Y’lamd. to Num. III, 45 (or VIII, 6) quot. in Ar. <span dir=\"rtl\">אפי׳ ס׳ אפי׳ ברבריים</span> (ed. Koh. <a href=\"#\" data-headword=\"סמריטין\">סמריטין</a>) even Sarmatians, even Barbarians; [perh. Samaritans, v. next w.].</div>","alt":[]},"19633":{"h":"סְמַרְטִיקִי","r":"O01145","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (Σαμαρειτική, sub. χώρα) <i>the Samaritan district</i>. <span class=\"citation\">Y. Ab. Zar. V, 44ᵈ</span> bot.</div>","alt":[]},"19634":{"h":"סמריטין","r":"O01146","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"סְמַרְטִין\">סְמַרְטִין</a></div>","alt":[]},"19635":{"h":"סְמַרְמוֹרוֹת","r":"O01147","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"סָמַר\">סָמַר</a>) <i>shudder</i>. <span class=\"citation\">Nidd. IX, 8</span> (<span class=\"citation\">63ᵃ</span>) Ar. [Var. in Ar. <a href=\"#\" data-headword=\"צְמַרְמוֹרוֹת\">צְמַרְמוֹרוֹת</a>; Mish. ed. <a href=\"#\" data-headword=\"צְמַרְמוֹרֶת\">צמרמורת</a>; Bab. ed. <a href=\"#\" data-headword=\"צְמַרְמוֹרוֹת\">צמרמורות</a>).</div>","alt":[]},"19636":{"h":"סַמְתּוֹרָא","r":"O01148","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (comp. of <a href=\"#\" data-headword=\"סַם\">סַם</a> a. <a href=\"#\" data-headword=\"תַּוָּרָא\">תורא</a>, v. <a href=\"#\" data-headword=\"תְּרֵי\"><span dir=\"rtl\">תְּרָא</span> I</a>; cmp. P. Sm. 2653 <span dir=\"rtl\">סם תרין</span>) <i>an emollient</i>, esp. <i>cosmetics</i>. <span dir=\"rtl\">סַמְתַּר משחא</span>, <span dir=\"rtl\">ס׳ רבותא</span> <i>cosmetic ointments</i> (v. <a href=\"#\" data-headword=\"מְשַׁח III\">מִשְׁחָא</a> I a. <a href=\"#\" data-headword=\"רְבוּתָא\">רְבוּתָא</a>). <span class=\"citation\">Targ. Esth. II, 3</span>; <span class=\"citation\">9</span>.—Pl. constr. <a href=\"#\" data-headword=\"סַמְתּוֹרָא\">סַמְתּוֹרֵי</a>. <span class=\"citation\">Ib. 12</span>.</div>","alt":["סַמְתָּרָא"]},"19637":{"h":"סַמְתֵּירָא","r":"O01149","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"סַמְתּוֹרָא\">preced.</a>) <i>an emollient</i> put on a sore, <i>plaster.</i> <span class=\"citation\">Targ. Job V, 18</span> <span dir=\"rtl\">מָעֵל ס׳</span> (Bxt. <a href=\"#\" data-headword=\"סַמְתַּרְתָּא\">סַמְתַּרְתָּא</a>; h. text <span dir=\"rtl\">חבש</span>).—V. <a href=\"#\" data-headword=\"סַמְתְּרֵי\">סַמְתְּרֵי</a>.</div>","alt":[]},"19638":{"h":"סַמְתַּר","r":"O01150","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"סַמְתּוֹרָא\">סַמְתּוֹרָא</a></div>","alt":[]},"19639":{"h":"סַמְתֵּר","r":"O01151","html":"<div class=\"sense\"> (<a href=\"#\" data-headword=\"סַמְתַּר\">preced.</a> wds.) <i>to apply an emollient, to heal</i>. <span class=\"citation\">Targ. Job XXXIV, 17</span> <span dir=\"rtl\">יְסַמְתֵּר</span> ed. Lag. (ed. <span dir=\"rtl\">יסתמר</span>, Ms. <span dir=\"rtl\">יסטמר</span>; corr. acc.; h. text <span dir=\"rtl\">יחבוש</span>; cmp. <a href=\"#\" data-headword=\"סַמְתֵּירָא\">סַמְתֵּירָא</a>). [As regards formation of a verb from a compound noun, cmp. <a href=\"#\" data-headword=\"בַּרְנֵשׁ\">ברנש</a>, P. Sm. 582.]</div>","alt":[]},"19640":{"h":"סַמְתְּרֵי","r":"O01152","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"סַמְתֵּר\">preced.</a> wds.) <i>a vulnerary preparation; dragon’s-blood</i>. <span class=\"citation\">B. Mets. 107ᵇ</span> הוו עבדי ליה ס׳ וכ׳ Ms. M. a. Ar. ed. Koh. (ed. <a href=\"#\" data-headword=\"סַמָּא I\">סַמָּא</a>; Ar. ed. <span dir=\"rtl\">סמתר</span>) they might prepare <i>samtré</i>, and he might recover; <span class=\"citation\">Yalk. Deut. 849</span>; <span class=\"citation\">Yeb. 114ᵇ</span> (Rashi <a href=\"#\" data-headword=\"סַמְתֵּירָא\">סַמְתֵּירֵי</a>). <span class=\"citation\">B. Bath. 74ᵇ</span> <span dir=\"rtl\">ההוא עישבא ס׳ היה</span> (Ar. <span dir=\"rtl\">הנך עישבי ס׳ הוו</span>, v. Rabb. D. S. a. l. note 8) that plant was <i>s.</i>—<span class=\"citation\">Ḥull. 54ᵃ</span> quot. in Rashbam to B. Bath. l. c. <span dir=\"rtl\">עבדי לה ס׳</span> (ed. <span dir=\"rtl\">בדרי לה סמא</span>).</div>","alt":[]},"19641":{"h":"סַמְתַּרְתָּא","r":"O01153","html":"<div class=\"sense\"> f., v. <a href=\"#\" data-headword=\"סַמְתֵּירָא\">סַמְתֵּירָא</a></div>","alt":[]},"19642":{"h":"סֵן","r":"O01154","html":"<div class=\"sense\"> (<span dir=\"rtl\">סנן</span>, cmp. <a href=\"#\" data-headword=\"סְנֶה\">סְנֶה</a> a. <a href=\"#\" data-headword=\"שֵׁן\">שֵׁן</a>) <i>tenon</i>.—Pl. <a href=\"#\" data-headword=\"סִינִּים\">סִינִּים</a>, <a href=\"#\" data-headword=\"סִינִּים\">סִינִּין</a>. <span class=\"citation\">Kel. X, 6</span> <span dir=\"rtl\">עשאן בס׳</span> (Mish. ed. <a href=\"#\" data-headword=\"סָנַן\">סינן</a>, corr. acc.) if he joined the boards by means of tenons, Maim. (R. S.: by placing between them <i>fine chips of thornwood</i>, v. <a href=\"#\" data-headword=\"סְנֶה\">סְנֶה</a>).</div>","alt":[]},"19643":{"h":"סַנָּא","r":"O01155","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"סַנּוֹא\">סַנּוֹא</a></div>","alt":[]},"19644":{"h":"סָנֵא","r":"O01156","html":"<div class=\"sense\"><i>to hate</i>, v. <a href=\"#\" data-headword=\"סני\">סני</a>.</div>","alt":["סְנָא"]},"19645":{"h":"סָנָא","r":"O01157","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"סָנֵא\">preced.</a>) <i>hatred</i>. <span class=\"citation\">Targ. Y. Ex. XXIII, 5</span>. <span class=\"citation\">Targ. Y. Num. XXXV, 20</span> <a href=\"#\" data-headword=\"בִּיסְנָא\">ביסְנָא</a>. <span class=\"citation\">Targ. Y. Gen. XXVII, 41</span>; a. e.</div>","alt":["סְנָא"]},"19646":{"h":"סִנְאָב","r":"O01158","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"סְנָאָה\">סְנָאָה</a></div>","alt":[]},"19647":{"h":"סִנְאָה","r":"O01159","html":"<div class=\"sense\"> f. = <a href=\"#\" data-headword=\"סָנָא\">סָנָא</a>. <span class=\"citation\">Targ. O. Num. XXXV, 20</span> ed. Berl. (ed. Amst. <a href=\"#\" data-headword=\"סָהֲדָא\">סַ׳</a>, corr. acc.).—V. <a href=\"#\" data-headword=\"סִנְאֲתָא\">סִנְאֲתָא</a></div>","alt":[]},"19648":{"h":"סַנְאָה","r":"O01160","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"סִנְאָה\">preced.</a>) <i>hater</i>, <i>enemy</i>. <span class=\"citation\">Targ. Ex. XXIII, 5</span>. Targ. II Esth. VI, 10; a. e.—<span class=\"citation\">Y. Ber. II, 5ᵃ</span> top <span dir=\"rtl\">סַנְאֵיהוֹן דישראל</span> the enemy of Israel. <span class=\"citation\">Ḥull. 43ᵇ</span> (euphem.) <span dir=\"rtl\">כלפי סַנְאֵיה דרבא</span> (not <span dir=\"rtl\">סנאוה</span>) against (the enemy of) Raba.—Pl. <a href=\"#\" data-headword=\"סְנָאִים\">סַנְאִין</a>, <span dir=\"rtl\">סַנְאַיָּא</span>, <a href=\"#\" data-headword=\"סְנָאֵי\">סַנְאֵי</a>. <span class=\"citation\">Targ. Ps. XXXV, 19</span> (ed. Wil. <a href=\"#\" data-headword=\"סְנָאֵי\">סָנְאַי</a>). <span class=\"citation\">Targ. Ex. I, 10</span>. <span class=\"citation\">Targ. Ps. CXXIX, 5</span> (Ms. <a href=\"#\" data-headword=\"סְנָאֵי\">סַנְאֵי</a>; some ed. <a href=\"#\" data-headword=\"סַנֵּי\">סַנֵי</a>). <span class=\"citation\">Ib. XLV, 6</span> (some ed. <a href=\"#\" data-headword=\"סָהֲדָא\">שַׂ׳</a>); a. e.—<span class=\"citation\">Y. Taan. IV, 68ᵈ</span> <span dir=\"rtl\">שַׂנְאַיָּיא</span>.—V. <a href=\"#\" data-headword=\"שַׂנְאוּתָא\">שַׂנְאוּתָא</a>.</div>","alt":[]},"19649":{"h":"סְנָאָה","r":"O01161","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"><i>S’naah</i>. <span class=\"citation\">Taan. IV, 5</span> (<span class=\"citation\">26ᵃ</span>) <span dir=\"rtl\">בני ס׳</span> (Ms. M. <a href=\"#\" data-headword=\"שִׁנְאָב\">שִׁנְאָב</a>; v. Rabb. D. S. a. l. note); Y. ib. IV, 68ᵇ bot.; Tosef. ib. IV (III), 6 ed. Zuck. (Var. <span dir=\"rtl\">סניאה</span>); Bab. ib. 12ᵃ <a href=\"#\" data-headword=\"סִנְאָב\">סִנְאָב</a> (Ms. M. <a href=\"#\" data-headword=\"ש׳\">ש׳</a>); <span class=\"citation\">Erub. 41ᵃ</span> <a href=\"#\" data-headword=\"סִנְאָב\">סנאב</a> (Ms. O. <span dir=\"rtl\">סנאה</span>).</div>","alt":[]},"19650":{"h":"סְנָאֵי","r":"O01162","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"סְנֵי\">סְנֵי</a></div>","alt":[]},"19651":{"h":"סְנָאִים","r":"O01163","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"סְנֶה\">סְנֶה</a></div>","alt":["סְנָאִין"]},"19652":{"h":"סִנְאֲתָא","r":"O01164","html":"<div class=\"sense\"> f. = <a href=\"#\" data-headword=\"סִנְאָה\">סִנְאָה</a>. <span class=\"citation\">Targ. II Sam. XIII, 15</span> (ed. Wil. <a href=\"#\" data-headword=\"סִנְאֲתָא\">סִנְאָתָא</a>). <span class=\"citation\">Targ. Ps. CIX, 5</span> (ed. Lag. <a href=\"#\" data-headword=\"סְנֵיתָא\">סְנִיתָא</a>). <span class=\"citation\">Ib. 3</span> <a href=\"#\" data-headword=\"סָנוּתָא\">סָנוּתָא</a>. <span class=\"citation\">Targ. Prov. XXVI, 26</span> <a href=\"#\" data-headword=\"סְנוּאֲתָא\">סְנוּאֲתָא</a> (ed. Lag. <a href=\"#\" data-headword=\"סְנִיאֲתָא\">סְנִיאֲתָא</a>; Ms. <a href=\"#\" data-headword=\"סִינְוָותָא\">סִינְוָותָא</a>).</div>","alt":[]},"19653":{"h":"סַנְבּוּטִין","r":"O01165","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"סַרְבִיטִין\">סַרְבִּיטִין</a></div>","alt":[]},"19654":{"h":"סִנְבּוּל","r":"O01166","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"סִיבּוֹלֶת\">סִיבּוֹלֶת</a></div>","alt":[]},"19655":{"h":"סַנְבַּטְיוֹן","r":"O01167","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"סַמְבַּטְיוֹן\">סמְבַּטְיוֹן</a></div>","alt":[]},"19656":{"h":"סִנַּבְרַאי","r":"O01168","html":"<p class=\"morphology\">pr. n. pl.</p><div class=\"sense\"><i>Sennabris</i>, near the lake of Tiberias. <span class=\"citation\">Gen. R. s. 98</span>; Y. Meg. I, 70ᵃ <span dir=\"rtl\">צי׳</span>; v. <a href=\"#\" data-headword=\"יֶרַח\">יֶרח</a>. Ib. III, 74ᵃ top Ursicinus burnt <span dir=\"rtl\">אורייתא דצנבראי</span> the Torah scroll (of the synagogue) of S.—Denom. <span dir=\"rtl\">סִנַּבְרָיָא</span>, <a href=\"#\" data-headword=\"סִנַּבְרַאי\">צִנַּ׳</a>, <a href=\"#\" data-headword=\"סִנַּבְרַאי\">צִינַּ׳</a>. <span class=\"citation\">Y. Shebi. VI, 36ᵈ</span>; ib. IX, 39ᵃ; Y. Ab. Zar. II, end, 42ᵃ <span dir=\"rtl\">לוי צ׳</span>.</div>","alt":["צִנַּ׳","צִנַּבְרַיי","צִינַּ׳"]},"19657":{"h":"סנגדא","r":"O01169","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"סַנִּיגוֹרָא\">סַנִּיגוֹרָא</a></div>","alt":[]},"19658":{"h":"סנגדודין","r":"O01170","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"סִנְגְּלָרִין\">סִנְגְּלָרִין</a></div>","alt":[]},"19659":{"h":"סנגוריא","r":"O01171","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"סְרוּנְגָּיָא\">סְרוּנְגָּיָא</a></div>","alt":[]},"19660":{"h":"סנגורין","r":"O01172","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"סִנְגְּלָרִין\">next w.</a></div>","alt":[]},"19661":{"h":"סִנְגְּלָרִין","r":"O01173","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"> (variously corrupted) <i>singulares, orderlies in the army</i>; (under the later Roman emperors) <i>imperial clerks in the provinces</i>. <span class=\"citation\">Yalk. Num. 771</span> <span dir=\"rtl\">גירה בהן הס׳</span> he set the singulares on them, and they crushed their heads with clubs (v. Sm. Ant. s. v. Fustuarium); <span class=\"citation\">Sifré Num. 131</span> <span dir=\"rtl\">סנגדודים</span>, <span dir=\"rtl\">סנגרורים</span>; <span class=\"citation\">Y. Snh. X, 28ᵈ</span> bot. <span dir=\"rtl\">סניגורים</span> (corr. acc.).—Y’lamd. to Num. X, 2 quot. in Ar. s. v. <span dir=\"rtl\">סגנם</span>: <span dir=\"rtl\">מה עשו הסניגורים</span> (corr. acc., or <span dir=\"rtl\">סִגְנִיפִירִים</span> signiferi?).</div>","alt":[]},"19662":{"h":"סַנְגָּרָא","r":"O01174","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"סַנִּיגוֹרָא\">סַנִּיגוֹרָא</a></div>","alt":[]},"19663":{"h":"סנגרורין","r":"O01175","html":"<div class=\"sense\">, corruptions of <a href=\"#\" data-headword=\"סִנְגְּלָרִין\">סִנְגְּלָרִין</a>.</div>","alt":["סנגרין"]},"19664":{"h":"סנדיות","r":"O01176","html":"<div class=\"sense\">, read: <a href=\"#\" data-headword=\"סִגָּרִיוֹת\">סִגָּרִיּוֹת</a>.</div>","alt":[]},"19665":{"h":"סִנְדִּיקוֹס","r":"O01177","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"סִינְדִּיקְנוֹס\">סִינְדִּיקְנוֹס</a></div>","alt":["סנדיקות","סִנְדִּיקְנוֹס"]},"19666":{"h":"סַנְדָּל","r":"O01178","html":"<div class=\"sense\"> c. (σάνδαλον, prob. from Pers. <i>sandal</i> = calceus) <i>sandal</i>, </div><div class=\"sense\"><b>1)</b> <i>a sole with straps, shoe</i>, contrad. to <a href=\"#\" data-headword=\"מַנְעָל\">מַנְעָל</a> a. <a href=\"#\" data-headword=\"נַעַל\">נַעַל</a>. <span class=\"citation\">Sabb. VI, 2</span>, v. <a href=\"#\" data-headword=\"סָמַר\">סָמַר</a>. <span class=\"citation\">Yoma VIII, 1</span>. <span class=\"citation\">Yeb. 102ᵃ</span>; a. fr.—<span dir=\"rtl\">ס׳ של בהמה</span> a sort of shoe for animals (v. Sm. Ant., 3rd Engl. ed., s. v. Solea). <span class=\"citation\">Sabb. 59ᵃ</span> <span dir=\"rtl\">ס׳ של וכ׳</span> a metal shoe for animals is liable to levitical uncleanness (expl. ‘because it may be used as a drinking vessel in war’ &amp;c.); <span class=\"citation\">Kel. XIV, 5</span> <span dir=\"rtl\">סַנְדְּלֵי בהמה</span> (pl.). <span class=\"citation\">Par. II, 3</span> <span dir=\"rtl\">עשה לה ס׳ וכ׳</span> if one made a shoe for her (the red cow), that she might not slip.—ס׳ של עריסה <i>a sort of shoe for the legs of a bedstead</i>; [Ar.: <i>a board placed under a short leg</i>]. Ohol. XII, 4; Tosef. ib. XIII, 4.—<span class=\"citation\">Yeb. 103ᵇ</span> ס׳ של נחת ע&quot;ז Ar. (ed. <span dir=\"rtl\">ס׳ של ע&quot;ז</span>) the shoe for the rest of an idol.—Pl. <span dir=\"rtl\">סַנְדָּלִין</span>. <span class=\"citation\">B. Bath. 58ᵃ</span> ‘the bed of a scholar’ is <span dir=\"rtl\">כל שאין … ס׳ וכ׳</span> that under which nothing is placed except the sandals in summer and shoes in winter time. <span class=\"citation\">Y. Sabb. VI, 8ᵃ</span>; a. fr.</div><div class=\"sense\"><b>—2)</b> <i>a flat fish</i> like <i>the sole</i> or <i>turbot</i>; trnsf. <i>a flat, fish-shaped abortion</i>. <span class=\"citation\">Nidd. III, 4</span> <span dir=\"rtl\">המפלת ס׳ וכ׳</span> a woman who discharges a sandal-like foetus or a placenta. <span class=\"citation\">Tosef. ib. IV, 7</span> <span dir=\"rtl\">ס׳ שאמרו דומה לס׳ דג שבים</span> the sandal abortion of which they speak means a foetus resembling the sea-fish called sandal; [oth. opin.] <span dir=\"rtl\">דומה ללשון של שור</span> resembling the fish called ‘oxtongue’ (βοὐγλοσσος, lingulaca); Y.ib. ib. III, 50ᵈ bot.; Bab. ib. 25ᵇ; a. e. [<span class=\"citation\">Snh. 59ᵇ</span> סנדלין Ms. M., v. <a href=\"#\" data-headword=\"סַנְדַּלְכוֹנִים\">סנְדֵּלְכוֹנִים</a>.]</div>","alt":[]},"19667":{"h":"סַנְדְּלָא","r":"O01179","html":"<div class=\"sense\"> <span class=\"citation\">Targ. Y. I Gen. XIV, 23</span> <span dir=\"rtl\">סַנְדְּלַת רצועא</span> a sandal provided with straps; Y. II <span dir=\"rtl\">רצועה דס׳</span> a shoe-strap. <span class=\"citation\">Targ. Ps. CVIII, 10</span>; a. fr.—<span class=\"citation\">Gen. R. s. 44</span>; <span class=\"citation\">Yalk. Jer. 285</span> <span dir=\"rtl\">עד דסַנְדְּלָךְ וכ׳</span>, v. <a href=\"#\" data-headword=\"כּוּבָּא I\"><span dir=\"rtl\">כּוּבָּא</span> I</a>. <span class=\"citation\">Yeb. 102ᵃ</span>, v. <a href=\"#\" data-headword=\"טַיְיעָא\">טַיְיעָא</a>. <span class=\"citation\">Snh. 7ᵇ</span> <span dir=\"rtl\">אפיקו לי מאני חנותאי … וס׳</span> get me my shop-tools (the judge’s implements): a stick, a strap, a trumpet (with which to proclaim excommunication) and a sandal (for <a href=\"#\" data-headword=\"חֲלִיצָה\">חֲלִיצָה</a>); a. fr.—Pl. <span dir=\"rtl\">סַנְדְּלִין</span>, <span dir=\"rtl\">סַנְדְּלַיָּא</span>. <span class=\"citation\">Targ. Is. XI, 15</span>. <span class=\"citation\">Targ. Y. Gen. XXXVII, 28</span> (cmp. <span class=\"citation\">Am. II, 6</span>); a. e.—Y. Sabb. VI, 8ᵃ top <span dir=\"rtl\">תרין ס׳</span> two pairs of shoes. <span class=\"citation\">Lam. R. to I, 1</span> <a href=\"#\" data-headword=\"רַבָּתִי\">רבתי</a> (חד מאת׳ 8); a. e.</div>","alt":["סַנְדַּלָּא"]},"19668":{"h":"סנדלבונין","r":"O01180","html":"<div class=\"sense\">, v. next wds.</div>","alt":["סנדלבין"]},"19669":{"h":"סַנְדַּלְכוֹן","r":"O01181","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (a corrupt. of σαρδόνυξ, σαρδόνυχος) <i>sardonyx</i>. <span class=\"citation\">Targ. Job XXVIII, 18</span> (h. text <span dir=\"rtl\">ראבות</span>).</div>","alt":[]},"19670":{"h":"סַנְדַּלְכוֹנִים","r":"O01182","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\">, in gen. <i>gems</i>. <span class=\"citation\">Snh. 59ᵇ</span> <span dir=\"rtl\">סנדלב׳ טובים</span> ed. (ed. Cracow <a href=\"#\" data-headword=\"סַנְדַּלְכִין\">סַנְדַּלְכָנִין</a>; Ms. M. <span dir=\"rtl\">סנדלין</span>; Ms. C. <span dir=\"rtl\">סנדלנין</span>; corr. acc.; v. Rabb. D. S. a. l. note); <span class=\"citation\">Yalk. Gen. 15</span> <a href=\"#\" data-headword=\"סנדלפונין\">סנדלפונין</a>; Ab. d’R. N., ed. Schechter, ch. I <span dir=\"rtl\">סנדלכים</span>. Ib. ch. XXXVIII <span dir=\"rtl\">פה שמוציא סנדלפונין טובות</span> the mouth which uttered beautiful gems.</div>","alt":["סַנְדַּלְכוֹנִין"]},"19671":{"h":"סַנְדַּלְכִין","r":"O01183","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"סַנְדַּלְכוֹנִים\">preced.</a></div>","alt":["סַנְדַּלְכָנִין"]},"19672":{"h":"סַנְדַּלְפוֹן","r":"O01184","html":"<p class=\"morphology\">pr. n.</p><div class=\"sense\"><i>Sandalfon</i>, name of an angel. <span class=\"citation\">Ḥag. 13ᵇ</span>. <span class=\"citation\">Pesik. R. s. 20</span> <span dir=\"rtl\">אשו של ס׳</span> the fire of S.</div>","alt":[]},"19673":{"h":"סנדלפונין","r":"O01185","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"סַנְדַּלְכוֹנִים\">סַנְדַּלְכוֹנִים</a></div>","alt":[]},"19674":{"h":"סַנְדְּלָר","r":"O01186","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (sandalarius) <i>sandal-maker</i>, surname of R. Johanan; [oth. opin.: <a href=\"#\" data-headword=\"ס׳\">ס׳</a> = <a href=\"#\" data-headword=\"אֲלֶכְסַנְדְּרִי\">אלכסנדרי</a>, <i>the Alexandrian</i>; v. <span class=\"citation\">Y. Ḥag. III, beg. 78ᵈ</span> ר׳ י׳ הס׳ אלכסנדרי וכ׳ R. J. the Sand’lar is a true Alexandrian]. <span class=\"citation\">Ab. IV, 11</span>; a. v. fr.</div>","alt":[]},"19675":{"h":"סנדלריאות","r":"O01187","html":"<div class=\"sense\">, <span class=\"citation\">Yalk. Gen. 79</span>, read: <span dir=\"rtl\">בַּלְנַרְיָאוֹת</span>, v. <a href=\"#\" data-headword=\"בַּנְּרִיּוֹת\">בַּנְּרִיּוֹת</a></div>","alt":[]},"19676":{"h":"סַנְדְּלַת","r":"O01188","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"סַנְדְּלָא\">סַנְדְּלָא</a></div>","alt":[]},"19677":{"h":"סַנְדְּרוֹס","r":"O01189","html":"<div class=\"sense\">, abbrev. of <a href=\"#\" data-headword=\"אֲלֶכְסַנְדְּרוֹס\">אֲלֶכְסַנְדְּרוֹס</a>. <span class=\"citation\">Ex. R. s. 15</span>, v. <a href=\"#\" data-headword=\"*אִילִיאוֹס\">אִילִיאוֹס</a>.</div>","alt":["סַנְדְּרִיאוֹס"]},"19678":{"h":"סַנְדְּרֵי","r":"O01190","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"סַנְהֶדְרֵי\">סַנְהֶדְרִין</a> h. a. ch.—[<a href=\"#\" data-headword=\"סַנְדְּרֵי\">סנדריות</a>, Sifra B’har, Par. 2, ch. III, v. <a href=\"#\" data-headword=\"אָכְסִיגָרוֹן\">אָכְסִיגָרוֹן</a>.]</div>","alt":["סַנֶּדְרָאוֹת","סַנֶּדְרָיוֹת","סַנְדַּרְיָיתָא"]},"19679":{"h":"סַנְדַּרְיָיתָא","r":"O01191","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"סַנְהֶדְרֵי\">סַנְהֶדְרִין</a> ch.</div>","alt":[]},"19680":{"h":"סנדרנא","r":"O01192","html":"<div class=\"sense\">, <span class=\"citation\">Cant. R. to IV, 4</span> <span dir=\"rtl\">ע&quot;י ס׳</span>, a corrupt dittography of <span dir=\"rtl\">ע&quot;י שני שדיך</span>.</div>","alt":[]},"19681":{"h":"סְנֶה","r":"O01193","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (b. h.) <i>prick, thorn, thorn-bush</i>. <span class=\"citation\">Ex. R. s. 2</span>; Tanḥ. Sh’moth 14 (expl. <span dir=\"rtl\">בלבת</span>, <span class=\"citation\">Ex. III, 2</span>) <span dir=\"rtl\">משני חלקיו של ס׳</span> (from the heart of) from upward of two thirds of the height of the thorn-bush. Ib. <span dir=\"rtl\">הם … אף אני בס׳ וכ׳</span> they (the Israelites) are in anguish, I (the Lord) also appear in the thorn-bush, out of a narrow place. Ex. R. l. c. <span dir=\"rtl\">מה הסנה שפל וכ׳</span> as the thorn-bush is the lowest of the trees, so are the Israelites &amp;c.; a. fr.—Pl. <a href=\"#\" data-headword=\"סְנָאִים\">סְנָאִים</a>, <a href=\"#\" data-headword=\"סְנָאִים\">סְנָאִין</a>, <a href=\"#\" data-headword=\"סְנָאִים\">סְנָיִים</a>, <a href=\"#\" data-headword=\"סְנָאִים\">סְנָיִין</a>. <span class=\"citation\">Kil. VIII, 5</span>, a. e. <span dir=\"rtl\">חוּלְדַּת הס׳</span>, v. <a href=\"#\" data-headword=\"חוּלְדָּה I\"><span dir=\"rtl\">חוּלְדָּה</span> I</a>. Tanḥ. Ki Thissa 2 <a href=\"#\" data-headword=\"סגיין\">סגיין</a> (corr. acc.). <span class=\"citation\">B. Mets. 117ᵃ</span> (expl. <a href=\"#\" data-headword=\"תִּקְרָה\">תקרה</a>) <span dir=\"rtl\">קינים ס׳ וטינא</span> Ar. (ed. <span dir=\"rtl\">קינים וס׳</span>) he must furnish reeds, thorns and clay (for the ceiling).—<span class=\"citation\">Y. Meg. I, 72ᵈ</span> top <span dir=\"rtl\">בסנאיו של יוסף</span>, v. <a href=\"#\" data-headword=\"סַנּוֹא\">סַנּוֹא</a>.]</div>","alt":[]},"19682":{"h":"סנדריוטי","r":"O01194","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"סְרַדְיוֹט\">סְרַדְיוֹט</a></div>","alt":[]},"19683":{"h":"סַנְהֶדְרֵי","r":"O01195","html":"<p class=\"morphology\">f.</p><div class=\"sense\">(also <i>pl.</i>) (συνέδριον) <i>Sanhedrin</i>, the supreme council of the Jews; <span dir=\"rtl\">ס׳ גדולה</span> <i>the Great S.</i>, consisting of seventy-one members; <span dir=\"rtl\">ס׳ קטנה</span> <i>the Small S.</i>, a judicial court of twenty-three. <span class=\"citation\">Snh. I, 6</span>. Ib. <span dir=\"rtl\">ראויה לס׳</span> fit to be a seat of the S. <span class=\"citation\">Macc. I, 10</span> <span dir=\"rtl\">ס׳ נוהגת בארץ וכ׳</span> the S. may exercise its functions in Palestine and outside. Ib. <span dir=\"rtl\">ס׳ ההורגת וכ׳</span> a S. that executes capital punishment (more than) once in seven years. Ib. 9 (ref. to <span class=\"citation\">Deut. XVII, 6</span>) <span dir=\"rtl\">שלא תהא ס׳ שומעת וכ׳</span> this intimates that the S. must not hear the testimony from the mouth of an interpreter. <span class=\"citation\">Snh. 63ᵃ</span> <span dir=\"rtl\">לס׳ שהרגו וכ׳</span> that a S. which puts a person to death must not taste food during the entire day of execution; a. v. fr.—Pl. <span dir=\"rtl\">סַנְהֶדְרָיוֹת</span>, <span dir=\"rtl\">סַנְהֶדְרָאוֹת</span>, <span dir=\"rtl\">סַנֶּדְרָ׳</span>. <span class=\"citation\">Ib. I, 5</span> <span dir=\"rtl\">אין עושין ס׳ לשבטים וכ׳</span> supreme courts for tribes (provincial courts, Small Sanhedrin) can be instituted only by decree of the court of seventy-one; Sifra K’dosh. ch. VIII, Par. 10 <span dir=\"rtl\">סנדריות של ישראל</span>; Yalk. Lev. 619 <span dir=\"rtl\">סנהד׳ של שבטים</span>, opp. <span dir=\"rtl\">ס׳ גדולה</span>. <span class=\"citation\">Snh. 16ᵇ</span> <span dir=\"rtl\">כנדראות</span> (also in Chald. diction); a. fr.—<i>Sanhedrin</i>, name of a treatise, of the Order of N’ziḳin, of Mishnah, Toseftaand Talmud Babli a. Y’rushalmi.</div>","alt":["סַנְהֶדְרִין"]},"19684":{"h":"סַנְהֶדְרִי","r":"O01196","html":"<div class=\"sense\"> <span class=\"citation\">Targ. Y. II, Num. XXV, 4</span>. Targ. Y. I ib. 7. <span class=\"citation\">Targ. I Chr. XVIII, 17</span>; a. fr.—<span class=\"citation\">Snh. 16ᵃ</span>; a. fr.—Pl. <span dir=\"rtl\">סַנְהֶדְרְיָיתָא</span>, <a href=\"#\" data-headword=\"סַנְדַּרְיָיתָא\">סַנְדַּרְיָיתָא</a>. <span class=\"citation\">Targ. Y. I Lev. XXIV, 12</span>. <span class=\"citation\">Targ. Y. I Num. IX, 8</span>; a. fr.</div>","alt":["סַנְהֶדְרִין","סַנְדְּרִי"]},"19685":{"h":"סַנּוֹא","r":"O01197","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"סָנֵא\">סָנֵא</a> = <a href=\"#\" data-headword=\"שָׂנֵא\">שָׂנֵא</a>; cmp. <a href=\"#\" data-headword=\"קַנָּא\">קַנָּא</a> a. <span dir=\"rtl\">קַנּוֹא</span>) <i>hater.</i>—Pl. <span dir=\"rtl\">סַנּוֹאִין</span>, <a href=\"#\" data-headword=\"סְנָאִים\">סַנָּאִין</a>. <span class=\"citation\">Zeb. 118ᵇ</span> (ref. to <span class=\"citation\">Deut. XXXIII, 16</span>, play on <a href=\"#\" data-headword=\"סְנֶה\">סְנֶה</a>) <span dir=\"rtl\">עין … מן הס׳ שלו</span> Ms. M. (ed. <span dir=\"rtl\">בין השנואין</span>, v. Rabb. D. S. a. l. note) the eye (of Joseph) which refused to enjoy that which was not its own, shall be permitted to feast on that which belongs to his haters (the brother tribes); <span class=\"citation\">Yalk. Josh. 29</span>; <span class=\"citation\">Y. Meg. I, 72ᵈ</span> top <span dir=\"rtl\">ששרת שכינה בסַנָּאָיו של יוסף</span> the Divine Presence dwelt among Joseph’s haters.</div>","alt":["סַנָּא"]},"19686":{"h":"סַנְוַארְתָּה","r":"O01198","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"סַנְוַורְתָּא\">סַנְוַורְתָּא</a></div>","alt":[]},"19687":{"h":"סְנוּאֲתָא","r":"O01199","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"סְנֵי\">סְנֵי</a>) </div><div class=\"sense\"><b>1)</b> <i>the hated wife</i>. <span class=\"citation\">Targ. O. Deut. XXI, 15</span> <a href=\"#\" data-headword=\"ס׳\">ס׳</a> ed. Berl. (oth. ed. <span dir=\"rtl\">שְׂנוּאֲ׳</span>, a. <span dir=\"rtl\">שְׂנִיאֲ׳</span>; Y. <a href=\"#\" data-headword=\"סְנוּתָא\">סְנוּתָא</a>, a. <a href=\"#\" data-headword=\"סְנֵיתָא\">סְנֵיתָא</a>, <span dir=\"rtl\">סְנִי׳</span>). <span class=\"citation\">Targ. O. Gen. XXIX, 33</span> <a href=\"#\" data-headword=\"ס׳\">ס׳</a> ed. Berl. (oth. ed. <a href=\"#\" data-headword=\"סוֹכָה\">שׂ׳</a>; Y. <a href=\"#\" data-headword=\"שָׂנֵיתָא\">שָׂנֵיתָא</a>). <span class=\"citation\">Targ. Prov. XXX, 23</span> <span dir=\"rtl\">שנוא׳</span> (ed. Lag. <a href=\"#\" data-headword=\"שְׂנִיר\">שְׂנִי׳</a>); a. e.</div><div class=\"sense\"><b>—2)</b> <i>hatred</i>, v. <a href=\"#\" data-headword=\"סִנְאֲתָא\">סִנְאֲתָא</a>.</div>","alt":["שְׂ׳"]},"19688":{"h":"סַנְוֵור","r":"O01200","html":"<div class=\"sense\"> (Saf. of <span dir=\"rtl\">נור</span>; cmp. <a href=\"#\" data-headword=\"חִיוַּרְוָרַיָּא\">חִיוַּרְוָרַיָּא</a>) <i>to dazzle, blind</i>. <span class=\"citation\">Targ. Y. Num. XVI, 14</span>.</div>","alt":[]},"19689":{"h":"סַנְוַורְתָּא","r":"O01201","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"סַנְוֵור\">preced.</a>; cmp. Syr. <span dir=\"rtl\">סנורא</span>, lorica, P. Sm. 2680) <i>polished metal helmet</i>. <span class=\"citation\">Sabb. 62ᵃ</span>, expl. <a href=\"#\" data-headword=\"קַסְדָּא\">קסדא</a> (Ms. M. <a href=\"#\" data-headword=\"סנירתא\">סנירתא</a>, read <span dir=\"rtl\">סנור׳</span>; v. Rabb. D. S. a. l. note for Var. lect.).</div>","alt":["סַנְוַארְתָּה"]},"19690":{"h":"סְנַוְותָּאָה","r":"O01202","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"סְנַפְתָּא\">סְנַפְתָּא</a>) <i>of S’navta</i>. <span class=\"citation\">Sabb. 17ᵇ</span> (Ms. <span dir=\"rtl\">נתוואה</span>, v. Rabb. D. S. a. l. note); (<span class=\"citation\">Ab. Zar. 36ᵃ</span> <span dir=\"rtl\">נִוְתָּאָה</span>, early eds. <span dir=\"rtl\">נִיוְתָּ׳</span>; v. <a href=\"#\" data-headword=\"נִיוְתִּי\">נִיוְתִּי</a>).</div>","alt":[]},"19691":{"h":"סְנוּנִית","r":"O01203","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"סָנַן\">סָנַן</a>) [<i>the glistening</i>,] <i>swallow</i>. Sifra Sh’mini, Par. 3, ch. V <span dir=\"rtl\">הס׳</span>; <span class=\"citation\">Ḥull. 62ᵃ</span> <span dir=\"rtl\">ס׳ לבנה</span> the white-bellied swallow. <span class=\"citation\">Tosef. ib. III</span> (<span class=\"citation\">IV), 23</span> <span dir=\"rtl\">אוכלין את ס׳ לבנה וכ׳</span> used to eat the white-bellied swallow, because &amp;c. <span class=\"citation\">Sabb. 77ᵇ</span> <span dir=\"rtl\">אימת ס׳ על הנשר</span> the fear which the eagle has of the swallow; a. e.</div>","alt":[]},"19692":{"h":"סְנוּנִיתָא","r":"O01204","html":"<div class=\"sense\"> <span class=\"citation\">Targ. Jer. VIII, 7</span> (h. text <span dir=\"rtl\">עגור</span>).</div>","alt":[]},"19693":{"h":"סִנּוּק","r":"O01205","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<span dir=\"rtl\">סנק</span>) <i>pressure</i>, <i>exhaustion</i>. <span class=\"citation\">Sabb. 67ᵃ</span>, v <a href=\"#\" data-headword=\"גָּד ³\">גַּדָּא</a>.</div>","alt":["סִי׳"]},"19694":{"h":"סִנּוֹקֶרֶת","r":"O01206","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (סָקַר II, with anorg. <a href=\"#\" data-headword=\"נ\">נ</a>) [<i>reddening</i>,] <i>a severe or insulting blow in the face</i> (<i>with the fist</i>; oth. opin.: <i>with the back of the hand</i>; Rashi: <i>with the saddle of an ass</i>). <span class=\"citation\">B. Kam. 27ᵇ</span> (Ms. M. <a href=\"#\" data-headword=\"סִינּוּק\">סִינּוֹקְרִית</a>; Ms. F. <span dir=\"rtl\">סיניקרת</span>; ed. Sonc. <span dir=\"rtl\">סטקרת</span>, corr. acc.; v. Rabb. D. S. a. l. note); Y. ib. VIII, end, 6ᶜ <a href=\"#\" data-headword=\"*סַקְלוּנְקִית\">סקלונקית</a>.</div>","alt":["סִינּ׳"]},"19695":{"h":"סַנְוֵרִים","r":"O01207","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"> v. <a href=\"#\" data-headword=\"סַנְוֵור\">סַנְוֵור</a>) <i>blindness</i>, <i>dimness</i>, <span class=\"citation\">Yalk. Esth. 1056</span> <span dir=\"rtl\">שהיה הס׳ על עיניו</span> his eye-sight was veiled.</div>","alt":[]},"19696":{"h":"סָנוּתָא","r":"O01208","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"סִנְאֲתָא\">סִנְאֲתָא</a></div>","alt":[]},"19697":{"h":"סְנוּתָא","r":"O01209","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"סְנוּאֲתָא\">סְנוּאֲתָא</a></div>","alt":[]},"19698":{"h":"סָנַט","r":"O01210","html":"<div class=\"sense\"> (cmp. Syr. <a href=\"#\" data-headword=\"סָנַט\">סנט</a>, P. Sm. 2676, a. Arab. sanuṭ) [<i>to scrape</i>, cmp. <a href=\"#\" data-headword=\"חָסַד II\"><span dir=\"rtl\">חָסַד</span> II</a>] <i>to sneer, scoff, malign</i>. <span class=\"citation\">Gen. R. s. 71</span>, beg. <span dir=\"rtl\">היו הכל סוֹנְטִין בה</span> all sneered at her; <span class=\"citation\">ib.</span> <span dir=\"rtl\">אף הגיתיות … סוֹנְטוֹת בה</span> (not <span dir=\"rtl\">סונטין</span>), v. <a href=\"#\" data-headword=\"*גִּתִּית\">גִּתִּית</a>; <span class=\"citation\">Yalk. ib. 125</span>. <span class=\"citation\">Gen. R. s. 68</span> סוֹנְטִים ‘Rashi’ (ed. Leipz. <span dir=\"rtl\">סונטומוס</span>, corr. acc.; ed. Wil. <span dir=\"rtl\">שׂונְטִים</span>; some ed. <span dir=\"rtl\">שוטנים</span>, corr. acc.).</div>","alt":[]},"19699":{"h":"סַנְטוֹרָא","r":"O01211","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"סַנְטֵרָא\">סַנְטֵרָא</a>.—<span dir=\"rtl\">סנטוראי</span>, v. <a href=\"#\" data-headword=\"סַנְטוּרֵי\">next w.</a></div>","alt":[]},"19700":{"h":"סַנְטוּרֵי","r":"O01212","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"> (<span dir=\"rtl\">סנטר</span>; cmp. <a href=\"#\" data-headword=\"נָטַר\">נָטַר</a>) <i>grudge, hidden hatred, vindictiveness</i>. <span class=\"citation\">Gen. R. s. 67</span> עד … סנטורי דרומי Ar. (ed. <span dir=\"rtl\">סנטרי׳</span>, <span dir=\"rtl\">סנטרוי</span>, corr. acc.) to this day people exclaim, ‘the vindictiveness of Rome’ (with play on <i>senatores</i>); Yalk. ib. 115 <span dir=\"rtl\">סנטוראי דרומאי</span> (<a href=\"#\" data-headword=\"סנטיראי\">סנטיראי</a>; corr. acc.). <span class=\"citation\">Y. Ab. Zar. I, 39ᶜ</span> (play on Saturnalia, v. <a href=\"#\" data-headword=\"סְטַרְנַלְיָיא\">סְטַרְנַלְיָיא</a>) <span dir=\"rtl\">ברומי צווהין ליה סַנְטוֹרַיָּיה דעשו</span> in Rome they (the Jews) call it (that festival of apparent good-will) the hidden hatred of Esau (Rome).</div>","alt":["סַנְטוּרַיָּא"]},"19701":{"h":"סנטורתא","r":"O01213","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"סַנְטֵרוּתָא\">סַנְטֵרוּתָא</a></div>","alt":[]},"19702":{"h":"סִנְטֵיר","r":"O01214","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"סִנְטֵר\">סִנְטֵר</a>, <a href=\"#\" data-headword=\"סַנְטֵר\">סַנְטֵר</a>, <a href=\"#\" data-headword=\"סַנְטֵרָא\"><a href=\"#\" data-headword=\"סַנְטֵרָא\">סַנְטֵרָא</a>.</a></div>","alt":["סַנְטֵיר","סַנְטֵירָא"]},"19703":{"h":"סנטיראי","r":"O01215","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"סַנְטוּרֵי\">סַנְטוּרֵי</a></div>","alt":[]},"19704":{"h":"סִנְטֵר","r":"O01216","html":"<div class=\"sense\"> (Saf. of <a href=\"#\" data-headword=\"נָטַר\">נָטַר</a>) <i>to guard</i>, esp. <i>to watch jealously; to bear grudge</i>. <span class=\"citation\">Gen. R. s. 67</span> (ref. to <span dir=\"rtl\">ויש̇ט̇ם̇</span>, <span class=\"citation\">Gen. XXVII, 41</span>) <span dir=\"rtl\">סִנְטֵירוֹ ונעשה לו ש̇ונא נוקם̇ ונוט̇ר</span> (better <span dir=\"rtl\">סִינְטְרוֹ</span>; Ar. a. <span class=\"citation\">Yalk. Gen. 115</span> omit our w.) he watched him grudgingly, and became to him a vindictive and grudge-bearing enemy; v. <a href=\"#\" data-headword=\"סַנְטוּרֵי\">סַנְטוּרֵי</a></div>","alt":[]},"19705":{"h":"סַנְטֵר","r":"O01217","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"סִנְטֵר\">preced.</a>) </div><div class=\"sense\"><b>1)</b> <i>guardsman</i>, <i>bailiff</i>. <span class=\"citation\">B. Bath. IV, 7</span> <span dir=\"rtl\">המוכר … מכר את הס׳</span> if one sells a township, he sells with it the <i>sanṭer</i> (a slave, v. <a href=\"#\" data-headword=\"אִיקוֹנוֹמוֹס\">אִיקוֹנוֹמוֹס</a>); expl. <span class=\"citation\">ib. 68ᵃ</span> <span dir=\"rtl\">בר מחווניתא</span>, v. <a href=\"#\" data-headword=\"מַחְוָונִיתָא\">מַחְוָונִיתָא</a>; [oth. opin. <span class=\"citation\">ib.</span> <span dir=\"rtl\">באגי</span> <i>the fields around the town</i>]; <span class=\"citation\">Tosef. ib. III, 5</span>. <span class=\"citation\">Snh. 98ᵇ</span> <span dir=\"rtl\">פגע בו ס׳</span> a bailiff meets him (trying to contest his title to the field). <span class=\"citation\">Y. B. Mets. V, 10ᶜ</span> <span dir=\"rtl\">ישראל שמינה … או ס׳</span> an Israelite who appointed a gentile his manager or guardsman. <span class=\"citation\">Gitt. 80ᵇ</span> <span dir=\"rtl\">אפי׳ … לשם ס׳ שבעיר</span> even if he dates a letter of divorce from the rule of a bailiff of the town. Tanḥ. B’rakhah 6 <span dir=\"rtl\">כס׳ הזה וכ׳</span> like the guardsman that speaks before the king; a. e.</div><div class=\"sense\"><b>—2)</b> <i>the guarded land outside of a township</i>. B. Bath. l. c., v. supra.</div><div class=\"sense\"><b>—3)</b>  (cmp. meanings of <a href=\"#\" data-headword=\"לֶחִי I\">לֶחִי</a>, and phrases like <span dir=\"rtl\">שמר פתחי פיך</span>, <span class=\"citation\">Mic. VII, 5</span>) [<i>fence</i>,] <i>jaw, jawbone, chin</i>. <span class=\"citation\">Ber. 24ᵇ</span> <span dir=\"rtl\">וכשהוא … מניח ידו על סַנְטֵרוֹ</span> (Ms. M. <span dir=\"rtl\">סַנְטֵירוֹ</span>) and when he yawned, he put his hand on his chin (to cover his mouth).</div><div class=\"sense\"><b>—4)</b>  a sort of <i>cloak</i>, <i>sanṭer</i> (cmp. <a href=\"#\" data-headword=\"גּוּנְדָּא II\"><span dir=\"rtl\">גּוּנְדָּא</span> II</a>). <span class=\"citation\">Treat. Der. Er. ch. XI</span> <span dir=\"rtl\">סַנְטֵרוֹ לצדדין וקובעו וכ׳</span> he who walks with his <i>sanṭer</i> hanging sideways and his cap turned back …, belongs to the haughty.</div>","alt":["סַנְטֵיר"]},"19706":{"h":"סַנְטֵרָא","r":"O01218","html":"<div class=\"sense\"><b>1)</b> <i>guardsman</i>, <i>bailiff</i> &amp;c. <span class=\"citation\">Koh. R. to IV, 8</span> בלשאצר ס׳ דבבל Belshazzar, governor of Babylon. <span class=\"citation\">Lev. R. s. 34</span> <span dir=\"rtl\">אתנסיבת לס׳ דקרתא</span> she married the guardsman of the town; <span class=\"citation\">Yalk. Is. 352</span>; <span class=\"citation\">Gen. R. s. 17</span> <span dir=\"rtl\">סנטרין</span> (corr. acc.); <span class=\"citation\">Y. Keth. XI, 34ᵇ</span> bot. <span dir=\"rtl\">לטסורא</span> (corr. acc.). Pesik. Haʿom., p. 69ᵇ (ref. to <span class=\"citation\">Jer. V, 24</span> <span dir=\"rtl\">ישטר לנו</span>) <span dir=\"rtl\">סַנְטֵרָךְ אנא וכ׳</span> I (the Lord) am thy guardsman (guarding thy crops), and wilt thou not give me my guard’s pay (tithes)?; <span class=\"citation\">Pesik. R. s. 18</span>; <span class=\"citation\">Koh. R. to I, 3</span> <span dir=\"rtl\">סנטורך</span>; <span class=\"citation\">Lev. R. s. 28</span>. Pesik. Ekhah, p. 120ᵇ <span dir=\"rtl\">ריש מטרתא וס׳</span> the chief of the town guard and the bailiff; Lam. R. introd. (R. Abba 2); a. e.—Pl. <a href=\"#\" data-headword=\"סַנְטוּרֵי\">סַנְטֵרַיָּא</a>, <span dir=\"rtl\">סַנְטֵרִין</span>, <a href=\"#\" data-headword=\"סַנְטֵרָא\">סַנְטֵי׳</a>, <a href=\"#\" data-headword=\"סַנְטֵרָא\">(סַנְטוֹ׳</a>). <span class=\"citation\">Y. Shebi. IV, 35ᵇ</span> top <span dir=\"rtl\">חמוניה ס׳ וכ׳</span> the field watchmen saw him (eat of the fruit) and began to strike him. <span class=\"citation\">Y. Ḥag. I, 76ᶜ</span> <span dir=\"rtl\">סַנְטוֹרֵי קרתא</span> the guardsmen of the town (Pesik. l. c. <span dir=\"rtl\">ריש מטרתא וסנטרא</span>, v. supra); a. e.—2) (only in <i>pl.</i>) <i>upper garments, outer clothing, walking dress</i>. <span class=\"citation\">Gen. R. s. 100</span> <span dir=\"rtl\">נפיק … סַנְטֵרוֹי</span> came forth to meet him dressed in his upper garments (although a mourner); <span dir=\"rtl\">מאי סנטרוי מאנין וכ׳</span> what do you mean by ‘his <i>sanṭerin’</i>? Garments which showed no rents; <span class=\"citation\">Y. M. Kat. III, 83ᶜ</span> top <span dir=\"rtl\">לביש סַנְטֵירַיָּה</span>, expl. <span dir=\"rtl\">מאנין דלא חפיתין</span>, v. <a href=\"#\" data-headword=\"חֲפַת\">חֲפַת</a>.—[<span class=\"citation\">Gen. R. s. 67</span> <span dir=\"rtl\">סנטרי׳</span>, <span dir=\"rtl\">סנטרוי</span>, v. <a href=\"#\" data-headword=\"סַנְטוּרֵי\">סַנְטוּרֵי</a>.]</div>","alt":["סַנְטֵי׳","(סַנְטוֹ׳)"]},"19707":{"h":"סַנְטֵרוּתָא","r":"O01219","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"סַנְטֵרָא\">preced.</a>) <i>watchman’s pay, watchman’s charge</i>. Pesik. Haʿom. p. 69ᵇ <a href=\"#\" data-headword=\"סַנְטֵרוּתָא\">סַנְטֵרוּתִי</a> (not <span dir=\"rtl\">סנטורתי</span>), v. <a href=\"#\" data-headword=\"סַנְטֵרָא\">preced.</a>; <span class=\"citation\">Pesik. R. s. 18</span>; <span class=\"citation\">Lev. R. s. 28</span> <span dir=\"rtl\">דסנטרותי</span> of that I which I have guarded; <span class=\"citation\">Koh. R. to I, 3</span> <span dir=\"rtl\">מסַנְטַרְיוּתִי</span>.</div>","alt":[]},"19708":{"h":"סַנְטַרְיוּתָא","r":"O01220","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"סַנְטֵרוּתָא\">preced.</a></div>","alt":[]},"19709":{"h":"סַנְי","r":"O01221","html":"<div class=\"sense\">, pl. of <a href=\"#\" data-headword=\"סַנְאָה\">סַנְאָה</a>.</div>","alt":[]},"19710":{"h":"סַנֵּי","r":"O01222","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"סַנְיָא IV\"><span dir=\"rtl\">סַנְיָא</span> IV</a></div>","alt":[]},"19711":{"h":"סני","r":"O01223","html":"<div class=\"sense\"><i>to hate</i>, v. <a href=\"#\" data-headword=\"שָׂנֵא\">שָׂנֵא</a>.</div>","alt":["סָנֵא","סָנָה"]},"19712":{"h":"סְנֵי","r":"O01224","html":"<div class=\"sense\"><b>1)</b> <i>to hate</i>. <span class=\"citation\">Targ. O. Deut. XXII, 16</span> (Y. ed. Amst. <a href=\"#\" data-headword=\"סַנָּא\">סַנָּא</a>). Ib. 13. <span class=\"citation\">Targ. Ps. XXXI, 7</span> Ms. (ed. <a href=\"#\" data-headword=\"סוֹכָה\">שׂ׳</a>); a. fr. (interch. with <a href=\"#\" data-headword=\"סְבָכָה\">שְׂ׳</a>).—Part. <a href=\"#\" data-headword=\"סָאנֵי\">סָנֵי</a>, <a href=\"#\" data-headword=\"סָאנֵי\">(סָאנֵי</a>); f. <a href=\"#\" data-headword=\"סַנְיָא IV\">סַנְיָא</a>; pl. <span dir=\"rtl\">מָנִין</span>, <a href=\"#\" data-headword=\"סָנַן\">סָנָן</a>. <span class=\"citation\">Targ. Prov. VI, 16</span>. <span class=\"citation\">Ib. XXVI, 28</span> (some ed. <span dir=\"rtl\">שָׂא׳</span>). <span class=\"citation\">Ib. VIII, 13</span> (Bxt. <a href=\"#\" data-headword=\"סַנְאָה\">סַנְאָה</a>). <span class=\"citation\">Ib. I, 22</span>. <span class=\"citation\">Targ. Mic. III, 2</span>; a. fr.—<span class=\"citation\">Yoma 9ᵇ</span> באלהא דסָנֵינָא לכו Ms. M. (<span dir=\"rtl\">אלהא ס׳</span>) by God, we hate you (Babylonians). <span class=\"citation\">Keth. 105ᵇ</span> <span dir=\"rtl\">לא לידון … דסָ׳ ליה</span> one must not act as judge in the case of one he loves, or of one he hates. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">מינייהו סָנוּ לי</span> some of them hate me. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">או מִסְנֵי כולהו סמו לי</span> (not <span dir=\"rtl\">מסנו</span>) if there is hating (among them), they all hate me. <span class=\"citation\">Sabb. 153ᵃ</span> <span dir=\"rtl\">דסני ליה כולהו וכ׳</span> (Rashi <span dir=\"rtl\">דסנו</span>) whom all the people of Pumbeditha hate. <span class=\"citation\">Ib. 26ᵃ</span> דהוות סניא לכלתה Ms. M. (ed. <span dir=\"rtl\">סְנִיאָה לה לכלתה</span>) who hated her daughter-in-law. <span class=\"citation\">Pes. 113ᵇ</span> <span dir=\"rtl\">ומי שריא למִסְנַיֵיה</span> (some ed. <span dir=\"rtl\">למִסְנֵיה</span>) is it permitted to hate a fellowman? <span class=\"citation\">Ib.</span> <span dir=\"rtl\">מהו למימרא … למִישְׂנַיְיהוּ</span> (Yalk. Ms. <span dir=\"rtl\">למִסְנַיֵיה</span>, v. Rabb. D. S. a. l. note 1) is it permitted to denounce him to his teacher that he may hate him? Ib. <span dir=\"rtl\">מִסְנֵא סנו ליה</span> Ms. M. (ed. <span dir=\"rtl\">מִיסְנֵי סני</span>) they should hate him. <span class=\"citation\">M. Kat. 17ᵃ</span> <span dir=\"rtl\">דהוו סנו שומעניה</span> whose reputation people disliked (who was ill-reputed, v. infra); a. fr.—<i>Part. pass.</i> <a href=\"#\" data-headword=\"סְנֵי\">סְנֵי</a>, <a href=\"#\" data-headword=\"סְנֵי\">סְנִי</a>; f. <a href=\"#\" data-headword=\"סַנְיָא IV\">סַנְיָא</a> <i>hated, hateful; ungainly, unsavory</i>. <span class=\"citation\">Targ. Prov. XIV, 20</span> (ed. Lag. <a href=\"#\" data-headword=\"סָאנֵי\">סאני</a>; h. text <span dir=\"rtl\">יִשָּׂנֵא</span>).—<span class=\"citation\">Sabb. 31ᵃ</span> <span dir=\"rtl\">דעלד סני וכ׳</span>, v. <a href=\"#\" data-headword=\"חַבְרָא\">חַבְרָא</a>. <span class=\"citation\">Meg. 25ᵇ</span> האי מאן דסני שימעניה Ms. M. (ed. <span dir=\"rtl\">דסְנָאֵי</span>, v. supra) one whose reputation is bad, v. <a href=\"#\" data-headword=\"בְּזֵי ²\"><span dir=\"rtl\">בְּזֵי</span> I</a>. <span class=\"citation\">Ib. 14ᵇ</span> <span dir=\"rtl\">סַנְיָין שמייהו</span> (Ms. M. <a href=\"#\" data-headword=\"סני\">סני</a>; Ms. Halberst. <span dir=\"rtl\">שַׂנְיָאן</span>; Ms. O. <a href=\"#\" data-headword=\"שְׁנֵי\">אִישְׂתַּנֵּי</a>; v. Rabb. D. S. a. l. note) they are ungainly of name; (Ms. M. their names are ungainly).</div><div class=\"sense\"><b>—2)</b>  (fr. part. pass.) <i>to be ugly</i>. <span class=\"citation\">Taan. 7ᵇ</span> top <span dir=\"rtl\">אי הוו סָנוּ וכ׳</span> if they had been ugly, they would have been still greater scholars.</div>","alt":["סְנָא"]},"19713":{"h":"סַנְיָא I","r":"O01225","html":"<div class=\"sense\"> f., v. <a href=\"#\" data-headword=\"סְנֵי\">preced.</a></div>","alt":[]},"19714":{"h":"סַנְיָא II","r":"O01226","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (preced) </div><div class=\"sense\"><b>1)</b> <i>badness</i>, <i>inferiority</i>. <span class=\"citation\">B. Bath. 122ᵃ</span> <span dir=\"rtl\">לשופרא וס׳</span> to equalize the distribution of land with regard to the better or inferior quality.</div><div class=\"sense\"><b>—2)</b> <i>evil nature</i>; (by way of antiphrasis for <a href=\"#\" data-headword=\"טִיב\">טיב</a>) <i>nature</i>.—<span dir=\"rtl\">ביש סַנְיֵיה</span> one whose nature is bad, <i>ill-natured</i>. <span class=\"citation\">Koh. R. to XI, 9</span> (some ed. <span dir=\"rtl\">ביש סַנְיָה</span>).—V. <a href=\"#\" data-headword=\"סוּנִיתָא\">סוּנִיתָא</a>.</div>","alt":[]},"19715":{"h":"סַנְיָא III","r":"O01227","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> = h. <a href=\"#\" data-headword=\"סְנֶה\">סְנֶה</a>. <span class=\"citation\">Targ. Y. Ex. III, 4</span>, sq.—<span class=\"citation\">Cant. R. to I, 1</span> (prov.) <span dir=\"rtl\">מן ס׳ נפיק וורדא</span> (some ed. <span dir=\"rtl\">נפקא ורדא</span>) from a thorn-bush comes forth a rose (good children of a bad father); <span class=\"citation\">Yalk. Sam. 134</span> <span dir=\"rtl\">ס׳ דאפיק וכ׳</span> (not <a href=\"#\" data-headword=\"סַכְיָא\">סכיא</a>) a thorn which produced a rose.—Pl. <span dir=\"rtl\">סַנַיָּיא</span>, <a href=\"#\" data-headword=\"סַנְיָא III\">סַנַיָּא</a>. <span class=\"citation\">Targ. Y. Deut. XXXIII, 16</span> (prob. to be read <span dir=\"rtl\">סַנְיָיא</span> sing.).—[<span class=\"citation\">Targ. Prov. VIII, 19</span> <a href=\"#\" data-headword=\"סַנְיָא III\">סניא</a> for <a href=\"#\" data-headword=\"סַגִּי\">סגיא</a>, v. <a href=\"#\" data-headword=\"גַּבְיָא I\"><span dir=\"rtl\">גַּבְיָא</span> I</a>.]</div>","alt":["סְנֵיָא"]},"19716":{"h":"סַנְיָא IV","r":"O01228","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<span dir=\"rtl\">סנן</span>) <i>sieve</i>; <span dir=\"rtl\">ס׳ דיבי</span> <i>mucal sieve</i>, name of a certain <i>part of the intestines</i>; [oth. opin.: <i>disliked by wolves</i>, v. <a href=\"#\" data-headword=\"סְנֵי\">סְנֵי</a>]. <span class=\"citation\">Ḥull. 50ᵇ</span>.—<span class=\"citation\">Koh. R. to VII, 19</span> (some ed. <a href=\"#\" data-headword=\"סני\">סני</a>); <span class=\"citation\">Lev. R. s. 3</span> <i>the ileum</i>; v. <a href=\"#\" data-headword=\"כַּנְתָא\">כַּנְתָא</a>.</div>","alt":["סַנֵּי"]},"19717":{"h":"סְנִיאָס","r":"O01229","html":"<div class=\"sense\">, <span class=\"citation\">Targ. Y. I Num. XXXIV, 11</span>, read <a href=\"#\" data-headword=\"פַּנְיָאס\">פַּנְיָאס</a>.</div>","alt":[]},"19718":{"h":"סְנִיאֲתָא","r":"O01230","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"סְנִיאֲתָא\">סְניּאֲתָא</a>, a. <a href=\"#\" data-headword=\"סִנְאֲתָא\">סִנְאֲתָא</a>.</div>","alt":[]},"19719":{"h":"סְנֵיגוֹר","r":"O01231","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (συνήγορος) <i>advocate</i>, <i>attorney</i>, opp. <a href=\"#\" data-headword=\"קָטֵיגוֹר\">קטיגור</a> prosecutor. <span class=\"citation\">R. Hash. 26ᵃ</span> <span dir=\"rtl\">אין קטיגור נעשה ס׳</span> the accuser (gold reminding of the golden calf) must not be made an advocate (therefore must the high priest on the Day of Atonement not enter the Holy of Holies in gold-embroidered garments); <span class=\"citation\">Ber. 59ᵃ</span>. <span class=\"citation\">Ḥag. 13ᵇ</span> <span dir=\"rtl\">קטיגור יעשה ס׳</span> shall the accuser (the ox or calf) become an advocate? <span class=\"citation\">Lev. R. s. 30</span> <span dir=\"rtl\">אוי … סְנֵיגוֹרוֹ וכ׳</span> woe to this man, his advocate has turned prosecutor!; <span class=\"citation\">Y. Succ. III, beg. 53ᶜ</span> <span dir=\"rtl\">שניגורו</span> (corr. acc.); a. fr.—Pl. <span dir=\"rtl\">סְנֵיגוֹרִים</span>, <span dir=\"rtl\">סְנֵיגוֹרִין</span>. <span class=\"citation\">Y. R. Hash. I, 57ᵇ</span> top; a. fr.—Mekh. Mishp., s. 20 (ref. to <span class=\"citation\">Ex. XXIII, 7</span>) <span dir=\"rtl\">שלא יעמיד אצלו ס׳ וכ׳</span> that he (the judge) must not allow advocates to stand by his side (in place of the parties themselves), for it is said, ‘before the judge the words of both of them must come’ (ib. XXII, 8); [<span class=\"citation\">Shebu. 30ᵇ</span> <span dir=\"rtl\">שלא יעשה סניגרון לדבריו</span> (Ms. M. <span dir=\"rtl\">יעשה דבריו סנגרון</span>; <span class=\"citation\">Yalk. Ex. 352</span> <span dir=\"rtl\">שלא יעשה סניגורין לדבריו</span>) that he must not appoint advocates for what he has to say (in defense of his decision, if a point of law is raised against it); the entire passage seems to require emendation in accordance with Mekh. l. c.]</div>","alt":[]},"19720":{"h":"סַנִּיגוֹרָא","r":"O01232","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"><i>Bar-Sannigora</i>. <span class=\"citation\">Targ. Y. I Num. XXXIV, 8</span> <span dir=\"rtl\">כרכוי דבר ס׳</span> the towns of Bar-S. (on the border between Syria and Palestine); [for <a href=\"#\" data-headword=\"טְבַרְיָא\">טבריא</a> ib., read with Y. II <a href=\"#\" data-headword=\"אַנְטוּכְיָא\">אנטוכיא</a>]; <span class=\"citation\">Sifré Deut. 51</span> <span dir=\"rtl\">כרכא דבר סנגרא</span> (not <span dir=\"rtl\">דבר</span>); <span class=\"citation\">Yalk. ib. 874</span> (not <a href=\"#\" data-headword=\"כְּרָבָא II\">כרבא</a>); <span class=\"citation\">Tosef. Shebi. IV, 11</span> <span dir=\"rtl\">כפרא דבר סנגרא</span> (read <span dir=\"rtl\">כרכא</span>; Var. <span dir=\"rtl\">סינגורא</span>); Y. Shebi. VI, 36ᶜ <span dir=\"rtl\">ברכה רבה ובר סנגדא</span> (corr. acc., or <span dir=\"rtl\">כרכה רבה דבר ס׳</span></div>","alt":["בַּר ס׳"]},"19721":{"h":"סְנִיגוֹרְיָא","r":"O01233","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (συνηγορία) <i>defence, speaking in behalf of</i>.—לִמֵּד ס׳ על <i>to speak in defence of</i>. <span class=\"citation\">Y. Taan. II, 65ᵈ</span> top. <span class=\"citation\">Ex. R. s. 15</span>, end. <span class=\"citation\">Lev. R. s. 6</span>, beg. [read:] <span dir=\"rtl\">הדא רו&quot;הק ס׳ היא מלמדת לכאן וכ׳</span> (<a href=\"#\" data-headword=\"זְכוּת\">זכות</a> being a gloss to our w.) that holy spirit speaks in defence of both sides; a. fr.</div>","alt":[]},"19722":{"h":"סְנִיגְרוֹן","r":"O01234","html":"<div class=\"sense\">, a corrupt. of <span dir=\"rtl\"><a href=\"#\" data-headword=\"סִיגָּרוֹן I\">סִיגָרוֹן</a>(אָכְ</span>). <span class=\"citation\">Tosef. Shebi. VI, 3</span>; <span class=\"citation\">Tosef. Ter. IX, 10</span>; v. <a href=\"#\" data-headword=\"אָכְסִיגָרוֹן\">אָכְסִיגָרוֹן</a></div>","alt":[]},"19723":{"h":"סניגרון","r":"O01235","html":"<div class=\"sense\">, <span class=\"citation\">Shebu. 30ᵇ</span>, read: <span dir=\"rtl\">סְנֵיגוֹרִין</span>; v. <a href=\"#\" data-headword=\"סְנֵיגוֹר\">סְנֵיגוֹר</a></div>","alt":[]},"19724":{"h":"סַנְיָה","r":"O01236","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"סַנְיָא II\"><span dir=\"rtl\">סַנְיָא</span> II</a></div>","alt":[]},"19725":{"h":"סַנְיוּתָא","r":"O01237","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"סְנֵי\">סְנֵי</a>) <i>dislike</i>, <i>displeasure</i>. <span class=\"citation\">Ned. 62ᵃ</span> <span dir=\"rtl\">קסבר משום סַנְיוּת מילתא וכ׳</span> he thought that man spoke so from a dislike of the thing (spoke ironically because he was angry). Yalk. Dan. 1060, v. <a href=\"#\" data-headword=\"שַׂנְאוּתָא\">שַׂנְאיּתָא</a>.</div>","alt":[]},"19726":{"h":"סְנֵין","r":"O01238","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"סְנַן\">סְנַן</a></div>","alt":[]},"19727":{"h":"סָנִיף","r":"O01239","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"סָנַף\">סָנַף</a>) <i>attachment, wedge; key-stone</i>. <span class=\"citation\">Midr. Till. to Ps. XCI</span>; <span class=\"citation\">Pirké d’R. El. ch. XXXV</span>; <span class=\"citation\">Yalk. Gen. 120</span> <span dir=\"rtl\">כאדם שהוא נותן ס׳ לכיפה</span> as one inserts a key-stone in an arch. <span class=\"citation\">Ber. 47ᵇ</span>; Y. ib. VI, 11ᵇ top <span dir=\"rtl\">עושין אותו ס׳ לעשרה</span> we wedge him in among the ten, i.e. we count him in so as to make up the requisite number; a. fr.—Pl. <span dir=\"rtl\">סְנִיפִים</span>, <span dir=\"rtl\">סְנִיפִין</span>. <span class=\"citation\">Tosef. Snh. VII, 9</span> <span dir=\"rtl\">בבית … עושין אותן ס׳</span> at a wedding feast we place them among (the adults); <span class=\"citation\">Hor. 13ᵇ</span>. <span class=\"citation\">Taan. 25ᵃ</span> <span dir=\"rtl\">ס׳ עשאום</span> they made them (the beams) in links, i.e. joined mortised pieces to them. <span class=\"citation\">Tosef. Men. XI, 6</span> <span dir=\"rtl\">ארבע ס׳ … היו וכ׳</span> four golden attachments were there (to the table) shaped like forks; <span class=\"citation\">Men. XI, 6</span>. <span class=\"citation\">Ib. 94ᵇ</span> <span dir=\"rtl\">והס׳ מעמידין וכ׳</span> and these attachments supported the loaves; <span class=\"citation\">Num. R. s. 4</span>; a. fr.—<span class=\"citation\">Kel. XXI, 3</span> ס׳ <i>the side-pieces of a saw which hold the blade, and the wedge with which the cord is twisted</i></div>","alt":[]},"19728":{"h":"סְנִיפָא","r":"O01240","html":"<div class=\"sense\">—Pl. constr. <span dir=\"rtl\">סְנִיפֵי</span> (<span dir=\"rtl\">סִינּוּפֵי</span>) <i>the barbed tops of a fence</i> or <i>wall</i>. <span class=\"citation\">B. Bath. 4ᵇ</span>, v. <a href=\"#\" data-headword=\"*דָּיְכֵי\">דָּיְכֵי</a>.</div>","alt":[]},"19729":{"h":"סְנִיפְתָּא","r":"O01241","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"סְנַפְתָּא\">סְנַפְתָּא</a></div>","alt":[]},"19730":{"h":"סנירתא","r":"O01242","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"סַנְוַורְתָּא\">סַנְווַרְתָּא</a></div>","alt":[]},"19731":{"h":"סְנֵיתָא","r":"O01243","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"סִנְאֲתָא\">סִנְאֲתָא</a> a. <a href=\"#\" data-headword=\"סְנוּאֲתָא\"><a href=\"#\" data-headword=\"סְנוּאֲתָא\">סְנוּאֲתָא</a>.</a></div>","alt":["סְנִיתָא"]},"19732":{"h":"סָנַן","r":"O01244","html":"<div class=\"sense\"> [<i>to sting</i>, cmp. <a href=\"#\" data-headword=\"סְנֶה\">סְנֶה</a>; of color:] <i>to be bright, shine</i>. V. <a href=\"#\" data-headword=\"סְנוּנִית\">סְנוּנִית</a>.—Part. pass. <span dir=\"rtl\">סָנוּן</span>; pl. <a href=\"#\" data-headword=\"סְנוּנִית\">סְנוּנִין</a>. <span class=\"citation\">Num. R. s. 4</span> (expl. <span dir=\"rtl\">מפזז</span>, <span class=\"citation\">II Sam. VI, 16</span>) <span dir=\"rtl\">היה לבוש בגדי זהב ס׳ וכ׳</span> he was dressed in glistening, gold-embroidered garments shining like fine gold.</div><div class=\"sense\"><b>Pi. סִינֵּן</b> <div class=\"sense\"><i>to clear, filter</i>; (of metals) <i>to smelt, refine</i>. <span class=\"citation\">Sabb. XX, 2</span> <span dir=\"rtl\">מְסַנְּנִין את היין וכ׳</span> you may (on the Sabbath) filter wine through a cloth &amp;c.Ḥull. <span class=\"citation\">Ḥull. 67ᵃ</span> <span dir=\"rtl\">יבחושין שסִינְּנָן</span> gnats in liquids which one has passed through a filter; a. e.—<i>Part. pass.</i> מְסוּנָּן <i>refined</i>, <i>bright</i>. Num. R. l. c. (expl. <span dir=\"rtl\">מפזז</span>, v. supra) <span dir=\"rtl\">הזהב המס׳ … פוזז</span> the refined gold which he wore made a rustling noise.</div></div><div class=\"sense\"><b>Nithpa. נִסְתַּנֵּן</b> </div><div class=\"sense\"><b>Hithpol. הִסְתּוֹנֵן</b> <div class=\"sense\"><i>to be refined</i>. Ib. s. 7, beg. <span dir=\"rtl\">נִסְתַּנְּנוּ הפסולות ממנו וכ׳</span> when the base metals are removed from it (the silver) by refining, it shows at once &amp;c. <span class=\"citation\">Pesik. R. s. 14</span> (ref. to <span class=\"citation\">Ps. XII, 7</span>) [read:] <span dir=\"rtl\">כשם שהכסף … ומצטרף ומִסְתּוֹנֵן וכ׳</span> as the silver to be smelted enters the crucible and is smelted and refined etc.; <span dir=\"rtl\">כך היא התורה מִסְתּוֹנֶנֶת וכ׳</span> so is the Law refined and smelted (through study) in forty-nine ways.</div></div>","alt":[]},"19733":{"h":"סְנַן","r":"O01245","html":"<div class=\"sense\">; (act. verb) <i>to filter, clear, refine</i> (interch. with <i>Pa</i>.). <span class=\"citation\">Targ. Ps. CV, 19</span> (Ms. <a href=\"#\" data-headword=\"סְנַן\">סַנֵּין</a>). <span class=\"citation\">Ib. XVII, 3</span>; a. fr.—Part. pass. <a href=\"#\" data-headword=\"סְנֵין\">סְנִין</a>; f. <a href=\"#\" data-headword=\"סְנֵיתָא\">סְנִינָא</a>. <span class=\"citation\">Ib. XII, 7</span>. <span class=\"citation\">Ib. LXVIII, 14</span>. <span class=\"citation\">Targ. Job XI, 15</span>; a. fr.</div><div class=\"sense\"><b>Pa. סַנֵּין</b> <div class=\"sense\"> <a href=\"#\" data-headword=\"סָנַן\">same</a>, v. supra. Ib. XXVIII, 1; a. e. [<span class=\"citation\">Targ. Y. I Deut. XXXIII, 28</span> <span dir=\"rtl\">דסַיַּין</span> (some ed. <span dir=\"rtl\">דמיין</span>; h. text <span dir=\"rtl\">ערף</span>) prob. to be read: <span dir=\"rtl\">דמְסַנִּין וכ׳</span> (= <span dir=\"rtl\">דמסננין</span></div></div>","alt":["סְנֵין"]},"19734":{"h":"סנסון","r":"O01246","html":"<div class=\"sense\">, <span class=\"citation\">Tosef. Kel. B. Bath. V, 11</span>; <span class=\"citation\">Tosef. Neg. V, 14</span>, read: <span dir=\"rtl\">סָגוֹסִין</span>, v. <a href=\"#\" data-headword=\"סָגוּם\">סָגוֹס</a></div>","alt":["סנסין"]},"19735":{"h":"סַנְסַן I","r":"O01247","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"><i>Sansan</i>. <span class=\"citation\">Gen. R. s. 19</span> <span dir=\"rtl\">חנינא בר ס׳</span> (cmp. <a href=\"#\" data-headword=\"סִיסִי\">סִיסִי</a>; <span class=\"citation\">Yalk. Esth. 1056</span> <a href=\"#\" data-headword=\"פַּפָּא\">פפא</a>).</div>","alt":[]},"19736":{"h":"סַנְסַן II","r":"O01248","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> <span dir=\"rtl\">סַנְסִנִּים</span> pl.; v. ) [<i>prick</i>,] <i>the pointed ribbed leaf of the palm tree</i>. <span class=\"citation\">Snh. 93ᵃ</span> (ref. to <span class=\"citation\">Cant. VII, 9</span>) <span dir=\"rtl\">לא עלתה בידי אלא ס׳ אחת</span> (v. Rashi) I can claim as mine only one leaf (of the palm Israel) that of Hanania &amp;c.; <span class=\"citation\">Yalk. Cant. 992</span> <a href=\"#\" data-headword=\"סַנְסִנָּה\">סַנְסִנָּה</a>.—Pl. <span dir=\"rtl\">סַנְסִנִּים</span>. <span class=\"citation\">Num. R. s. 3</span>, beg.; <span class=\"citation\">Gen. R. s. 41</span>, beg.; <span class=\"citation\">Yalk. Ps. 845</span> <span dir=\"rtl\">ס׳ לכברה</span> (not <span dir=\"rtl\">לכבד</span>) the leaves (of the palm tree) are used for sieves.</div>","alt":[]},"19737":{"h":"סַנְסַנָּא","r":"O01249","html":"<div class=\"sense\">—Pl. <span dir=\"rtl\">סַנְסִנַּיָּיה</span>. <span class=\"citation\">Cant. R. to VII, 9</span>, v. <a href=\"#\" data-headword=\"אִלְבָּנָא\">אִלְבָּנָא</a>.</div>","alt":[]},"19738":{"h":"סַנְסִנָּה","r":"O01250","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"סַנְסַן II\"><span dir=\"rtl\">סַנְסַן</span> II</a></div>","alt":[]},"19739":{"h":"סָנַף","r":"O01251","html":"<div class=\"sense\"> (Saf. of <span dir=\"rtl\">ענף</span>; v. <a href=\"#\" data-headword=\"סִימְפּוֹן\">סימְפּוֹן</a>) <i>to interlace; to insert</i>. <span class=\"citation\">Tosef. Keth. VII, 10</span> <span dir=\"rtl\">היה בה מום אחר וסְנָפוֹ בין המומין</span> if she had another blemish, and he in his enumeration had inserted it among the blemishes (which she really did not have, so as to make believe that she was also free from that blemish); <span class=\"citation\">Tosef. B. Bath. IV, 5</span>, sq.; <span class=\"citation\">B. Mets. 80ᵃ</span> (<span dir=\"rtl\">אחד</span> for <span dir=\"rtl\">אחר</span>). V. <a href=\"#\" data-headword=\"סָנִיף\">סָנִיף</a>.</div>","alt":[]},"19740":{"h":"סנף","r":"O01252","html":"<div class=\"sense\">, <span class=\"citation\">Koh. R. to XI, 9</span> <span dir=\"rtl\">איסתנפנוי</span>, read: <span dir=\"rtl\">אִיסְתַּפְנוּן</span>, v. <a href=\"#\" data-headword=\"סְפַן\">סְפַן</a></div>","alt":[]},"19741":{"h":"סְנַפִּיר","r":"O01253","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (b. h.; = <a href=\"#\" data-headword=\"סְנַפִּיר\">סַנְפִּיר</a>; <span dir=\"rtl\">ספר</span> with anorganic <a href=\"#\" data-headword=\"נ\">נ</a>; cmp. <a href=\"#\" data-headword=\"סִמְפּוֹרִין\">סִמְפּוֹרִין</a>, <i>fins.</i> <span class=\"citation\">Ḥull. III, 7</span>. <span class=\"citation\">Nidd. VI, 9</span> <span dir=\"rtl\">כל … יש לו ס׳</span> every fish that has scales has also fins; <span dir=\"rtl\">ויש שיש לו ס׳ וכ׳</span> but some have fins but no scales. Sifra Sh’mini, ch. IV, Par. 3 <span dir=\"rtl\">אפי׳ אין לו אלא ס׳ אחת</span> even if it has only one set of fins; a. e.—Pl. <span dir=\"rtl\">סְנַפִּירִים</span>, <span dir=\"rtl\">סְנַפִּירִין</span>, <a href=\"#\" data-headword=\"סַמְפִּירִינוֹן\">סְנַפִּרִ׳</a>. Ib. <span dir=\"rtl\">המרבה … ובס׳</span> one that has more than one coat of scales and one set of fins. Ib. (ref. to <span class=\"citation\">Job XLI, 22</span>) <i>ḥaddudé ḥares</i> <span dir=\"rtl\">אלו ס׳ שלו</span> refers to its (the Leviathan’s) fins. Ḥull. l. c. <span dir=\"rtl\">וס׳ הפורח בהן</span> by <i>s’nappirin</i> is meant that organ with which it speeds its movements.—[<span class=\"citation\">Yalk. Lev. 645</span> <span dir=\"rtl\">סנפירים</span>, v. <a href=\"#\" data-headword=\"סַלְפִּינְגָּס\">סַלְפִּינְגָּס</a>.]</div>","alt":[]},"19742":{"h":"סַנְפִּירִינוֹן","r":"O01254","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"סַמְפִּירִינוֹן\">סַמְפִּי׳</a></div>","alt":[]},"19743":{"h":"סְנַפִּר","r":"O01255","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"סְנַפִּיר\">סְנַפִּיר</a></div>","alt":[]},"19744":{"h":"סְנַפְתָּא","r":"O01256","html":"<p class=\"morphology\">pr. n. pl.</p><div class=\"sense\"><i>S’nafta</i>, a border town. Y. Shebi. VI, 36ᶜ; <span class=\"citation\">Tosef. Shebi. IV, 11</span> <span dir=\"rtl\">סְנִיפְ׳</span> ed. Zuck. (Var. <span dir=\"rtl\">סנפ׳</span>); <span class=\"citation\">Sifré Deut. 51</span>, a. <span class=\"citation\">Yalk. ib. 874</span> <span dir=\"rtl\">ספנתא</span>.</div>","alt":["סְנַפְתָּה"]},"19745":{"h":"סָנַק","r":"O01257","html":"<div class=\"sense\"> (Saf. of <a href=\"#\" data-headword=\"אנק\">אנק</a>, <a href=\"#\" data-headword=\"עֲנָק I\">ענק</a>; cmp. Assyr. <span dir=\"rtl\">סנק</span>, Del. Assyr. Handw.) <i>to press, stuff</i>. <span class=\"citation\">Tam. II, 1</span> <span dir=\"rtl\">סוֹנְקִין אותן וכ׳</span> (Talm. ed. <span dir=\"rtl\">סוֹלְקִין</span>) they press them against the sides of the altar.</div><div class=\"sense\"><b>Pi. סִינֵּק</b> <div class=\"sense\"> <a href=\"#\" data-headword=\"סְנַפְתָּא\">same</a>. <span class=\"citation\">Mikv. II, 6</span> <span dir=\"rtl\">המְסַנֵּק את הטיט וכ׳</span> if one presses the mud against the sides of the pool.</div></div>","alt":[]},"19746":{"h":"סְנַק","r":"O01258","html":"<div class=\"sense\"><i>Pa</i>. <span dir=\"rtl\">סַנֵּק</span> <a href=\"#\" data-headword=\"סָנַק\">same</a>, esp. <i>to stuff</i>; [oth. opin.: <i>to choke, cause loss of breath</i>].—Part. pass. <span dir=\"rtl\">מְסַנַּק</span>, (with <a href=\"#\" data-headword=\"ו\">ו</a> emphat.) <span dir=\"rtl\">מְסַנְּקָן</span>. <span class=\"citation\">Pes. 3ᵇ</span> <span dir=\"rtl\">שויתינן … כגדי מס׳</span> you made that subject to us (as savory) as a stuffed kid; <span dir=\"rtl\">כדבר אחר מ׳</span> as a stuffed swine; [Ar. a. Rashi: this lesson made us (as tired) as a breathless kid, swine].</div>","alt":[]},"19747":{"h":"סנקדרין","r":"O01259","html":"<div class=\"sense\">, <span class=\"citation\">Yalk. Esth. 1057</span>, read: <span dir=\"rtl\">סִנְקַתֶּדְרִין</span>.</div>","alt":[]},"19748":{"h":"סנקוטס","r":"O01260","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"סִנְקְלִיטוֹס\">סִנְקְלִיטוֹס</a></div>","alt":[]},"19749":{"h":"סנקירקים","r":"O01261","html":"<div class=\"sense\">, <span class=\"citation\">Sifré Deut. 317</span>; <span class=\"citation\">Yalk. ib. 944</span> <span dir=\"rtl\">סרקני דקין</span>, corruptions; prob. to be read: <span dir=\"rtl\">סִנְקְלִיטִיקִים</span>, v. <a href=\"#\" data-headword=\"סִינְקִלִיטוֹס\">סִנְקְלִיטִיקוֹס</a>; [Pesik. Zutr. Haăz., ed. Bub. p. 113 has <span dir=\"rtl\">סנקליטין</span>].</div>","alt":["סנקנירקים"]},"19750":{"h":"סנקלוס","r":"O01262","html":"<div class=\"sense\">, v. next wds.</div>","alt":["סנקלטורי","סִנְקְלִיט","סִנְקְלִיטוֹן"]},"19751":{"h":"סִנְקְלִיטוֹס","r":"O01263","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (σύγκλητος) </div><div class=\"sense\"><b>1)</b>  (= <span dir=\"rtl\">סנקליטיקוס</span>) <i>senator, councilor, counselor</i>. <span class=\"citation\">Ex. R. s. 46</span>.—Pl. <span dir=\"rtl\">סִנְקְלִיטִים</span>, <a href=\"#\" data-headword=\"סנקלוס\">סִנְקְלִיטִין</a>. Pesik. Zutr. Haăz. (ed. Bub. p. 113) (ref. to <span dir=\"rtl\">עתודים</span>, <span class=\"citation\">Deut. XXXII, 14</span>) <span dir=\"rtl\">אלו ס׳ שלהם</span> that means their (the Roman) senators (sent to the provinces); (<span class=\"citation\">Sifré Deut. 317</span> <a href=\"#\" data-headword=\"סנקירקים\">סנקנירקים</a>, Var. <a href=\"#\" data-headword=\"סנקירקים\">סנקירקים</a>; <span class=\"citation\">Yalk. ib. 944</span> <span dir=\"rtl\">סרקני דקין</span>). <span class=\"citation\">Y. Ber. IX, 13ᵈ</span> <span dir=\"rtl\">חילף את כל ס׳ שלו</span> he changed all his councilors; <span class=\"citation\">Y. Snh. XI, 30ᶜ</span> top (some ed. <a href=\"#\" data-headword=\"סנקלוס\">סנקליטון</a>, v. infra). <span class=\"citation\">Lev. R. s. 13</span> <span dir=\"rtl\">גחין ואמר לסִנְקְלִיטָין וכ׳</span> he bent down and said to his assessors, these three things (for which I put to death three persons) did I do in one night; <span class=\"citation\">Midr. Till. to Ps. LXXX</span> <span dir=\"rtl\">לסִנְקְלִיט שלו</span> (sing.; ed. Bub. <a href=\"#\" data-headword=\"סנקוטס\">סנקוטס</a>, oth. ed. <span dir=\"rtl\">טוקלוס</span>, <a href=\"#\" data-headword=\"סנקלוס\">סנקלוס</a>; corr. acc.). <span class=\"citation\">Gen. R. s. 8</span> <span dir=\"rtl\">מלך שהיו לו שני ס׳ וכ׳</span> a king that had two counselors, without whose consent he did nothing; <span class=\"citation\">Yalk. ib. 13</span>; a. fr.</div><div class=\"sense\"><b>—2)</b>  mostly <a href=\"#\" data-headword=\"סנקלוס\">סִנְקְלִיטוֹן</a> (ἡ σύγκλητος, accus.) <i>senate</i>, <i>assembly</i>. Y. Snh. l. c.; Y. Ber. l. c., v. supra. <span class=\"citation\">Deut. R. s. 6</span> <span dir=\"rtl\">תיקרי אומן של סנקליטור</span> (read: <span dir=\"rtl\">אִימָּן של סנקליטון</span>) let her be called the mother of the senate.—[<span class=\"citation\">Pirké d’R. El. ch. XLVIII</span>, <span dir=\"rtl\">סנקלטורי פרעה</span>, <span dir=\"rtl\">סנקליט׳</span>, read with <span class=\"citation\">Yalk. Ex. 169</span> <span dir=\"rtl\">ספקלטורי</span>, v. <a href=\"#\" data-headword=\"סְפִקְלָאטוֹר\">סְפִקְלָטוֹר</a>.]</div>","alt":["סִינְ׳","סוּנְ׳"]},"19752":{"h":"סנקליטור","r":"O01264","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"סִנְקְלִיטוֹס\">preced.</a></div>","alt":[]},"19753":{"h":"סִנְקְלִרטִיקוֹס","r":"O01265","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (συγκλητικός) <i>one of senatorial rank, senator</i>. <span class=\"citation\">Ex. R. s. 28</span> <span dir=\"rtl\">קרא לפלוני ס׳ וכ׳</span> call such and such a senator that he may come with you. <span class=\"citation\">Num. R. s. 18</span>.—Pl. <span dir=\"rtl\">סִנְקְלִיטִיקִים</span>, <span dir=\"rtl\">סִנְקְלִיטִיקִין</span>, <a href=\"#\" data-headword=\"סִנּוֹקֶרֶת\">סִינִ׳</a>. <span class=\"citation\">Sifré Deut. 317</span>; <span class=\"citation\">Yalk. ib. 944</span>, v. preced art.</div>","alt":["סִינְ׳"]},"19754":{"h":"סִנְקַתִּדְרוֹן","r":"O01266","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"סִנְקַתִּדְרוֹס\">next w.</a></div>","alt":["סִינ׳","סוּנְ׳"]},"19755":{"h":"סִנְקַתִּדְרוֹס","r":"O01267","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (συγκάθεδρος) <i>assessor</i>, <i>associate</i>. <span class=\"citation\">Gen. R. s. 49</span> <span dir=\"rtl\">מלך שהיה לו ס׳ אחד</span> (not … <a href=\"#\" data-headword=\"יָם\">ים</a>, … <span dir=\"rtl\">יס</span>; Ar. … <span dir=\"rtl\">רון</span>) a king who had an associate; <span dir=\"rtl\">עשיתי … ס׳ שלי</span> I have appointed him my associate. <span class=\"citation\">Gen. R. s. 78</span> רון … <span class=\"citation\">Ex. R. s. 43</span>, beg. <a href=\"#\" data-headword=\"סוּנְקְלִיטוֹס\">סוּנְקַתִּדְרוֹ</a> his associate regent. Tanḥ. <span class=\"citation\">Mishp. 5</span> <a href=\"#\" data-headword=\"סקנדרוס\">סקנדרוס</a>; ed. Bub. 3 <a href=\"#\" data-headword=\"סונדוקרוס\">סונדוקרוס</a> (corr. acc.); a. fr.—Pl. <a href=\"#\" data-headword=\"סִנְקַתִּדְרוֹן\">סִנְקַתִּדְרִין</a>, <a href=\"#\" data-headword=\"סִנְקְלִיטוֹס\">סִינְ׳</a>, <a href=\"#\" data-headword=\"סִינְטוֹמוֹס\">סוּנְ׳</a>. <span class=\"citation\">Yalk. Gen. 13</span> <span dir=\"rtl\">מלך שהיו לו ס׳ … חוץ מדעתן</span> a king who had associates without whose consent he did nothing; <span class=\"citation\">Gen. R. s. 8</span> <span dir=\"rtl\">סנקתדרון … חוץ מדעתו</span> (some ed. <span dir=\"rtl\">מדעתם</span>, corr. acc.). <span class=\"citation\">Yalk. Esth. 1057</span> <a href=\"#\" data-headword=\"סנקדרין\">סנקדרין</a> (corr. acc.).</div>","alt":["סִינְ׳","סוּנְ׳"]},"19756":{"h":"סִנָּרָא","r":"O01268","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"סִינָּרָא\">סִינָּרָא</a></div>","alt":[]},"19757":{"h":"סנריות","r":"O01269","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אָכְסִיגָרוֹן\">אָכְסִיגָרוֹן</a></div>","alt":[]},"19758":{"h":"סָס","r":"O01270","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (b. h.) <i>moth</i>, <i>worm</i>. <span class=\"citation\">Yoma 9ᵇ</span> ארז מגור מן הסס Ms. L. (v. Rabb. D. S. a. l. note 200) a cedar sawed out by the worm, v. <a href=\"#\" data-headword=\"*סַסְמָגוֹר\">סַסְמָגוֹר</a>.</div>","alt":[]},"19759":{"h":"סָסָא","r":"O01271","html":"<div class=\"sense\"> ch. </div><div class=\"sense\"><b>1)</b>  <a href=\"#\" data-headword=\"סָס\">same</a>. <span class=\"citation\">Targ. Prov. XXV, 20</span> (some ed. <a href=\"#\" data-headword=\"סימא\">סימא</a>, corr. acc.).—<span class=\"citation\">Y. Bets. II, 61ᶜ</span> top; Y. Maas. Sh. V, 56ᶜ top; <span class=\"citation\">Y. Ḥag. II, 78ᵃ</span> bot. <span dir=\"rtl\">ס׳ דקיסא מיניה וביה</span> (vers. of Meïri to <span class=\"citation\">Bets. 20ᵇ</span>) the worm of the wood comes out of itself (the wood); v. <a href=\"#\" data-headword=\"כַּסָּא I\"><span dir=\"rtl\">כַּסָּא</span> I</a>.—[</div><div class=\"sense\"><b>2)</b>  = <a href=\"#\" data-headword=\"סָאסָא\">סָאסָא</a> q. v.]</div>","alt":[]},"19760":{"h":"סַסְגּוֹנָא","r":"O01272","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (comp. of <a href=\"#\" data-headword=\"סָס\">סס</a>, v. <a href=\"#\" data-headword=\"סוּס\">סוּס</a> a. <a href=\"#\" data-headword=\"שׂוּשׂ\">שׂוּשׂ</a>, a. <a href=\"#\" data-headword=\"גַּוָּון ²\">גַּוְנָא</a>) [<i>of glistening color</i>,] <i>sasgona, sasg’vana</i> (Chald. rendition of <a href=\"#\" data-headword=\"תַּחַשׁ\">תַּחַשׁ</a>) </div><div class=\"sense\"><b>1)</b>  name of an animal the skin of which was used for covering the Tabernacle. <span class=\"citation\">Targ. Ex. XXV, 5</span>. <span class=\"citation\">Ib. XXVI, 14</span> (Y. <a href=\"#\" data-headword=\"סַסְגּוֹנָא\">ססגוו׳</a>); a. e.—<span class=\"citation\">Sabb. 28ᵃ</span> היינו דמתרגמינן ס׳ שסָס בגוונין הרבה Ar. (ed. <span dir=\"rtl\">ששָׂשׂ</span>) that is the reason why we translate (<i>tasḥash</i>) with <i>sasgona</i>, because it glistened with many colors.</div><div class=\"sense\"><b>—2)</b>  name of a <i>color</i>, <i>scarlet</i> (v. P. Sm. 2682). <span class=\"citation\">Targ. Cant. VII, 2</span> <span dir=\"rtl\">סנרלין דס׳</span> (not <span dir=\"rtl\">דססוגונא</span>) scarlet shoes (cmp. <span class=\"citation\">Ez. XVI, 10</span>).</div>","alt":["סַסְגְּוָו׳"]},"19761":{"h":"סַסְגּוֹנִיתָא","r":"O01273","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"סַסְגּוֹנָא\">preced.</a>) <i>uratic stone</i> (from its color; Ar. <i>colored spots on the skin</i>). <span class=\"citation\">Yeb. 64ᵇ</span> Ar. (ed. <a href=\"#\" data-headword=\"*סוּסְכִּינְתָּא\">סוּסְכִּינְתָּא</a>).</div>","alt":[]},"19762":{"h":"*סַסְמָגוֹר","r":"O01274","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (supposed to be a comp. of <a href=\"#\" data-headword=\"סָס\">סָס</a> a. <span dir=\"rtl\">מגיר</span>, cmp. <a href=\"#\" data-headword=\"מְגֵרָה\">מְגֵרָה</a>) [<i>a sawing worm</i>,] name of a species of <i>cedar</i> subject to decay. <span class=\"citation\">Yoma 9ᵇ</span> [read:] <span dir=\"rtl\">מאי ארז שהרקב שולט בו ס׳ …</span> what is the cedar over which decay has power?… Sasmagor (Ms. L. omits our w., and has only the explanation of it: <span dir=\"rtl\">ארז מגור מן הסס</span>, v. <a href=\"#\" data-headword=\"סָס\">סָס</a>; v. Rabb. D. S. a. l. note 200). [To the following <span dir=\"rtl\">מאי ס׳</span> what is S.?, the reply <span dir=\"rtl\">ארז מגור מן הסס</span> has obviously fallen out, whereas the subsequent <span dir=\"rtl\">אמר ר׳ אבא בת קול</span> resumes the discussion interrupted by <span dir=\"rtl\">מאי ארז וכ׳</span>;—different in comment.]</div>","alt":[]},"19763":{"h":"סָעַד","r":"O01275","html":"<div class=\"sense\"><b>1)</b> <i>to support, strengthen</i>. <span class=\"citation\">Lam. R. to II, 2</span>; <span class=\"citation\">Y. Taan. IV, 68ᵈ</span> bot. <span dir=\"rtl\">לא תִסְעוֹד</span>, v. <span dir=\"rtl\">סָבַף</span>. <span class=\"citation\">Midr. Till. to Ps. XLI, 3</span> אני סוֹעֲדוֹ ומעמידו I will strengthen and raise him (from his sick-bed); a. fr.</div><div class=\"sense\"><b>—2)</b>  (with or without <a href=\"#\" data-headword=\"לֵב\">לב</a>) <i>to satisfy the appetite, to satiate</i>. <span class=\"citation\">Midr. Till. to Ps. CIV, 15</span> <span dir=\"rtl\">הלחם סוֹעד</span> (ed. Bub. <span dir=\"rtl\">לבב</span>) bread satiates, v. <a href=\"#\" data-headword=\"מְזוֹנִיתָא\">מְזוֹנִיתָא</a>. <span class=\"citation\">Yalk. Lev. 675</span> (ref. to <span class=\"citation\">Lev. XXVI, 26</span>) <span dir=\"rtl\">לרבות כל סוֹעֲדֵי לחם</span> (fr. a noun <a href=\"#\" data-headword=\"סוֹעָד\">סוֹעָד</a>) this include all supports by bread (all substitutes of food); Sifra B’ḥuck. Par. 2, ch. VI <span dir=\"rtl\">מְסָעֲדֵי</span> or <span dir=\"rtl\">מִסְעֲדֵי</span>.</div><div class=\"sense\"><b>—3)</b>  (denom. of <a href=\"#\" data-headword=\"סְעוּדָה\">סְעוּדָה</a>) <i>to dine</i>. <span class=\"citation\">Ḥull. 7ᵇ</span> <span dir=\"rtl\">רצונך סְעוֹד אצלי</span> please dine with me. <span class=\"citation\">Erub. 53ᵇ</span> <span dir=\"rtl\">מדוע אינך סוֹעֵד</span> why dost thou not eat?; <span dir=\"rtl\">כבר סָעַדְתִּי וכ׳</span> I have had my meal in daytime; a. fr.—<span class=\"citation\">Sabb. 62ᵇ</span> <span dir=\"rtl\">במה סָעַדְתָּ היום</span> what did you dine on to-day? (a lascivious metaphor).—[<span class=\"citation\">Ib. 12ᵇ</span> <span dir=\"rtl\">ששכינה סועד</span>, v. <a href=\"#\" data-headword=\"*סָעַר I\"><span dir=\"rtl\">סָעַר</span> I</a>.]</div><div class=\"sense\"><b>Pi. סִיעֵד</b> <div class=\"sense\"><i>to support, assist</i>. <span class=\"citation\">Yalk. Num. 760</span> <span dir=\"rtl\">לסַעֲדָהּ</span> in order to keep her (the cow) steady (on the ship). <span class=\"citation\">Sabb. XVIII, 3</span> <span dir=\"rtl\">אבל מְסַעֲדִין</span> but you may assist (an animal in child-birth); expl. <span class=\"citation\">ib. 128ᵇ</span>. <span class=\"citation\">Ib.</span> (quot. fr. <span class=\"citation\">Tosef. ib. XV</span> (<span class=\"citation\">XVI), 2</span>) <span dir=\"rtl\">כיצד מסעדין אוחזין וכ׳</span> (Tosef. l. c. <span dir=\"rtl\">מסייעין</span>).</div></div>","alt":[]},"19764":{"h":"סְעַד","r":"O01276","html":"<div class=\"sense\"><b>1)</b> <i>to assist, help</i>. <span class=\"citation\">Targ. I Sam. VII, 12</span> (ed. Wil. <i>Pa</i>.).—<span class=\"citation\">Targ. Gen. XXVII, 37</span> (h. text <a href=\"#\" data-headword=\"סְמַךְ I\">סמך</a>); a. fr.—<span class=\"citation\">Lam. R. to II, 2</span> <span dir=\"rtl\">לא נִסְעוֹד וכ׳</span>, v. <a href=\"#\" data-headword=\"סְכַף\">סְכַף</a>.</div><div class=\"sense\"><b>—2)</b>  (with or without <a href=\"#\" data-headword=\"לִיבָּא\">לִיבָּא</a>) <i>to dine, eat</i>. <span class=\"citation\">Targ. Jud. XIX, 5</span>. <span class=\"citation\">Targ. Ps. XIV, 4</span>.—<span class=\"citation\">Gitt. 67ᵇ</span> <span dir=\"rtl\">מאי טעמא לא סָעֵיד מר גבן</span> why will you not dine with us?</div><div class=\"sense\"><b>—3)</b> <i>to satiate</i>, contrad. to <a href=\"#\" data-headword=\"זוּן I\">זון</a> and to <a href=\"#\" data-headword=\"גָּרַר I\">גרר</a>. <span class=\"citation\">Ber. 35ᵇ</span> <span dir=\"rtl\">חמרא סָעֵיד</span> wine satisfies; <span dir=\"rtl\">נהמא מִיסְעַד סעיד וכ׳</span> bread satisfies but does not exhilarate; a. e.</div><div class=\"sense\"><b>Pa. סַעֵיד</b> <div class=\"sense\"><i>to support, help</i>. <span class=\"citation\">Targ. II Chr. XXVIII, 23</span>. <span class=\"citation\">Targ. Y. Ex. XVII, 12</span>.</div></div><div class=\"sense\"><b>Ithpa. אִסְתָּעֵד</b> <div class=\"sense\"><i>to be supported</i>. <span class=\"citation\">Targ. Is. V, 6</span>.</div></div>","alt":["סְעוֹד","סְעֵיד"]},"19765":{"h":"סַעַד","r":"O01277","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"סְעַד\">preced.</a>) <i>support</i>, <i>auxiliary</i>. <span class=\"citation\">Tosef. Snh. II, 4</span> <span dir=\"rtl\">עושין אותן ס׳ לשנה</span> we consider each of these circumstances an auxiliary reason for intercalation; <span class=\"citation\">Snh. 11ᵃ</span>; Y. ib. I, 18ᵈ top (corr. acc.).</div>","alt":[]},"19766":{"h":"סְעַד ²","r":"O01278","html":"<div class=\"sense\"><b>1)</b>  <a href=\"#\" data-headword=\"סַעַד\">same</a>, <i>support</i>, <i>assistance</i>. <span class=\"citation\">Targ. I Kings X, 12</span> סעד Bxt. (ed. <a href=\"#\" data-headword=\"סְעַד\">סְעִיד</a>). <span class=\"citation\">Targ. Gen. XXI, 20</span>; a. fr.—<span class=\"citation\">Lam. R. to II, 2</span> <span dir=\"rtl\">ברייא בסַעֲדֵיכוֹן מן אלין</span> the Lord help you against these (Romans); (<span class=\"citation\">Y. Taan. IV, 69ᵃ</span> <span dir=\"rtl\">ברייכון סְעוֹדִינְכוֹן</span>, <a href=\"#\" data-headword=\"סְעוֹדוּנָא\">סְעוֹדוּנ׳</a>).—Pl. <span dir=\"rtl\">סַעֲדִין</span>, constr. <span dir=\"rtl\">סַעֲדֵי</span>. <span class=\"citation\">Targ. Y. Lev. XXVI, 26</span> (v. <a href=\"#\" data-headword=\"סָעַד\">סָעַד</a>).</div><div class=\"sense\"><b>—2)</b> <i>food</i>. <span class=\"citation\">Targ. Ruth II, 14</span>.—</div><div class=\"sense\"><b>*3)</b>  סַעֲדִין <i>root of the Cyperus Rotundus</i>. <span class=\"citation\">Gen. R. s. 72</span> (expl. <span dir=\"rtl\">דודאים</span>, <span class=\"citation\">Gen. XXX, 14</span>) <a href=\"#\" data-headword=\"ס׳\">ס׳</a> Ar. (ed. <a href=\"#\" data-headword=\"שְׂעוֹרִין\">שעורין</a>).</div>","alt":["סַעֲדָא I"]},"19767":{"h":"סַעֲדָא II","r":"O01279","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"סְעַד ²\">preced.</a>) <i>assistant, helper, follower.</i>—Pl. <span dir=\"rtl\">סַעֲדיָּיא</span>, <a href=\"#\" data-headword=\"ס׳\">ס׳</a>. <span class=\"citation\">Targ. O. Lev. XX, 5</span> <span dir=\"rtl\">סַעָדוֹהִי</span> ed. Berl. (not with <a href=\"#\" data-headword=\"ר\">ר</a>; oth. ed. <a href=\"#\" data-headword=\"סָהֲדָא\">סַ׳</a>; h. text <a href=\"#\" data-headword=\"מִשְׁפָּחָה\">משפחה</a>).</div>","alt":["סָעֲדָא"]},"19768":{"h":"סַעַדְתָּא","r":"O01280","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"סַעֲדָא II\">preced.</a> wds.) <i>sustenance</i>, <i>comfort</i>. <span class=\"citation\">Gen. R. s. 48</span> quot. in Rashi to <span class=\"citation\">Gen. XVIII, 5</span> (ed. <a href=\"#\" data-headword=\"מְזוֹנִיתָא\">מְזוֹנִיתָא</a>).</div>","alt":[]},"19769":{"h":"סְעוֹד","r":"O01281","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"סְעַד\">סְעַד</a></div>","alt":[]},"19770":{"h":"סָעוֹד","r":"O01282","html":"<div class=\"sense\"> m. = <a href=\"#\" data-headword=\"סְעוּדָה\">סְעוּדָה</a>. <span class=\"citation\">Y. Ber. II, 5ᵃ</span> bot. <span dir=\"rtl\">אם היו עושין עמו בסְעוֹדָן</span> if they work for him for their meals (the meals included in the wages).</div>","alt":[]},"19771":{"h":"סְעוּדָא","r":"O01283","html":"<div class=\"sense\"> f., v. <a href=\"#\" data-headword=\"סְעוּדְתָּא\">סְעוּדְתָּא</a></div>","alt":[]},"19772":{"h":"סְעוּדָה","r":"O01284","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"סָעַד\">סָעַד</a>) <i>meal, dinner; feast</i>. <span class=\"citation\">Yoma 75ᵇ</span> (ref. to <span class=\"citation\">Ex. XVI, 12</span>) <span dir=\"rtl\">קבע להן זמן ס׳</span> he (Moses) introduced for them fixed meal-times. <span class=\"citation\">Succ. 26ᵃ</span> <span dir=\"rtl\">סְעוּדַת קבע</span> a regular full meal, v. <a href=\"#\" data-headword=\"עַרְאַי\">עַרְאַי</a>. <span class=\"citation\">Tosef. Ber. IV, 10</span> <span dir=\"rtl\">מוסרין ס׳ לטבח</span> they put the banquet in charge of the cook; <span dir=\"rtl\">נתקלקל דבר בס׳</span> if anything is wrong in the banquet; <span class=\"citation\">B. Bath. 93ᵇ</span>. Tosef. l. c. 8 <span dir=\"rtl\">סדר הס׳</span> ed. Zuck. (Var. <a href=\"#\" data-headword=\"הֶסֵּיבָּה\">הֶסֵּיבָּה</a>); a. v. fr.—<span dir=\"rtl\">סעודת ארוסין</span>, <span dir=\"rtl\">ס׳ נישואין</span> &amp;c., v. respective determinants.—<span class=\"citation\">Ab. III, 16</span> <span dir=\"rtl\">הכל מתוקן לס׳</span> everything is prepared for the feast (the hereafter). <span class=\"citation\">Pesik. R. s. 41</span>, end, v. <a href=\"#\" data-headword=\"זָמַן\">זָמַן</a>.—Pl. <a href=\"#\" data-headword=\"סְרוּדָה\">סְעוּדוֹת</a>. <span class=\"citation\">Sabb. XVI, 2</span>. <span class=\"citation\">Ib. 117ᵇ</span>; a. fr.</div>","alt":[]},"19773":{"h":"סְעוֹדוּנָא","r":"O01285","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"סְעַד\">סְעַד</a>) <i>assistance</i>, <i>help</i>; trnsf. <i>helper</i>. <span class=\"citation\">Y. Taan. IV, 69ᵃ</span>, v. <a href=\"#\" data-headword=\"סְעַד ²\"><span dir=\"rtl\">סַעֲדָא</span> I</a>.</div>","alt":["סְעוֹדִינָא"]},"19774":{"h":"סְעוּדְתָּא","r":"O01286","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> Targ. II Esth. VI, 11. <span class=\"citation\">Targ. II Sam. XI, 8</span>.—<span class=\"citation\">Yoma 74ᵇ</span>; <span class=\"citation\">75ᵇ</span> <span dir=\"rtl\">מאן דאית ליה ס׳ וכ׳</span> he who has only one meal, let him eat it in daytime. <span class=\"citation\">Keth. 61ᵇ</span>; a. fr.—Pl. <a href=\"#\" data-headword=\"סְעוּדְתָּא\">סְעוּדָתָא</a>. <span class=\"citation\">Gitt. 38ᵇ</span> <span dir=\"rtl\">אחת קבעת ס׳ וכ׳</span> one family had their regular dining parties on the Sabbath &amp;c. Ib. <span dir=\"rtl\">סְעיּדָתַיְיהוּ</span> their entertainments; a. e.</div>","alt":["סְעוּדָא"]},"19775":{"h":"סְעוֹרָא","r":"O01287","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (סְעַר I) <i>visitation</i>. <span class=\"citation\">Targ. O. Num. XVI, 29</span> ed. Berl. (oth. ed. <a href=\"#\" data-headword=\"סַעֲרָא II\">סְעָרָא</a>; Var. <a href=\"#\" data-headword=\"סוּעֲרָא\">סוּעֲרָא</a>, <a href=\"#\" data-headword=\"סוּעֲרָא\">סוּעֲרָה</a>, <a href=\"#\" data-headword=\"סִבְכָא\">סִי׳</a>). <span class=\"citation\">Targ. Mic. VII, 4</span> <span dir=\"rtl\">סְעוּרַת</span> (constr.).</div>","alt":[]},"19776":{"h":"סְעוֹרִים","r":"O01288","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"><i>S’ʿorim, S’ʿoram</i>. <span class=\"citation\">B. Mets. 73ᵇ</span> <span dir=\"rtl\">רב סעורם</span>; <span class=\"citation\">M. Kat. 28ᵃ</span> <span dir=\"rtl\">רב שְׂעוֹרִים</span> (Ms. M. <a href=\"#\" data-headword=\"סְעוֹרִים\">סְעוֹרִים</a>).</div>","alt":["סְעוֹרָם"]},"19777":{"h":"סְעוֹרִין","r":"O01289","html":"<div class=\"sense\"><i>barley</i>, v. <a href=\"#\" data-headword=\"סְעַרְתָּא\">סְעַרְתָּא</a>.</div>","alt":[]},"19778":{"h":"סְעוֹרָנָא","r":"O01290","html":"<div class=\"sense\"> m. = <a href=\"#\" data-headword=\"סְעוֹרָא\">סְעוֹרָא</a>. <span class=\"citation\">Targ. Hos. IX, 7</span>. <span class=\"citation\">Targ. Jer. XI, 23</span>. <span class=\"citation\">Ib. XXIII, 12</span> (ed. Lag. <a href=\"#\" data-headword=\"סוֹעֲרָן\">סוֹעֲרָן</a>).</div>","alt":[]},"19779":{"h":"*סְעוּתָא","r":"O01291","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<span dir=\"rtl\">נסע</span>; cmp. <span dir=\"rtl\">נסח</span> a. <span dir=\"rtl\">נסע</span>) = <a href=\"#\" data-headword=\"סְחוּתָא\">סְחוּתָא</a>, <i>sweepings</i>. Pesik. ʿAsser, p. 95ᵇ מן סְעוּתֵיה דביתך וכ׳ Ar. (ed. Bub. <span dir=\"rtl\">פחותיה</span>) out of the sweepings of thy house thou mightest give me so much; [Tanḥ. R’eh 10 <a href=\"#\" data-headword=\"סְחוֹרָה\">סחורה</a>; ed. Bub. 4 <span dir=\"rtl\">סחורתא</span> (read: <span dir=\"rtl\">סחותא</span>); Var. in a gloss <a href=\"#\" data-headword=\"חֶרְוָותָא\">חֶרְוָותָא</a>; Var. in Ar. s. v. <a href=\"#\" data-headword=\"*סְעוּתָא\">סעותא</a>: <span dir=\"rtl\">חֶרְוָותֵיה</span>, <span dir=\"rtl\">חֶרְוָתֵיה</span>, v. <a href=\"#\" data-headword=\"חָרֵי\">חָרֵי</a>.]</div>","alt":[]},"19780":{"h":"*סעל","r":"O01292","html":"<div class=\"sense\">, a word in an enigmatic speech, <span class=\"citation\">Koh. R. to I, 8</span> <span dir=\"rtl\">ס׳ לרפאתו</span>, perh. to be read: <a href=\"#\" data-headword=\"סַעַד\">סַעַד</a> <i>help</i>; [Matt. K. suggests <span dir=\"rtl\">חַּעַל</span>].</div>","alt":[]},"19781":{"h":"*סָעַר I","r":"O01293","html":"<div class=\"sense\"> (cmp. <a href=\"#\" data-headword=\"סוּר\">סוּר</a>) <i>to go around; to visit</i>. <span class=\"citation\">Sabb. 12ᵇ</span> מנין שהקב&quot;ה סוֹעֵר את החולה Ms. M. (Ar. <span dir=\"rtl\">סר</span>; ed. <span dir=\"rtl\">שהשכינה סועד</span>) whence is it proven that the Lord visits the sick?—Answ. ref. to <span dir=\"rtl\">יסעדנו</span> (<span class=\"citation\">Ps. XLI, 4</span>), [to which is added in Ar.: <span dir=\"rtl\">קרי ביה יִסְעָרֶנּוּ</span> read it <i>yisʿarennu</i> ‘shall visit him].</div>","alt":[]},"19782":{"h":"סְעַר","r":"O01294","html":"<div class=\"sense\">, (corresp. to h. <span dir=\"rtl\">פקד</span>) <i>to visit, examine</i>. <span class=\"citation\">Targ. I Kings IX, 12</span> (ed. Lag. <span dir=\"rtl\">למחזי</span>). <span class=\"citation\">Targ. I Sam. XIV, 17</span>.—Esp. <a href=\"#\" data-headword=\"ס׳\">ס׳</a> (<a href=\"#\" data-headword=\"ל\">ל</a>)שלם <i>to inquire after a person’s health</i>. <span class=\"citation\">Ib. XVII, 18</span> (ed. Wil. <a href=\"#\" data-headword=\"תַּסְקוֹפָא\">תַּסְ׳</a> <i>Af.</i>). <span class=\"citation\">Targ. II Kings X, 13</span> (ed. Wil. <span dir=\"rtl\">למסעד</span>, corr. acc.; v. Koh. Ar. Compl. s. v. <a href=\"#\" data-headword=\"*סָעַר I\">סער</a>).</div><div class=\"sense\"><b>Af. אַסְעַר</b> <div class=\"sense\"><b>1)</b>  <a href=\"#\" data-headword=\"*סָעַר I\">same</a>, v. supra.</div><div class=\"sense\"><b>—2)</b>  (with <span dir=\"rtl\">על</span> of person) <i>to visit upon</i>. <span class=\"citation\">Targ. Job XXXIV, 29</span>. <span class=\"citation\">Ib. XXXVI, 23</span> אַסְעַר Ms. (ed. <span dir=\"rtl\">יִסְעַר</span>, read <span dir=\"rtl\">יַסְ׳</span>). <span class=\"citation\">Targ. O. Lev. XXVI, 16</span>; a. fr.</div></div><div class=\"sense\"><b>Ithpa. אִסְתַּעַר</b> <div class=\"sense\"><i>to be visited; to be inflicted upon</i>. <span class=\"citation\">Targ. O. Num. XVI, 29</span> (some ed. <span dir=\"rtl\">יִסְתְּ׳</span>, <i>Ithpe.</i>).</div></div>","alt":[]},"19783":{"h":"סָעַר II","r":"O01295","html":"<div class=\"sense\"><i>to be rough; to be in commotion</i>.</div><div class=\"sense\"><b>Pi. סִיעֵר</b> <div class=\"sense\"><i>to stir up, to blow.</i> <span class=\"citation\">Kil. V, 7</span> <span dir=\"rtl\">וסִיעַרְתֹּו הרוח לאחריו</span> and the wind drove the seed backward; <span class=\"citation\">Tosef. ib. III, 12</span> <a href=\"#\" data-headword=\"סייתו\">סייתו</a>, <span dir=\"rtl\">סייעתו</span>, <span dir=\"rtl\">הסעורתו</span> ed. Zuck. (corr. acc., v. infra). <span class=\"citation\">B. Bath. 25ᵃ</span> (ref. to <span dir=\"rtl\">שעירם</span>, <span class=\"citation\">Deut. XXXII, 2</span>) <span dir=\"rtl\">זו … שמְסָעֶרֶת וכ׳</span> that is the east wind which stirs up the whole world like a <i>saʿir</i> (demon); [<span class=\"citation\">Sifré Deut. 306</span> <span dir=\"rtl\">שמשחיד וכ׳</span>; <span class=\"citation\">Yalk. ib. 942</span> <span dir=\"rtl\">שמשחרת</span> which makes the sky black like goats.</div></div><div class=\"sense\"><b>Hif. הִסְעִיר</b> <div class=\"sense\"> <a href=\"#\" data-headword=\"סְעַר\">same</a>. Tosef. l. c. <span dir=\"rtl\">והסעורתו</span>, read: <span dir=\"rtl\">יהִסְעִירָתוֹ</span>, v. supra. <span class=\"citation\">Num. R. s. 9</span> (play on <a href=\"#\" data-headword=\"שְׁעָרִים\">שְׂעֹרִים</a>, <span class=\"citation\">Num. V, 15</span>) <span dir=\"rtl\">והִסְעִירָם הב&quot;ה וכ׳</span> (not <span dir=\"rtl\">והסעידה</span>) and the Lord scattered them among the nations (with ref. to <span class=\"citation\">Zech. VII, 14</span>).</div></div>","alt":[]},"19784":{"h":"סְעַר ²","r":"O01296","html":"<div class=\"sense\">; <i>Ithpa.</i> אִסְתַּעַר <i>to be excited, troubled</i>. <span class=\"citation\">Targ. II Kings VI, 11</span>.</div>","alt":[]},"19785":{"h":"סֵעָר","r":"O01297","html":"<div class=\"sense\"><i>hair</i>, v. <a href=\"#\" data-headword=\"שֵׂעָר\">שֵׂעָר</a>.</div>","alt":[]},"19786":{"h":"סְעָר","r":"O01298","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"סֵעָר\">preced. art.</a>; cmp. <a href=\"#\" data-headword=\"זוּף\">זוּף</a> II a. <a href=\"#\" data-headword=\"זַיִף\">זַיִף</a>) <i>hair</i>. <span class=\"citation\">Targ. O. Gen. XXV, 25</span> ed. Berl.; a. fr. [Mostly with <span dir=\"rtl\">שׂ</span>, v. <a href=\"#\" data-headword=\"שַׂעֲרָא\">שַׂעֲרָא</a>.]—<span class=\"citation\">Y. Naz. IX, end, 58ᵃ</span> <a href=\"#\" data-headword=\"סַעֲרָה\">סַעֲרָה</a>, v. <a href=\"#\" data-headword=\"שַׂעֲרָא\">שַׂעֲרָא</a>.—Pl. <a href=\"#\" data-headword=\"סַעֲרָן\">סַעֲרָן</a> f. <span class=\"citation\">Targ. Ps. LXIX, 5</span> (Ms. <a href=\"#\" data-headword=\"סְעָרַיָּא\">סַעֲרִין</a>).</div>","alt":["סַעַר","סַעֲרָא I"]},"19787":{"h":"סַעֲרָא II","r":"O01299","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><i>visitation</i>, v. <a href=\"#\" data-headword=\"סְעוֹרָא\">סְעוֹרָא</a>.</div>","alt":["סְעָרָא"]},"19788":{"h":"סַעֲרָה","r":"O01300","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"סְעָר\">סְעָר</a></div>","alt":[]},"19789":{"h":"סְעָרָה I","r":"O01301","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><i>storm-wind</i>; (hypostatised) <i>the wind-bag</i>. <span class=\"citation\">Ḥag. 12ᵇ</span> <span dir=\"rtl\">רוח בס׳</span> the wind rests on the storm, for we read (<span class=\"citation\">Ps. CXLVIII, 8</span>) as to the wind (<i>ruaḥ</i>), storm does its bidding; <span dir=\"rtl\">וס׳ תלויה וכ׳</span> (not <a href=\"#\" data-headword=\"תְּלוֹי\">תלוי</a>) and the storm depend son the arm of the Lord; Yalk. Am. 543; <span class=\"citation\">Yalk. Ps. 883</span>; <span class=\"citation\">Y. Ḥag. II, beg. 77ᵃ</span> <span dir=\"rtl\">הרוח תלויה בס׳</span> the <i>ruaḥ</i> depends on the <i>s’ʿarah</i>; <span dir=\"rtl\">וס׳ עשאה הקב&quot;ה כמין וכ׳</span> and the Lord has made the <i>s’ʿarah</i> a sort of charm and suspended it on his arm; a. e.</div>","alt":[]},"19790":{"h":"סְעָרָה II","r":"O01302","html":"<div class=\"sense\"> (v. <a href=\"#\" data-headword=\"סְעָר\">סְעָר</a>) = <a href=\"#\" data-headword=\"שַׂעֲרָה\">שַׂעֲרָה</a>, <i>hair</i>. <span class=\"citation\">B. Bath. 16ᵃ</span> (ref. to <a href=\"#\" data-headword=\"שַׂעֲרָה\">שערה</a>, <span class=\"citation\">Job IX, 17</span>, a.</div>","alt":[]},"19791":{"h":"סערה","r":"O01303","html":"<div class=\"sense\"> ib. ib. XXXVIII, </div><div class=\"sense\"><b>1)</b>  איוב בס׳ חירף ובס׳ השיבוהו … Job when blaspheming used the word <i>s’ʿarah</i> (storm, anger), … and he was answered with <i>s’ʿarah</i>, for we read, And the Lord answered Job (by argument) from the <i>s’ʿarah</i> (the hair of man), v. <a href=\"#\" data-headword=\"נִימָה\">נִימָה</a>; <span class=\"citation\">Nidd. 52ᵃ</span> <span dir=\"rtl\">בשְׂעָרָה חירף בס׳ וכ׳</span>.</div>","alt":[]},"19792":{"h":"סְעָרַיָּא","r":"O01304","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"><i>barley</i>, v. <a href=\"#\" data-headword=\"סְעַרְתָּא\">סְעַרְתָּא</a>.</div>","alt":["סְעָרֵי","סְעָרִין"]},"19793":{"h":"סַעֲרָן","r":"O01305","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (סַעֲרָא I) <i>hairy</i>. <span class=\"citation\">Targ. O. Gen. XXVII, 11</span> ed. Berl. (oth. ed. a. Y. <a href=\"#\" data-headword=\"סָהֲדָא\">שַׂ׳</a>).—Pl. fem. <span dir=\"rtl\">סַעֲרַנְיָין</span>. Ib. 23, ed. Berl. (oth. ed. <a href=\"#\" data-headword=\"שְׂעִירַן\">שְׂעִירַן</a>; Y. <a href=\"#\" data-headword=\"שַׂעֲרָן\">שערניין</a>).</div>","alt":[]},"19794":{"h":"סערניא","r":"O01306","html":"<div class=\"sense\">, <span class=\"citation\">Targ. O. Ex. IX, 31</span> ed. Vien., v. <a href=\"#\" data-headword=\"סְעַרְתָּא\">next w.</a></div>","alt":[]},"19795":{"h":"סְעַרְתָּא","r":"O01307","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (collect. noun) = h. <a href=\"#\" data-headword=\"שַׂעֲרָה\">שְׂעֹרָה</a>, <i>barley</i>. <span class=\"citation\">Targ. Y. Ex. IX, 31</span> <a href=\"#\" data-headword=\"סַרְתָּא\">סַרְתָּא</a> (contr. of <span dir=\"rtl\">סְעַרְ׳</span>). <span class=\"citation\">Targ. Job XXXI, 40</span> (some ed. <a href=\"#\" data-headword=\"סְעַרְתָּא\">סַעֲרָתָא</a> <i>pl.</i>).—<i>Pl.</i> <a href=\"#\" data-headword=\"סְעָרַיָּא\">סְעָרִין</a>, <a href=\"#\" data-headword=\"סְעָרַיָּא\">סְעָרֵי</a>, <a href=\"#\" data-headword=\"סְעָרַיָּא\">סְעָרַיָּא</a>, <a href=\"#\" data-headword=\"סְעוֹרִין\">סְעוֹרִין</a>. Targ. O. Ex. l. c. (ed. Vien. <a href=\"#\" data-headword=\"סְעָרַיָּא\">סַעֲרֵי</a>; <a href=\"#\" data-headword=\"סערניא\">סערניא</a>, corr. acc.). <span class=\"citation\">Targ. O. Num. V, 15</span> ed. Berl. (oth. ed. <a href=\"#\" data-headword=\"סוֹכָה\">שׂ׳</a>). <span class=\"citation\">Targ. Is. XXVIII, 25</span>. <span class=\"citation\">Targ. Ruth III, 15</span>; <span class=\"citation\">17</span>; a. e.—Y. M. Kat. I, beg. 80ᵃ <span dir=\"rtl\">דהוות זריעה ס׳</span> (not <span dir=\"rtl\">דהוון</span>) which was planted with barley. <span class=\"citation\">Pes. 42ᵇ</span> <span dir=\"rtl\">דשדי ביה שערי</span> they put barley into it (the grape vinegar); a. e.</div>","alt":[]},"19796":{"h":"סַף","r":"O01308","html":"<div class=\"sense\"> part. a. perf. of <a href=\"#\" data-headword=\"סוּף\">סוּף</a>.</div>","alt":["סָף"]},"19797":{"h":"סַף ²","r":"O01309","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> , v. <a href=\"#\" data-headword=\"סוּף\">סוּף</a>, <i>to cut, hollow out</i>; also <i>to put ends together, join</i>) </div><div class=\"sense\"><b>1)</b> <i>door-sill</i>; </div><div class=\"sense\"><b>2)</b> <i>bowl</i>. Mekh. Bo, s. 6 (ref. to <span class=\"citation\">Ex. XII, 22</span>) <span dir=\"rtl\">מניד הכתוב … ואין סף אלא אסקופה</span> the text intimates that he loosens and digs a hole on the side of the threshold and slaughters over it, for <i>saf</i> means (a cavity made in) the threshold. Ib. <span dir=\"rtl\">אין סף אלא כלי</span> <i>saf</i> means a vessel; <span class=\"citation\">Y. Pes. IX, 36ᵈ</span> bot., sq.</div><div class=\"sense\"><b>—3)</b> pl. <a href=\"#\" data-headword=\"סִיפִּים\">סִפִּים</a>, <a href=\"#\" data-headword=\"סִיפִּים\">סִפִּין</a>, <a href=\"#\" data-headword=\"סִבְכָא\">סִי׳</a> [<i>cut stones</i>, cmp. <a href=\"#\" data-headword=\"גָּזִית\">גָּזִית</a>,] <i>paving-blocks, stone-pavement</i>. <span class=\"citation\">Midr. Till. to Ps. LXXVIII, 45</span> <span dir=\"rtl\">והס׳ נבקעין וכ׳</span> and the blocks burst before them (the frogs). <span class=\"citation\">Midr. Till. to Ps. CV, 30</span> <span dir=\"rtl\">בתי הס׳</span> houses which had stone pavements; (Yalk. ib. 820 <span dir=\"rtl\">פספסין</span>; <span class=\"citation\">Ex. R. s. 10</span> <span dir=\"rtl\">פסיפס</span>).</div>","alt":[]},"19798":{"h":"סִפָּא","r":"O01310","html":"<div class=\"sense\"><b>1)</b> <i>door-sill, door-post</i>; also (v. <a href=\"#\" data-headword=\"סֵיפָא\">סֵיפָא</a>) <i>border</i>, <i>bank</i>. <span class=\"citation\">Targ. Ez. XL, 6</span>, sq. <span class=\"citation\">Targ. I Sam. I, 9</span>. <span class=\"citation\">Targ. II Kings X, 21</span>; <span class=\"citation\">ib. XXI, 16</span> (<a href=\"#\" data-headword=\"סֵיפָא\">סֵיפָא</a>; h. text <a href=\"#\" data-headword=\"פה\">פה</a>; v. Pesh. <span class=\"citation\">Josh. III, 15</span>); a. fr.—<span class=\"citation\">Gitt. 68ᵇ</span> bot. <span dir=\"rtl\">בסי׳ דבבא</span> at the door-post.—Pl. <a href=\"#\" data-headword=\"סִיפִּים\">סִפִּין</a>, <a href=\"#\" data-headword=\"סַפְיָא\">סִפַּיָּא</a>, <span dir=\"rtl\">סִפֵּי</span>, <a href=\"#\" data-headword=\"סִבְכָא\">סִי׳</a>. <span class=\"citation\">Targ. Ex. XII, 7</span> (some ed. <a href=\"#\" data-headword=\"סִפְלָא\">סִיפַ׳</a>). <span class=\"citation\">Targ. Deut. VI, 9</span>; <span class=\"citation\">XI, 20</span> (some ed. <span dir=\"rtl\">סִיפֵי</span>, <a href=\"#\" data-headword=\"סִפָּא\">סֵי׳</a>). <span class=\"citation\">Targ. Prov. VIII, 34</span> <a href=\"#\" data-headword=\"ספי\">ספי</a> (Ms. a. some ed. <a href=\"#\" data-headword=\"פכי\">פכי</a>, corr. acc.); a. e.</div><div class=\"sense\"><b>—2)</b>  (v. <a href=\"#\" data-headword=\"סַף ²\">preced.</a> 3) <i>block, a course of blocks, layer</i> (v. <a href=\"#\" data-headword=\"נִדְבָּךְ\">נִדְבָּךְ</a>). <span class=\"citation\">B. Bath. 5ᵇ</span> כל ס׳ וס׳ זימניה הוא Ar. (ed. <a href=\"#\" data-headword=\"שִׁפָּא I\">שפא</a>) every time he finishes a layer, it is his time (to get paid); ib. 6ᵃ (ed. <a href=\"#\" data-headword=\"שפי\">שפה</a>). Ib. 4ᵃ <span dir=\"rtl\">אפיק ס׳ ועייל ס׳</span> (some ed. <a href=\"#\" data-headword=\"שפי\">שפה</a>) he let one block protrude (beyond the line) and one block recede; <span class=\"citation\">Yalk. Deut. 913</span> <a href=\"#\" data-headword=\"שִׁפָּא I\">שפא</a>.—Pl. <a href=\"#\" data-headword=\"סְפָיִין\">סְפָיִין</a> (h. form, as if from <a href=\"#\" data-headword=\"סְפָי\">סְפָי</a>, v. <a href=\"#\" data-headword=\"ספי\">סָפָה</a>). <span class=\"citation\">Y. Sabb. VII, 10ᵈ</span> top <span dir=\"rtl\">דעבד ס׳</span> who lays a course of blocks; ib. XII, beg. 13ᶜ</div>","alt":["סִיפָּא","(סִיפָא","סֵי׳)"]},"19799":{"h":"סְפָא","r":"O01311","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"סְפֵי\">סְפֵי</a></div>","alt":[]},"19800":{"h":"סְפָאוֹת","r":"O01312","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"סְפָי\">סְפָי</a></div>","alt":["(סְפָאיוֹת)"]},"19801":{"h":"סָפַג","r":"O01313","html":"<div class=\"sense\"> (denom. of <a href=\"#\" data-headword=\"סְפוֹג\">סְפוֹג</a>) </div><div class=\"sense\"><b>1)</b> <i>to swallow, absorb</i>. <span class=\"citation\">Cant. R. to VII, 3</span> <span dir=\"rtl\">מה חטה זו סוֹפֶגֶת … סוֹפְגִין וכ׳</span> as the wheat (flour) absorbs (water), so Israel absorbs &amp;c. <span class=\"citation\">Ab. V, 15</span>, v. <a href=\"#\" data-headword=\"סְפוֹג\">סְפוֹג</a>; a. e.—Trnsf. (cmp. <a href=\"#\" data-headword=\"לְקָא\">לָקָה</a>, <a href=\"#\" data-headword=\"בְּלַע\">בְּלַע</a>) <i>to receive lashes, be punished</i>. <span class=\"citation\">Tem. I, 1</span>, a. fr. <span dir=\"rtl\">סוֹפֵג את הארבעים</span> receives forty (thirty-nine) lashes. <span class=\"citation\">Naz. IV, 3</span> <span dir=\"rtl\">אם אינה סופגת … תִּסְפּוֹג וכ׳</span> if she cannot receive the Biblical punishment, let her receive the punishment for rebellion; a. fr.</div><div class=\"sense\"><b>—2)</b> <i>to use a</i> <a href=\"#\" data-headword=\"סְפוֹג\">סְפוֹג</a>, <i>to wipe, dry</i>. <span class=\"citation\">Sabb. XXII, 1</span> <span dir=\"rtl\">לא יִסְפּוֹג</span> (Ar. <span dir=\"rtl\">יְסַפֵּג</span> <i>Pi.</i>) he must not put down a sponge (to absorb the spilt wine). <span class=\"citation\">Zeb. VI, 5</span> <span dir=\"rtl\">סְפָגוֹ במלח</span> he dried the dripping head of the sacrifice by rubbing salt on it. <span class=\"citation\">Tosef. ib. VII, 10</span> <span dir=\"rtl\">מלח ולא ס׳ ס׳ וכ׳</span> if he put salt on but did not dry it, or if he dried it without putting salt on; a. e.—<span class=\"citation\">Sabb. 145ᵃ</span> לסוֹפְגָן במלח Ar. (ed. <span dir=\"rtl\">לסופתן</span>, v. <a href=\"#\" data-headword=\"סָפַת\">סָפַת</a>).—[<span class=\"citation\">Tosef. Zab. I, 9</span> <span dir=\"rtl\">וסופג</span>, read: <span dir=\"rtl\">וסִפּוּג</span>.—<span class=\"citation\">Yalk. Deut. 840</span> <span dir=\"rtl\">סופגין</span>, read: <span dir=\"rtl\">סופנין</span>, v. <a href=\"#\" data-headword=\"סָפַן\">סָפַן</a>.]</div><div class=\"sense\"><b>Pi. סִיפֵּג</b> <div class=\"sense\"> <a href=\"#\" data-headword=\"סְפָאוֹת\">same</a>; v. supra, a. infra.</div></div><div class=\"sense\"><b>Hif. הִסְפִּיג</b> <div class=\"sense\"><b>1)</b> <i>to wipe, dry</i>. <span class=\"citation\">Men. 7ᵇ</span> <span dir=\"rtl\">וטבל ולא מַסְפִּיג</span> (Rashi: <span dir=\"rtl\">מְסַפֵּג</span> <i>Pi.</i>) he must dip (<span class=\"citation\">Lev. IV, 6</span>) but not wipe, i.e. there must be blood enough in the vessel to dip the finger into it; <span class=\"citation\">Yalk. Lev. 469</span>; <span class=\"citation\">Zeb. 93ᵇ</span> <span dir=\"rtl\">מְסַפֵּג</span>. <span class=\"citation\">Num. R. s. 17</span> <span dir=\"rtl\">נטלו והִסְפִּיגוֹ</span> he took it (the flayed ram) and wiped it (with salt, v. supra); a. e.</div><div class=\"sense\"><b>—2)</b> <i>to receive drippings, collect</i>. <span class=\"citation\">Gen. R. s. 94</span> <span dir=\"rtl\">כשרף הזה … עד שמַסְפִּיגִין אותו</span> like resin which scarcely begins to ooze out, when arrangements are made to collect it; Tanḥ. B’midb. 16 (not <span dir=\"rtl\">השבט</span>); ed. Bub. ib. 19; Yalk. Ezra 1067.</div></div><div class=\"sense\"><b>Hithpa. הִסְתַּפֵּג</b> </div><div class=\"sense\"><b>Nithpa. נִסְתַּפֵּג</b> <div class=\"sense\"><i>to be wiped off, dried</i>. Num. R. l. c. <span dir=\"rtl\">כאילו יצחק מִסְתַּפֵּג לפניך</span> as if Isaac’s blood had been wiped off. <span class=\"citation\">Sabb. XXII, 5</span> <span dir=\"rtl\">הריחץ … ונ׳</span> if one bathed … and dried himself &amp;c. Ib. <span dir=\"rtl\">מִסְתַּפְּגִין וכ׳</span> wipe themselves with one sheet. <span class=\"citation\">Yoma III, 4</span>. <span class=\"citation\">Tosef. Zab. I, 9</span> <span dir=\"rtl\">כדי … ויִסְתַּפֵּג</span> time enough for a person to bathe, come up and dry himself; a. fr.</div></div>","alt":[]},"19802":{"h":"סֶפֶג","r":"O01314","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"סָפַג\">preced.</a>) <i>drying, wiping.</i> <span class=\"citation\">Kil. IX, 3</span> <span dir=\"rtl\">מטפחות הס׳</span> (Ar. <span dir=\"rtl\">הסִפּוּג</span>) towels.</div>","alt":[]},"19803":{"h":"סָפַד","r":"O01315","html":"<div class=\"sense\"> (b. h.) [<i>to strike, beat;</i> cmp. Lat. plango,] <i>to lament, mourn</i>. <span class=\"citation\">Gitt. 57ᵃ</span> <span dir=\"rtl\">סִיפְדוּ לזה</span> mourn for this man. <span class=\"citation\">Snh. 47ᵃ</span>, a. e. <span dir=\"rtl\">אל תִּסְפְּדוּנִי וכ׳</span> do not hold services for me in the towns; a. fr.</div><div class=\"sense\"><b>Hif. הִסְפִּיד</b> <div class=\"sense\"><i>to arrange funeral</i> or <i>memorial services for; to lament, eulogise</i>. <span class=\"citation\">M. Kat. I, 5</span> <span dir=\"rtl\">ולא יַסְפִּידֶנּוּ קידם וכ׳</span> and must not engage a <i>safdan</i> (eulogist) for him thirty days before a festival. <span class=\"citation\">Meg. 28ᵇ</span> <span dir=\"rtl\">אין מַסְפִּידִין בהן וכ׳</span> no funeral services for an individual must be held in them (the synagogues); <span dir=\"rtl\">ומספידין … רבים</span> but you may use them for funeral services in cases of public mourning (for a distinguished person). <span class=\"citation\">Treat. S’maḥ. III, 4</span> <span dir=\"rtl\">מספידין לעניים וכ׳</span> mourning services are held for children of poor men at the age of three, for those of rich men at the age of four years. <span class=\"citation\">M. Kat. 21ᵇ</span> <span dir=\"rtl\">והִסְפִּידוּם הספד גדול</span> and they arranged a great lamentation over them (the sons of R. ‘Aḳiba); a. fr.</div></div><div class=\"sense\"><b>Nif. נִסְפַּד</b> <div class=\"sense\"><i>to be mourned for, be eulogised</i>. <span class=\"citation\">Snh. 47ᵃ</span> <span dir=\"rtl\">מת לא נ׳ וכ׳</span> a dead not mourned for and not buried. <span class=\"citation\">Yeb. 78ᵇ</span> <span dir=\"rtl\">שלא נ׳ כהלכה</span> no appropriate lamentations were held over his remains; a. e.</div></div>","alt":[]},"19804":{"h":"סְפַד","r":"O01316","html":"<div class=\"sense\"> <span class=\"citation\">Targ. Gen. XXIII, 2</span>; a. fr.—<span class=\"citation\">Yeb. 116ᵇ</span> <span dir=\"rtl\">סִפְדִי בעליך</span> observe mourning for thy husband. <span class=\"citation\">M. Kat. 28ᵇ</span> <span dir=\"rtl\">דִּיסְ׳ וִסְפְּדוּנֵוה</span> for him who has mourned for others, others will mourn; <span class=\"citation\">Keth. 72ᵃ</span> <a href=\"#\" data-headword=\"דִּיסְקְרִין\">דִּסְ׳</a>; <span class=\"citation\">Tosef. ib. VII, 6</span> <span dir=\"rtl\">סְפוֹד דיִסְפְּדוּנָךְ</span> mourn, in order that people may mourn for thee; Y. ib. VII, 31ᵇ bot. (corr. acc.). Meg. Taan. ch. I; <span class=\"citation\">Sabb. 21ᵇ</span>, a. fr. <span dir=\"rtl\">דלא למִסְפֵּד</span> when no lamentations may be held; a. fr.</div><div class=\"sense\"><b>Af. אַסְפֵּיד</b> <div class=\"sense\"><b>1)</b>  as <a href=\"#\" data-headword=\"סָפַד\">preced.</a> <i>Hif.</i> <span class=\"citation\">Targ. Lam. I, 18</span>.—<span class=\"citation\">M. Kat. 25ᵇ</span> <span dir=\"rtl\">ההוא יומא לא אתו לאַסְפּוּדֵיה</span> that day (when he died), they did not come to mourn for him. <span class=\"citation\">Meg. 28ᵇ</span> <span dir=\"rtl\">אַכְפְּדָהּ לכלתיה וכ׳</span> held funeral services for his daughter-in-law in the synagogue; a. fr.</div><div class=\"sense\"><b>—2)</b> <i>to beat the hip in mourning</i>. <span class=\"citation\">Koh. R. to XII, 7</span> <span dir=\"rtl\">הוה מַסְפִּיד בחדא ידא וכ׳</span> made the motion of mourning with one hand and of praising (Nebuchadnezzar) with the other; <span class=\"citation\">Yalk. Ez. 364</span> <span dir=\"rtl\">הוון … ומַסְפִּידִין וכ׳</span>.</div></div>","alt":[]},"19805":{"h":"סָפְדָּא","r":"O01317","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"סְפַד\">preced.</a>) <i>mourner</i>, <i>wailer</i>.—Pl. <span dir=\"rtl\">סָפְדַּיָּא</span>. <span class=\"citation\">Targ. Koh. XII, 5</span> (some ed. <span dir=\"rtl\">סוֹפְדַיָּא</span>). <span class=\"citation\">Targ. Y. Lev. XIII, 45</span> <span dir=\"rtl\">ועל ס׳ יהוי מהלך</span> (not <span dir=\"rtl\">ספריא</span>) and he shall go around to the wailers (v. <span class=\"citation\">M. Kat. 5ᵃ</span>).</div>","alt":[]},"19806":{"h":"סִפְדָּא","r":"O01318","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"סוֹפְדָא\">סִופְדָּא</a></div>","alt":[]},"19807":{"h":"סַפְדָּן","r":"O01319","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"סִפְדָּא\">preced.</a> wds.) <i>hired mourner, speaker at funerals</i> or <i>memorial services</i>. <span class=\"citation\">M. Kat. 8ᵃ</span> <span dir=\"rtl\">בא ס׳ וכ׳</span> a wailer came and placed himself at the door (offering his services).—Pl. <span dir=\"rtl\">סַפְדָּנִים</span>, <span dir=\"rtl\">סַפְדָּנִין</span>. <span class=\"citation\">Ber. 62ᵃ</span> <span dir=\"rtl\">כשם … מן הס׳ וכ׳</span> as the dead are called to account (for their deeds), so the wailers and those who respond after them will be made responsible (for their eulogies).</div>","alt":[]},"19808":{"h":"סַפְדָּנָא","r":"O01320","html":"<div class=\"sense\"> <span class=\"citation\">M. Kat. 8ᵃ</span> <span dir=\"rtl\">כד הדר ס׳ וכ׳</span> whenever, in Palestine, a wailer comes around, they say, let all those who are of a bitter heart (mourning for a relative) weep with him (engage him for wailing). <span class=\"citation\">Ib. 25ᵇ</span> <span dir=\"rtl\">פתח עליה ההוא ס׳</span> the wailer on the occasion began thus; <span class=\"citation\">Ḥag. 15ᵇ</span>; a. fr.—Pl. <span dir=\"rtl\">סַפְדָּנַיָּא</span>, <span dir=\"rtl\">סַפְדָּנֵי</span>. <span class=\"citation\">Taan. 5ᵇ</span> וכי בכדי בכו בכייא וספדו ס׳ וכ׳ Ms. M., was it for nought that the weepers wept, and the wailers wailed &amp;c.? <span class=\"citation\">Yeb. 121ᵇ</span> <span dir=\"rtl\">כן וכן ס׳ הוו התם</span> such and such wailers officiated there.</div>","alt":[]},"19809":{"h":"סִפָּה","r":"O01321","html":"<p class=\"morphology\">f.</p><div class=\"sense\">, pl. <span dir=\"rtl\">סִפּוֹת</span>(b. h.; v. <a href=\"#\" data-headword=\"סַף\">סַף</a>) <i>bowls</i>, <i>moulds</i> of glassware. <span class=\"citation\">Tosef. Kel. B. Bath. VII, 7</span> <span dir=\"rtl\">משינטלו מן הס׳ שלהן</span> as soon as they are taken out of their moulds.</div>","alt":[]},"19810":{"h":"סִפּוּג","r":"O01322","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"סִיפּוּג\">סִיפּוּג</a></div>","alt":[]},"19811":{"h":"סְפוֹג","r":"O01323","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<span dir=\"rtl\">ספג</span>, cmp. <span dir=\"rtl\">ספח</span>) <i>a porous luxuriant growth, mushroom; sponge, any sponge-like material; wiper</i>. <span class=\"citation\">Y. Sabb. VII, 10ᵃ</span> (in Chald. dict.) <span dir=\"rtl\">ההן דגזז ס׳ וכ׳</span> he who cuts mushrooms etc. (on the Sabbath) is guilty of the acts of harvesting and of planting (the cutting being the means of advancing the growth). <span class=\"citation\">B. Kam. 115ᵇ</span>; <span class=\"citation\">Succ. 50ᵃ</span>; <span class=\"citation\">Yalk. Mal. 587</span> <span dir=\"rtl\">ארס … דומה לס׳ וכ׳</span> the venom of the serpent (on top of liquids) resembles a fungus (Ar.: a veil-like growth on the head of a certain sea-fish) and remains floating &amp;c.; (Y. Ter. VII, 45ᵈ bot. <span dir=\"rtl\">עומד כסבכה</span>, v. <a href=\"#\" data-headword=\"סְבָכָה\">סְבָכָה</a>). <span class=\"citation\">Kel. IX, 4</span> <span dir=\"rtl\">ס׳ שבלע וכ׳</span> a mushroom which has absorbed unclean liquids, though it is dry on the outside etc. <span class=\"citation\">Sabb. XXI, 3</span> <span dir=\"rtl\">ס׳ אם יש לו עור וכ׳</span> a sponge (used for sucking up liquids), if it has leather handles etc. <span class=\"citation\">Tosef. ib. V</span> (<span class=\"citation\">VI), 3</span> <span dir=\"rtl\">ס׳ שע׳&#x27;ג המכה</span> an absorbent substance (wool) put on a wound. Y. ib. XVII, 15ᶜ top <span dir=\"rtl\">ונתן עליה ס׳ יבש</span> and he put on it a dry sucker (compress); <span class=\"citation\">Lev. R. s. 15</span>; <span class=\"citation\">Lam. R. to IV, 20</span>; a. fr.—<span class=\"citation\">Ab. V, 15</span> <span dir=\"rtl\">ס׳ שהוא סופג וכ׳</span> (a scholar indiscriminately cramming his mind is called) a sponge, because he absorbs every thing.—Pl. <span dir=\"rtl\">סְפוֹגִים</span>, <span dir=\"rtl\">סְפוֹגִין</span>. <span class=\"citation\">Y. Yeb. XVI, 15ᵈ</span> top <span dir=\"rtl\">רצו לחתוך ס׳</span> (divers) wanted to cut sponges. <span class=\"citation\">Sabb. 129ᵇ</span> <span dir=\"rtl\">ס׳ של צמר</span> tufts of wool; (Tosef. ib. XV (XVI), 3 <a href=\"#\" data-headword=\"כְּסוּת\">כסות</a>). <span class=\"citation\">Ab. Zar. 18ᵃ</span> <span dir=\"rtl\">הביאו ס׳ של צמד וכ׳</span> they took tufts of wool, soaked them with water, and put them onhis heart; a. e.—[Σπόγγος, σφόγγος seems to be of Semitic origin.]</div>","alt":[]},"19812":{"h":"סְפוֹגָא","r":"O01324","html":"<div class=\"sense\">(<a href=\"#\" data-headword=\"סְפוֹג\">preced.</a>) <i>a spongy cake.</i>—Pl. <span dir=\"rtl\">סְפוֹגִין</span>. <span class=\"citation\">Targ. Y. Lev. II, 4</span> (ed. Vien. <span dir=\"rtl\">ספוּ׳</span>); v. <a href=\"#\" data-headword=\"אִסְפּוֹג\">אִסְפּוֹג</a>.</div>","alt":[]},"19813":{"h":"סְפוֹגָנִית","r":"O01325","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"סְפוֹגָא\">preced.</a>) <i>sponge-like.</i> <span class=\"citation\">Ukts. II, 8</span> <span dir=\"rtl\">פת ס׳</span> spongy bread.</div>","alt":[]},"19814":{"h":"סִפְוָוא","r":"O01326","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"סִיפְוָוא\">סִיפְוָוא</a></div>","alt":["סִפְּ׳"]},"19815":{"h":"סִפְוָון","r":"O01327","html":"<div class=\"sense\"> v. <a href=\"#\" data-headword=\"סִיפְתָא\">סִיפְתָא</a></div>","alt":["סִפְוָותָא"]},"19816":{"h":"סָפוֹן","r":"O01328","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>soap</i>, v. <a href=\"#\" data-headword=\"צָפוֹן I\"><span dir=\"rtl\">צָפוֹן</span> I</a>.</div>","alt":[]},"19817":{"h":"סַפּוֹנָא","r":"O01329","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"סַפָּנָא\">סַפָּנָא</a></div>","alt":[]},"19818":{"h":"ספונאות","r":"O01330","html":"<div class=\"sense\">, <span class=\"citation\">Tosef. Kel. B. Kam. VI, 17</span>, v. <a href=\"#\" data-headword=\"סְפָי\">סְפָי</a> a. <a href=\"#\" data-headword=\"אִסְטַגְיוֹת\"><a href=\"#\" data-headword=\"אִסְטַגְיוֹת\">אִסְטַגְיוֹת</a>.</a></div>","alt":[]},"19819":{"h":"סִפּוֹנְיָא","r":"O01331","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"סִימְפּוֹנְיָא\">סִימְפּוֹנְיָא</a></div>","alt":[]},"19820":{"h":"סִפְוָנִיּוֹת","r":"O01332","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"סִיפְוָונִיּוֹת\">סִיפְוָונִיּוֹת</a></div>","alt":[]},"19821":{"h":"ספוסטא","r":"O01333","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"סְבַסְטִי\">סְבַסְטִי</a></div>","alt":[]},"19822":{"h":"סִפּוּק","r":"O01334","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"סִפְלָא\">סִיפּ׳</a></div>","alt":["סִפּוּקָא"]},"19823":{"h":"ספוקה","r":"O01335","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"סְפֵיקָה I\"><span dir=\"rtl\">סְפֵיקָה</span> I</a></div>","alt":[]},"19824":{"h":"סְפוֹקְלָטוֹרָא","r":"O01336","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אִיסְפַּקְלָטוֹרָא\">אֵיסְפַּקְלָטוֹרָא</a></div>","alt":["סְפוֹקְלְטָרָא"]},"19825":{"h":"סִפּוּר","r":"O01337","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"סִיפּוּר\">סִיפּוּר</a></div>","alt":[]},"19826":{"h":"סָפוּר","r":"O01338","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> <a href=\"#\" data-headword=\"סָפַר\">(סָפַר</a>), pl. <span dir=\"rtl\">סְפוּרִים</span>, <span dir=\"rtl\">סְפוּרִין</span> <i>the days which have to be counted</i> (<span class=\"citation\">Lev. XV, 28</span>), <i>legal calculation</i>. <span class=\"citation\">Nidd. 30ᵃ</span> <span dir=\"rtl\">שלימו לה ס׳ דידה</span> her account is completed. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">בעינן ס׳ בפנינו</span> we (the judges) require the count before us, i.e. we count from the first day of her appearance before the ritual court; <span class=\"citation\">ib. 69ᵃ</span></div>","alt":[]},"19827":{"h":"סַפּוּרָא","r":"O01339","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (סְפַר <i>Pa</i>.) <i>hair-cutting;</i> מאני ס׳ <i>barber’s tools</i>. <span class=\"citation\">Lev. R. s. 28</span>, end <span dir=\"rtl\">אפיק מאני סַפּוּרֵיה</span> he took out his barber tools; <span class=\"citation\">ib.</span> <span dir=\"rtl\">ואילין אונון מאניא ספוריה</span> (read: <span dir=\"rtl\">מאני</span>) and these are his (thy father’s) tools; <span class=\"citation\">Yalk. Esth. 1058</span> <span dir=\"rtl\">ואילין אינון סַפָּרַיָּא דידך</span> and these are thy scissors; <span class=\"citation\">Esth. R. to VI, 10</span> <span dir=\"rtl\">ואשכחת מאני סַפָּרָא דידיה</span> and thou shalt find his tools.</div>","alt":[]},"19828":{"h":"סְפוֹרָה","r":"O01340","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><i>number</i>.—Pl. <span dir=\"rtl\">סְפוֹרוֹת</span>. <span class=\"citation\">Y. Shek. V, beg. 48ᶜ</span> (ref. to <span class=\"citation\">I Chr. II, 55</span> they are named Sof’rim, <span dir=\"rtl\">שעשו את התורה ס׳ ס׳</span> because they arranged the Law by numbers (as in <span class=\"citation\">Ter. I, 1</span>; <span class=\"citation\">Sabb. VII, 2</span> etc.); Yalk. Chr. 1074 <a href=\"#\" data-headword=\"סְפִירוּת\">סְפִירוֹת</a>.</div>","alt":[]},"19829":{"h":"סִפּוּרַיָּיא","r":"O01341","html":"<p class=\"morphology\">pr. n. pl.</p><div class=\"sense\"><i>K’far Sippuraya</i> (Es-Safiriye), near Lydda (Neub. Géogr. p. 81). <span class=\"citation\">Y. Kidd. III, 64ᵈ</span> bot. [read:] <span dir=\"rtl\">הורי בכ׳ ס׳</span>.</div>","alt":["כְּפַר ס׳"]},"19830":{"h":"סָפַח","r":"O01342","html":"<div class=\"sense\"> (b. h.) <i>to grow, swell, be added to</i>.</div><div class=\"sense\"><b>Pi. סִפֵּחַ</b> <div class=\"sense\"><b>1)</b> <i>to add</i>, esp. (of a river) <i>to cast out alluvial soil, make new land</i> <span class=\"citation\">Gen. R. s. 13</span> <span dir=\"rtl\">על הנהר שמְסַפֵּחַ למדינה וכ׳</span> when a river ameliorates the soil of a district, we say the blessing etc.; Y. Ber. IX, 14ᵃ <span dir=\"rtl\">מספיק</span> (corr. acc.). (corr. acc.).</div><div class=\"sense\"><b>—2)</b> <i>to join, conspire</i>. Tanḥ. Thazr. 11 (play on <a href=\"#\" data-headword=\"סַפַּחַת\">ספחת</a>, <span class=\"citation\">Lev. XIII, 2</span>) <span dir=\"rtl\">שהיה המן מספח עם וכ׳</span> Haman conspired with Ahasver to destroy etc.</div><div class=\"sense\"><b>—3)</b>  (v. <a href=\"#\" data-headword=\"סַפַּחַת\">סַפַּחַת</a>) <i>to smite with sores</i>. Pesik. Vattom., p. 133ᵃ (ref. to <span dir=\"rtl\">ושׂפח</span>, <span class=\"citation\">Is. III, 17</span>) <span dir=\"rtl\">ואין ספח אלא צרעת</span> <i>sippaḥ</i> means striking with leprosy; Tanḥ. l. c. <span dir=\"rtl\">אין ושִׂפַּח וכ׳</span>; <span class=\"citation\">Lev. R. s. 16</span> <span dir=\"rtl\">הלקן בצרעת</span>.</div></div><div class=\"sense\"><b>Nithpa. נִסְתַּפֵּחַ</b> <div class=\"sense\"><i>to attach one’s self, become a citizen</i>. <span class=\"citation\">Ruth R. to I, 1</span> end <span dir=\"rtl\">שהניחו ישראל ונִסְתַּפְּחוּ וכ׳</span> they left Israel and became citizens in the fields of Moab.</div></div>","alt":[]},"19831":{"h":"סֶפַח","r":"O01343","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"סָפִיחַ\">סָפִיחַ</a></div>","alt":[]},"19832":{"h":"ספחית","r":"O01344","html":"<div class=\"sense\">, <span class=\"citation\">Y. Shek. IV, 48ᵃ</span> top, v. <a href=\"#\" data-headword=\"סָפִיחַ\">סָפִיחַ</a></div>","alt":[]},"19833":{"h":"סַפַּחַת","r":"O01345","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><i>rising on the skin, sore</i>. Sifra Thazr., <span class=\"citation\">Neg., ch. I</span> (ref. to <span class=\"citation\">Lev. XIII, 2</span>) <span dir=\"rtl\">ס׳ שני לשאת</span> (not <span dir=\"rtl\">לבהרת</span>) <i>sappaḥath</i> is secondary to (is a species of) <i>s’eth</i>. Ib.; <span class=\"citation\">Shebu. 6ᵇ</span> <span dir=\"rtl\">אין ס׳ אלא טפילה</span> the word <i>sappaḥath</i> itself intimates an attachment to something (ref. to <span class=\"citation\">I Sam. II, 36</span>). <span class=\"citation\">Yeb. 47ᵇ</span>; <span class=\"citation\">109ᵇ</span>, a. e. <span dir=\"rtl\">קשים גרים לישראל כס׳ בעור</span> proselytes are as bad to Israel as a sore on the skin (ref. to <span dir=\"rtl\">ונספחו</span>, <span class=\"citation\">Is. XIV, 1</span>).</div>","alt":[]},"19834":{"h":"סִפְטָא","r":"O01346","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"סִיפְטָא\">סִיפְטָא</a></div>","alt":[]},"19835":{"h":"*סְפַטְנִי","r":"O01347","html":"<p class=\"morphology\">f. pl.</p><div class=\"sense\"> (spatulæ) <i>small and broad swords</i>. <span class=\"citation\">Tosef. Kel. B. Mets. V, 6</span> (ed. Zolk. <span dir=\"rtl\">סוֹפִינֵי</span>).</div>","alt":[]},"19836":{"h":"ספי","r":"O01348","html":"<div class=\"sense\"><b>1)</b> <i>to cut</i>, esp. <i>to cut a slice, to give a portion; to have a share in a meal</i>. <span class=\"citation\">Pes. 3ᵇ</span> <span dir=\"rtl\">סְפוּ לי מאליה</span> give me a piece of the fat-tail. <span class=\"citation\">Midr. Till. to Ps. IV, 7</span> ed. Bub. <span dir=\"rtl\"><span dir=\"rtl\">מי יתן</span> (<span dir=\"rtl\">לנו</span>) <span dir=\"rtl\">לִסְפּוֹת עמכם וכ׳</span></span> (differ. in ed., v. ed. Bub. note) oh, that we could share with you in the good of the hereafter; <span class=\"citation\">Yalk. ib. 627</span> <span dir=\"rtl\">לספור</span> (corr. acc.).</div><div class=\"sense\"><b>—2)</b> <i>to consume, destroy</i>. Tanḥ. Vayera 8 (ref. to <span class=\"citation\">Gen. XVIII, 23</span>) <span dir=\"rtl\">בשר ודם האף סוֹפֶה אותו וכ׳</span> as regards a human being, anger consumes him (carries him away), is it so with thee? Wilt thou consume the righteous with the wicked?</div><div class=\"sense\"><b>Nif. נִסְפֶּה</b> <div class=\"sense\"><i>to be destroyed, ruined</i>. <span class=\"citation\">Gen. R. s. 49</span> (ref. to <span class=\"citation\">Prov. XIII, 23</span>) <span dir=\"rtl\">ונמצא נ׳ בלא משפט מקומו</span> and thus he was ruined (by the tax-gatherers) not in accordance with the judgment of his place (which had been released from the tax in the meanwhile).</div></div>","alt":["סָפָה"]},"19837":{"h":"סְפֵי","r":"O01349","html":"<div class=\"sense\"><b>1)</b> <i>to cut, apportion, give to eat</i>. <span class=\"citation\">Targ. Y. Num. XI, 18</span> (ed. Vien. <span dir=\"rtl\">יַסְפִּי׳</span> <i>Af.</i>).—<span class=\"citation\">Pes. 3ᵇ</span> <span dir=\"rtl\">מי קא סָפוּ לך מאליה</span> have they given you a piece &amp;c.? v. <a href=\"#\" data-headword=\"ספי\">preced.</a> <span class=\"citation\">Ḥull. 107ᵇ</span> לא סְפִינָא לך I should not have given thee to eat. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">קא סָפִית לבראי וכ׳</span> thou didst feed my son, and didst not wash thy hands (v. <a href=\"#\" data-headword=\"מְשֵׁי\">מְשֵׁי</a>). <span class=\"citation\">Ib. 95ᵇ</span> <span dir=\"rtl\">איכו השתא סְפִיתוּ וכ׳</span> how near you came giving the sons of B. forbidden food to eat. <span class=\"citation\">Ib.ᵃ</span> top <span dir=\"rtl\">מי לא סַפְיִי לך וכ׳</span> (Ar. <span dir=\"rtl\">סְפָאִי</span>) should I not have given thee a portion of the fat ox? Ib. <span dir=\"rtl\">דזבן … וס׳ לי</span> such and such a gentile bought of it, and he gave me of it. <span class=\"citation\">B. Bath. 21ᵃ</span> עד שית … קביל וסְפִי ליה וכ׳ Ar. (ed. <a href=\"#\" data-headword=\"אַסְפִּי\">אַסְפִּי</a> <i>Af.</i>) until six years of age take no pupils, from six and upward take (the child) and feed him (with knowledge) as you feed an ox; a. fr.</div><div class=\"sense\"><b>—2)</b> <i>to scrape together, collect</i>. <span class=\"citation\">Targ. O. Ex. XXVII, 3</span>.—<span class=\"citation\">Cant. R. to I, 6</span> <span dir=\"rtl\">ס׳ חלא וכ׳</span> he grabbed up sand and put it in his mouth. <span class=\"citation\">B. Mets. 114ᵇ</span> <span dir=\"rtl\">סְפִי שקול וכ׳</span> grab and take of these leaves (of Eden); <span dir=\"rtl\">ספא שקל</span> he grabbed and carried them off.</div><div class=\"sense\"><b>Af. אַסְפֵּי</b> <div class=\"sense\"> <a href=\"#\" data-headword=\"ספי\">same</a>, <i>to give to eat</i>. <span class=\"citation\">Targ. Y. Num. XI, 18</span>, v. supra.—<span class=\"citation\">B. Bath. 21ᵃ</span>, v. supra.—[<span class=\"citation\">Lam. R. to I, 7</span> <span dir=\"rtl\">כד תספון כלה וכ׳</span>, a corruption, prob. to be read: <span dir=\"rtl\">כד מַסְפִּין כלה</span> ‘when they give a bride to eat’, some words like ‘coarse food’ being omitted.]</div></div><div class=\"sense\"><b>Ithpa. אִסְתְּפֵי</b> <div class=\"sense\"> [<i>to be withdrawn</i>, cmp. <i>Nif.</i> of <a href=\"#\" data-headword=\"אָסַף\">אָסַף</a> <span class=\"citation\">II Sam. XVII, 13</span>; <span class=\"citation\">Jer. IV, 5</span>, a. e.,] <i>to shrink, be afraid</i>. <span class=\"citation\">Targ. Job XXXII, 6</span> <span dir=\"rtl\">אִסְתְּפֵיתִי</span> (h. text <span dir=\"rtl\">זחלתי</span>). <span class=\"citation\">Targ. Y. Gen. XXI, 17</span> <span dir=\"rtl\">תִּסְתְּפִין</span> (not <span dir=\"rtl\">תַּסְתִּיפִין</span>). <span class=\"citation\">Ib. XLII, 4</span>; a. fr.—<span class=\"citation\">Ber. 20ᵃ</span> <span dir=\"rtl\">לא קא מִסְתְּפֵי מר מיה&quot;ר</span> are you not afraid of temptation? <span class=\"citation\">Ib. 62ᵃ</span> <span dir=\"rtl\">לא מִסְתְּפִיתוּ</span> are ye not afraid? <span class=\"citation\">Snh. 94ᵇ</span> bot. <span dir=\"rtl\">מהאי לא תִסְתְּפִי אלא אִיסְתְּפִי וכ׳</span> be not afraid of this one, but be afraid of &amp;c.; a. fr.</div></div>","alt":["סְפָא"]},"19838":{"h":"ספי ²","r":"O01350","html":"<div class=\"sense\">, <span class=\"citation\">Yalk. Gen. 133</span> <span dir=\"rtl\">ס׳ קולא</span>, read: <a href=\"#\" data-headword=\"סְפִיקוּלָא I\">סְפִיקוּלָא</a>.</div>","alt":[]},"19839":{"h":"סְפָי","r":"O01351","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"ספי\">סָפָה</a> = b. h. <a href=\"#\" data-headword=\"שָׂפָה\">שָׂפָה</a>) <i>rim</i>.—Pl. <a href=\"#\" data-headword=\"סְפָאוֹת\">סְפָיוֹת</a>, <a href=\"#\" data-headword=\"סְפָאוֹת\">סְפָאוֹת</a>. Y. Ab. Zar. II, end, 42ᵃ; <span class=\"citation\">Tosef. Kel. B. Kam. VI, 17</span> (not <span dir=\"rtl\">ספונאו׳</span>), v. <a href=\"#\" data-headword=\"אִסְטַגְיוֹת\">אִסְטַגְיוֹת</a>; <span class=\"citation\">Kel. VIII, 9</span> <a href=\"#\" data-headword=\"שִׁפְיוּת\">שְׂפָיוֹת</a>. <span class=\"citation\">Ib. IV, 4</span> ספיות Ar. ed. Koh. (oth. ed. Ar. <a href=\"#\" data-headword=\"סְפָאוֹת\">סְפָאוֹת</a>, <a href=\"#\" data-headword=\"סְפָאוֹת\">סְפָאיוֹת</a>; ed. <a href=\"#\" data-headword=\"שִׁפְיוּת\">שׂפָיוֹת</a>).—<a href=\"#\" data-headword=\"סְפָיִין\">סְפָיִין</a>, <span class=\"citation\">Y. Sabb. VII, 10ᵈ</span> top, v. <a href=\"#\" data-headword=\"סִפָּא\">סִפָּא</a>.</div>","alt":[]},"19840":{"h":"סַפְיָא","r":"O01352","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מִסְפְּיָיא\">מִסְפְּיָיא</a></div>","alt":[]},"19841":{"h":"סְפִידָא","r":"O01353","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"סִיפְדָּא\">סִיפְדָּא</a></div>","alt":["סַפִּידָא"]},"19842":{"h":"סָפִיחַ","r":"O01354","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>spontaneous growth, after-growth</i>.—Pl. <span dir=\"rtl\">סְפִיחִים</span>, <span dir=\"rtl\">סְפִיחִין</span>, <a href=\"#\" data-headword=\"סִיפּוּק\">(סְפָ׳</a>). <span class=\"citation\">Shebi. IX, 1</span> <span dir=\"rtl\">כל הס׳ מותרין חוץ מסְפִיחֵי כרוב</span> (Y. ed. <span dir=\"rtl\">הספחים … סִפְחֵי</span>) all spontaneous growths (of the Sabbatical year, dating from the sixth year) are permitted, except the after-growth of cabbage; <span class=\"citation\">Pes. 51ᵇ</span> <span dir=\"rtl\">כל הס׳ אסורין וכ׳</span> (v. comment.). Sifra B’har, Par. 1, ch. I (ref. to <span class=\"citation\">Lev. XXV, 5</span>) <span dir=\"rtl\">מכאן סמכו … הס׳ וכ׳</span> from here the scholars found a support for the prohibition of the after-growth. <span class=\"citation\">Shek. IV, 1</span> <span dir=\"rtl\">שומרי ס׳ בשביעית וכ׳</span> those appointed to watch the after-growth (of barley for the ‘Omer) in the Sabbatical year receive their wages &amp;c. Y. ib. 48ᵃ top <a href=\"#\" data-headword=\"ספחית\">ספחית</a> (corr. acc.); a. fr.</div>","alt":["(סֶפַח)"]},"19843":{"h":"ספיטוס","r":"O01355","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"סוֹפִיסְטָא\">סוֹפִיסְטָא</a></div>","alt":["ספיטס"]},"19844":{"h":"סַפְיָיא","r":"O01356","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"מִסְפְּיָיא\">מִספְּיָיא</a></div>","alt":[]},"19845":{"h":"סְפָיִין","r":"O01357","html":"<div class=\"sense\">, <span class=\"citation\">Y. Sabb. VII, 10ᵈ</span> top, v. <a href=\"#\" data-headword=\"סִפָּא\">סִפָּא</a></div>","alt":[]},"19846":{"h":"ספימטא","r":"O01358","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"סְבַסְטִי\">סבַסְטִי</a></div>","alt":[]},"19847":{"h":"סְפִינָא","r":"O01359","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"סְפִינְתָּא\">סְפִינְתָּא</a></div>","alt":[]},"19848":{"h":"סְפִינָה","r":"O01360","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><b>2)</b>  [<i>storage</i>,] <i>freight-ship</i>. <span class=\"citation\">Taan. III, 7</span>, v. <a href=\"#\" data-headword=\"טָרַף\">טָרַף</a>. <span class=\"citation\">B. Bath. 91ᵇ</span> top (on the death of Abraham) <span dir=\"rtl\">אוי לה לס׳ וכ׳</span> woe to the ship whose captain is gone; a. fr.—Pl. <span dir=\"rtl\">סְפִינוֹת</span>. <span class=\"citation\">Ex. R. s. 17</span>, end <span dir=\"rtl\">ס׳ של פירטין</span> pirate ships; a. e.</div>","alt":[]},"19849":{"h":"סְפִינְתָּא","r":"O01361","html":"<div class=\"sense\"> <span class=\"citation\">Targ. I Kings IX, 26</span>, sq. <span dir=\"rtl\">ספינא</span> Bxt. (ed. <a href=\"#\" data-headword=\"סְפִינְתָּא\">סְפִינְתָּא</a> collect. noun; ed. Wil. <a href=\"#\" data-headword=\"סְפִינְתָּא\">סְפִינָתָא</a>, <i>pl.</i>). <span class=\"citation\">Ib. X, 22</span>.—<span class=\"citation\">Taan. 21ᵃ</span> <span dir=\"rtl\">אסקריא דס׳</span>, v. <a href=\"#\" data-headword=\"אִסְקַרְיָא\">אִסְקַרְיָא</a>. <span class=\"citation\">Ned. 50ᵃ</span>, v. <a href=\"#\" data-headword=\"אֵילָא\">אֵילָא</a>; a. e.—<i>Pl.</i> <a href=\"#\" data-headword=\"סְפִינָא\">סְפִינָן</a>, <a href=\"#\" data-headword=\"סְפִינְתָּא\">סְפִינָתָא</a>, constr. <a href=\"#\" data-headword=\"סְפִינָא\">סְפִינַת</a>, <span dir=\"rtl\">סְפִינֵי</span>. <span class=\"citation\">Targ. O. Deut. XXVIII, 68</span>. <span class=\"citation\">Targ. I Kings XXII, 49</span>. <span class=\"citation\">Targ. Is. XXIII, 1</span>; a. fr.</div>","alt":["סְפִינָא"]},"19850":{"h":"סְפֵיק","r":"O01362","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"סְפַק\">סְפַק</a>. [Pesik. B’shall., p. 89ᵃ, <span dir=\"rtl\">ס׳ להו</span>, read: <a href=\"#\" data-headword=\"סְפִיקוּלָא I\">סְפִיקוּלָא</a>.]</div>","alt":[]},"19851":{"h":"סְפֵיק־","r":"O01363","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"סָפֵק\">סָפֵק</a></div>","alt":[]},"19852":{"h":"סְפֵיקָא","r":"O01364","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"סְפֵקָא\">סְפֵקָא</a>, a. <a href=\"#\" data-headword=\"סְפֵיקָה I\">סְפֵיקָה</a>.</div>","alt":[]},"19853":{"h":"סַפִּיקָא","r":"O01365","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"סְפַק\">סְפַק</a>) <i>sufficiency, opportunity, possibility</i>. <span class=\"citation\">Targ. Y. Gen. XXXI, 29</span>.—V. <a href=\"#\" data-headword=\"סְפֵיקָה I\">next w.</a></div>","alt":[]},"19854":{"h":"סְפֵיקָה I","r":"O01366","html":"<div class=\"sense\"> f. h. <a href=\"#\" data-headword=\"סַפִּיקָא\">same</a> (frequ. Chald. form <a href=\"#\" data-headword=\"סַפִּיקָא\">סַפִּיקָא</a> (v. <a href=\"#\" data-headword=\"סַפִּיקָא\">preced.</a>) or <a href=\"#\" data-headword=\"סְפֵיקָא\">סְפֵיקָא</a>). <span class=\"citation\">Y. Peah I, 15ᶜ</span> sq. <span dir=\"rtl\">האיש ס׳ בידו וכ׳</span> the man has the power (possesses the means, to honor his parents) but the married woman not; <span class=\"citation\">Y. Kidd. I, 61ᵃ</span> bot.; Bab. <span class=\"citation\">Kidd. 30ᵇ</span> <a href=\"#\" data-headword=\"סֵיפֶק\">סֵיפֶק</a>; <span class=\"citation\">ib. 35ᵃ</span>; <span class=\"citation\">Tosef. ib. I, 11</span> <a href=\"#\" data-headword=\"סֵפֶק\">סֵפֶק</a>. <span class=\"citation\">Yalk. Ex. 259</span> אין ספיקא בידי וכ׳ I am unable to give it to you; Mekh. B’shall., Vayass‘a, s. 3 <a href=\"#\" data-headword=\"סָפַק I\">ספק</a>. <span class=\"citation\">Koh. R. to I, 15</span> <span dir=\"rtl\">שהיתה ספיקא בידך וכ׳</span> thou didst have an opportunity to repent. <span class=\"citation\">Midr. Till. to Ps. LXXXVI, 1</span> <span dir=\"rtl\">וספוקה בידו וכ׳</span> ed. Bub. (corr. acc.; oth ed. <span dir=\"rtl\">וספק</span>) while he has the power to prevent it. <span class=\"citation\">Ker. 5ᵃ</span> <span dir=\"rtl\">אינו סיפק</span>, v. <a href=\"#\" data-headword=\"עִיקָּר\">עִיקָּר</a>; a. fr.</div>","alt":[]},"19855":{"h":"סְפֵיקָה II","r":"O01367","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><i>doubt;</i> pl. <span dir=\"rtl\">סְפֵיקוֹת</span>, v. <a href=\"#\" data-headword=\"סָפֵק\">סָפֵק</a>.</div>","alt":[]},"19856":{"h":"סְפִיקוּלָא I","r":"O01368","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (spiculum) <i>dart</i>, <i>javelin;</i> <span dir=\"rtl\">נתן ס׳</span> [<i>to put up the javelin</i>,] <i>to call for judgment; to sentence</i> (v. Sm. Ant. a. Luebker Reallex. s. v. Hasta), opp. <a href=\"#\" data-headword=\"דִּימוֹס II\"><span dir=\"rtl\">דִּימוֹס</span> II</a>. <span class=\"citation\">Y. Ber. IX, 14ᵇ</span> <span dir=\"rtl\">וכשהוא נותן ס׳ הכל וכ׳</span> but when he orders judgment, all murmur against him; <span class=\"citation\">Lev. R. s. 24</span>, beg. <a href=\"#\" data-headword=\"סְפִיקְלָא\">ספיקלא</a>.—<span class=\"citation\">Gen. R. s. 79</span> <span dir=\"rtl\">וכד … ס׳ וכ׳</span> and when he heard the divine voice say ‘judgment’, the bird was caught; <span class=\"citation\">Koh. R. to X, 8</span> <a href=\"#\" data-headword=\"סְפִיקְלָא\">ספיקלא</a> (correct the passage as in Gen. R. l. c.); a. e.—<span class=\"citation\">Ex. R. s. 15</span> prepare the swords (v. <a href=\"#\" data-headword=\"אִסְפָּתִי\">אִסְפָּתִי</a>), <span dir=\"rtl\">שאם ימרדו ישמעו אִסְפִּיקוּלָא</span> that, in case they rebel, they may hear the call for judgment (‘spicula’). <span class=\"citation\">Midr. Till. to Ps. XCII</span> <span dir=\"rtl\">ישב עליו בדין לספק לו</span>, read: <span dir=\"rtl\">ישב עליו לס׳</span> (<span dir=\"rtl\">בדין</span>, a gloss) he sat down to pronounce judgment upon him.</div>","alt":["סְפִיקוּלָה","(סְפִקוּלָ׳)"]},"19857":{"h":"סְפִיקוּלָא I ²","r":"O01369","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (specula) <i>watch-tower</i>. <span class=\"citation\">Y. Sabb. I, 3ᵇ</span> bot.</div>","alt":["סְפִיקְלָה"]},"19858":{"h":"ספיקטורין","r":"O01370","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"סְקִיפְטוֹרִין\">סְקִיפְטוֹרִין</a></div>","alt":[]},"19859":{"h":"סְפִיקְלָא","r":"O01371","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"סְפִיקוּלָא I\">סְפִיקוּלָא</a></div>","alt":["סְפִיקְלָה"]},"19860":{"h":"סְפִיקְלָטוֹר","r":"O01372","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"סְפִקְלָאטוֹר\">סְפִקְלָאטוֹר</a></div>","alt":[]},"19861":{"h":"*ספיקלוא","r":"O01373","html":"<div class=\"sense\">, Y. Ber. VIII, 13ᶜ bot. <span dir=\"rtl\">בבית ס׳</span>; Asheri to <span class=\"citation\">Ber. 59ᵃ</span> <span dir=\"rtl\">בכספוקלריא</span>, Ma‘ăd. Yomt. a. l. <span dir=\"rtl\">בבית ספוקלרי</span>, prob. to be read: <span dir=\"rtl\">בבית סְפִיקְלַרְיָא</span> (v. <a href=\"#\" data-headword=\"סְפַקְלַרְיָא\">סְפַקְלַרְיָא</a>) <i>in the mirror-room</i>, i.e. <i>toilet-room</i></div>","alt":["ספיקריא"]},"19862":{"h":"סַפִּיר","r":"O01374","html":"<div class=\"sense\">, m.(b. h.; </div><div class=\"sense\"><b>1)</b> <i>sapphire</i>. <span class=\"citation\">Ex. R. s. 38</span>, end <span dir=\"rtl\">על ס׳ היה וכ׳</span> on the sapphire (in the high priest’s breastplate) the name of Issachar was engraven. Pesik. ‘Ăniya, p. 135ᵇ <span dir=\"rtl\">נבקע … והס׳ לא חסר</span> the anvil was split, the hammer was broken in two, but the sapphire remained intact. <span class=\"citation\">Lam. R. to IV, 7</span>, v. <a href=\"#\" data-headword=\"גִּזְרָה\">גִּזְרָה</a>; a. e.—V. <a href=\"#\" data-headword=\"סַמְפִּירִינוֹן\">סַמְפִּירִינוֹן</a>.</div><div class=\"sense\"><b>—2)</b> <i>sappir</i>, name of a species of beans. <span class=\"citation\">Kil. I, 1</span>, expl. Y. ib. 27ᵃ top <a href=\"#\" data-headword=\"פושונה\">פושונה</a> (R. S. to Kil. l. c. <a href=\"#\" data-headword=\"*פַּיְישׂוֹנָא\">פַּיְישׂוּנָא</a>).</div>","alt":[]},"19863":{"h":"סְפֵיר־","r":"O01375","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"סָפֵר\">סָפֵר</a></div>","alt":[]},"19864":{"h":"סְפִירָא","r":"O01376","html":"<div class=\"sense\">, f. <i>goat’s hair</i>, v. <a href=\"#\" data-headword=\"צְפִירָא II\"><span dir=\"rtl\">צְפירָא</span> II</a>.</div>","alt":[]},"19865":{"h":"סְפֵירָא","r":"O01377","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (σφαῖρα) <i>ball</i>. <span class=\"citation\">Pesik. R. s. 3</span>; <span class=\"citation\">Num. R. s. 14</span> <span dir=\"rtl\">כהדא ס׳ וכ׳</span> like the ball with which girls play &amp;c., v. <a href=\"#\" data-headword=\"כַּדּוּר\">כַּדּוּר</a>.</div>","alt":["סְפֵירָה"]},"19866":{"h":"סְפִירָה","r":"O01378","html":"<p class=\"morphology\">f.</p><div class=\"sense\"><b>1)</b> <i>counting</i>. <span class=\"citation\">Nidd. 73ᵃ</span> <span dir=\"rtl\">ראוי לס׳</span> fit to begin with it the count (of the seven days of purification); <span class=\"citation\">ib.</span> <span dir=\"rtl\">לסְפִירַת או כי תזוב</span> for the count required in the case described <span class=\"citation\">Lev. XV, 26</span>, sq. Sifra Emor, Par. 10, ch. XII (ref. to <span class=\"citation\">Lev. XXIII, 16</span>) <span dir=\"rtl\">כל סְפִירָתָם לא וכ׳</span> all they have to count (from Passover to the Feast of Weeks) shall be no more than fifty days. Ib. <span dir=\"rtl\">ס׳ שהיא תלויה בב&quot;ד וכ׳</span> a count which depends on the court (deciding on the New Moons), to exempt the weekly Sabbath, <span dir=\"rtl\">שסְפִירָתָהּ בכל אדם</span> which everybody counts; <span class=\"citation\">Men. 65ᵇ</span>; a. fr.—Pl. <a href=\"#\" data-headword=\"סְפִירוּת\">סְפִירוֹת</a>. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">כל ס׳ שאתה סופר וכ׳</span> all the counted days together shall be no more than fifty (v. supra); a. e.—Yalk. Chr. 1075, v. <a href=\"#\" data-headword=\"סְפוֹרָה\">סְפוֹרָה</a>.</div><div class=\"sense\"><b>—2)</b> <i>writing</i>, <i>recording</i>. <span class=\"citation\">Gitt. 21ᵇ</span>; <span class=\"citation\">Succ. 24ᵇ</span> (ref. to <span dir=\"rtl\">ספר</span>, <span class=\"citation\">Deut. XXIV, 1</span>) <span dir=\"rtl\">לסְפִירַת דברים וכ׳</span> (the word <i>sefer</i> refers not to the writing material but) merely to the act of writing the words (formula of divorce). <span class=\"citation\">Yalk. Deut. 936</span>; <span class=\"citation\">Erub. 15ᵇ</span> <span dir=\"rtl\">לספִירוּת</span>.</div>","alt":[]},"19867":{"h":"סְפִירוּת","r":"O01379","html":"<div class=\"sense\"> f., v. <a href=\"#\" data-headword=\"סְפִירָה\">preced.</a></div>","alt":[]},"19868":{"h":"סַפִּירִינוֹן","r":"O01380","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"סַמְפִּירִינוֹן\">סַמְפִּירִינוֹן</a></div>","alt":[]},"19869":{"h":"סֵפֶל","r":"O01381","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (ספל <i>to scrape, cut out</i>) </div><div class=\"sense\"><b>1)</b> (b. h.; <i>bowl</i>, <i>basin</i>. <span class=\"citation\">Kidd. 31ᵃ</span> <span dir=\"rtl\">הטל להן מים בס׳ וכ׳</span> pour water into a bowl for them (to drink from) &amp;c., v. <a href=\"#\" data-headword=\"קִעְקֵעַ I\"><span dir=\"rtl\">קִעְקֵעַ</span> I</a>. <span class=\"citation\">Nidd. 27ᵃ</span>; Y. ib. III, 51ᵃ <span dir=\"rtl\">במוציא את הס׳ וכ׳</span> when he carries away the basin (with the after-birth) &amp;c. <span class=\"citation\">Cant. R. to I, 1</span>; <span class=\"citation\">Koh. R. to I, 1</span> (ref. to <a href=\"#\" data-headword=\"יָקֶה\">יקה</a>, <span class=\"citation\">Prov. XXX, 1</span>) <span dir=\"rtl\">כס׳ הזה שנתמלא בשעתו וכ׳</span> like a bowl which is filled in due time and emptied in due time, so did &amp;c.; <span class=\"citation\">Num. R. s. 10</span>; a. e.—Pl. <span dir=\"rtl\">סְפָלִים</span>, <a href=\"#\" data-headword=\"סְפָיִין\">סְפָלִין</a>. <span class=\"citation\">Sabb. 129ᵇ</span> the rich keep the after-birth <span dir=\"rtl\">בס׳ של שמן</span> in basins filled with oil; <span class=\"citation\">Tosef. ib. XV</span> (<span class=\"citation\">XVI), 3</span> <span dir=\"rtl\">בסופלי</span> (corr. acc.). <span class=\"citation\">Ber. 44ᵃ</span> <span dir=\"rtl\">סִפְלֵי טרית</span> basinfuls of salted fish. <span class=\"citation\">Zeb. 91ᵇ</span> <span dir=\"rtl\">לס׳</span> for the bowls (for <i>libations</i>); a. e.</div><div class=\"sense\"><b>—2)</b> <i>a frame stool</i> or <i>bench;</i> also <i>night-stool</i>, interch. with <a href=\"#\" data-headword=\"סַפְסָל\">סַפְסָל</a>. <span class=\"citation\">Midr. Till. to Ps. LXXVIII, 45</span> <span dir=\"rtl\">היה … יושב על הס׳ וכ׳</span> (ed. Bub. <a href=\"#\" data-headword=\"סַפְסָל\">ספסל</a>) the Philistine (to save himself from the attack of the mice) seated himself on a stool of bronze; <span dir=\"rtl\">והיה הס׳ נבקע וכ׳</span> and the stool burst of itself, and the mouse came up &amp;c.; Midr. Sam. ch. X; <span class=\"citation\">Yalk. Sam. 102</span>; <span class=\"citation\">Yalk. Kings 222</span> <a href=\"#\" data-headword=\"סַפְסָל\">ספסל</a>; <span class=\"citation\">Yalk. Ex. 183</span> <a href=\"#\" data-headword=\"סַפְסָל\">ספסל</a>; a. e.—<i>Pl.</i> as ab. <span class=\"citation\">Tosef. Ab. Zar. VI</span> (<span class=\"citation\">VII), 3</span> <span dir=\"rtl\">הס׳ והקתידראות</span> ed. Zuck. (Var. <span dir=\"rtl\">הסַפְסָלִין</span>) stools and chairs. Midr. Sam. l. c.; Yalk. Sam. l. c.; a. e.</div>","alt":[]},"19870":{"h":"סִפְלָא","r":"O01382","html":"<div class=\"sense\">, <i>bowl</i>.—Pl. <span dir=\"rtl\">סִפְלֵי</span>, <a href=\"#\" data-headword=\"סִבְכָא\">סִי׳</a>. <span class=\"citation\">Targ. Y. Num. XV, 7</span>.—[<span class=\"citation\">Targ. Y. Ex. XXIV, 6</span> ספלים Ar.; ed. <span dir=\"rtl\">מזרקיא</span>; h. text <span dir=\"rtl\">אגנות</span>).</div>","alt":["סִיפְ׳"]},"19871":{"h":"סִפְלָנִי","r":"O01383","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"סִיפְלָנִי\">סִיפְלָנִי</a></div>","alt":[]},"19872":{"h":"סְפָם","r":"O01384","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"שָׂפָם\">שְׂפָם</a></div>","alt":["סְפָמָא"]},"19873":{"h":"סְפַמְיָא","r":"O01385","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אִסְפַּמְיָא\">אִסְפַּמְיָא</a></div>","alt":[]},"19874":{"h":"סָפַן","r":"O01386","html":"<div class=\"sense\"> (cmp. <a href=\"#\" data-headword=\"צָפַן\">צָפַן</a>, <a href=\"#\" data-headword=\"צָפָה\">צָפָה</a>) [<i>to look up to, look out for</i>,] </div><div class=\"sense\"><b>1)</b> <i>to respect; to care for, mind</i> Y. Snh. X, beg. 27ᶜ <span dir=\"rtl\">זהו שאומר ואיני סוֹפְנָהּ …</span> that is he who says, there is a Torah, but I do not mind its authority; Y. Peah I, 16ᵇ <span dir=\"rtl\">סובלה</span> (corr. acc.). <span class=\"citation\">Tosef. Sot. III, 14</span> <span dir=\"rtl\">ולא סְפָנוּהוּ וכ׳</span> (Var. <span dir=\"rtl\">סנפוהו</span>, corr. acc.) they minded him not, because he was merely a common soldier <a href=\"#\" data-headword=\"גּוּלְיָיר\">(גּוֹלְיָיר</a>). <span class=\"citation\">Sifré Deut. 33</span> (ref. to <span dir=\"rtl\">היום</span>, <span class=\"citation\">Deut. VI, 6</span>) <span dir=\"rtl\">שלא יהו … שאין אדם סופנה</span> Rashi ed. Berl. a. l. (ed. <span dir=\"rtl\">סופרה</span>, corr. acc.; Ms. 3 <span dir=\"rtl\">צוֹפְנָהּ</span>, v. ed. Fr. note) that they be not in thy eyes like an antiquated ordinance which nobody minds; <span class=\"citation\">Yalk. Deut. 840</span> <span dir=\"rtl\">שאין הכל סוֹפְנִין אותה</span> (not <span dir=\"rtl\">סופגין</span>). <span class=\"citation\">Tosef. Keth. VII, 5</span> <span dir=\"rtl\">תהא מוטלת ואין כל בריה סופנה</span> (not <span dir=\"rtl\">בריא</span>) she will lie dead and none will care for her (to bury her); <span class=\"citation\">Keth. 72ᵃ</span> <span dir=\"rtl\">ואון … סופדה … סופנה</span> (R. Hillel quoted in Sifré l. c., ed. Fr. note <span dir=\"rtl\">צופנה</span>) and none will mourn for her, and some say <i>sof’nah</i>; (Y. ib. VII, 31ᵇ bot. <span dir=\"rtl\">משגחת</span>).—Part. pass. <a href=\"#\" data-headword=\"סָפוֹן\">סָפוּן</a>; pl. <span dir=\"rtl\">סְפוּנִים</span>, <span dir=\"rtl\">סְפוּנִין</span>. <span class=\"citation\">Ex. R. s. 20</span> <span dir=\"rtl\">והייתי ס׳ בפניו</span> (some ed. <span dir=\"rtl\">בעיניו</span>) and I enjoyed his respect. Mekh. B’shall., Vayass‘a, s. 2 <span dir=\"rtl\">וכי מה אנו ס׳ שאתם וכ׳</span> what is our distinction, that you murmur against us?; <span class=\"citation\">Yalk. Ex. 258</span>. Tanḥ. Vayesh. 3 <span dir=\"rtl\">אתה עושה … כאלו הוא ס׳</span> thou wouldst treat the idolater as if he (his idolatry) was respected. Ib. <span dir=\"rtl\">אינן ס׳ לכלום</span> are regarded as nothing (before God); a. e.—[</div><div class=\"sense\"><b>2)</b>  (b. h.) <i>to provide, lay up</i>; v. next w.]</div>","alt":[]},"19875":{"h":"סְפַן","r":"O01387","html":"<div class=\"sense\"><b>1)</b> <i>to brighten, scour</i>; v. <i>Ithpe.</i></div><div class=\"sense\"><i>to regard</i>. Targ. II Esth. I, 12. Ib. VII, 9 (10).—3) <i>to look out for, provide, store</i>; (of a bird’s ovary) <i>to be fructified</i>. <span class=\"citation\">Bets. 7ᵃ</span> <span dir=\"rtl\">ביעי דסַפְנָא מארעא</span> eggs laid by a hen that was fecundated by friction in the dust, v. <a href=\"#\" data-headword=\"דְּכַר II\">דִּכְרָא</a>. <span class=\"citation\">Ḥull. 58ᵃ</span> <span dir=\"rtl\">בדספנא מארעא</span></div><div class=\"sense\"><b>Ithpe. אִסְתְּפַן</b> <div class=\"sense\"><b>1)</b> <i>to be brightened, scoured</i>. <span class=\"citation\">Targ. Y. Lev. VI, 21</span> (cmp. <span class=\"citation\">Tosef. Nidd. VIII, 11</span> <span dir=\"rtl\">הצפינן</span>, quot. s. v. <a href=\"#\" data-headword=\"צָפוֹן I\"><span dir=\"rtl\">צָפוֹן</span> I</a>).</div><div class=\"sense\"><b>—2)</b> <i>to be provided, laid in</i>. <span class=\"citation\">Koh. R. to XI, 9</span> [read:] <span dir=\"rtl\">עד דאִיסְתַּפְנוּן פריטוי</span> until the money which he owes is hatched (brought together); (Pesik. Shub., p. 164ᵇ <span dir=\"rtl\">מתפשר</span>, v. <a href=\"#\" data-headword=\"פְּשַׁר I\">פְּשַׁר</a>).</div></div>","alt":[]},"19876":{"h":"סַפָּן","r":"O01388","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (denom. of <a href=\"#\" data-headword=\"סְפִינָה\">סְפִינָה</a>) <i>sailor</i>, <i>captain</i> of a freight ship. <span class=\"citation\">Shebi. VIII, 5</span>, v. <a href=\"#\" data-headword=\"בַּיָּיר\">בַּיָּיר</a>. <span class=\"citation\">Tosef. B. Mets. IX, 14</span>, a. e.—Pl. <span dir=\"rtl\">סַפָּנִין</span>. <span class=\"citation\">Sabb. XV, 1</span>, sq. <span dir=\"rtl\">קשר הס׳</span>, expl. <span class=\"citation\">ib. 111ᵇ</span>, v. <a href=\"#\" data-headword=\"אִיסְטְרִידָא\">אִיסְטְרִידָא</a>. <span class=\"citation\">Kidd. IV, 14</span> <span dir=\"rtl\">הס׳ רובן וכ׳</span> sailors are mostly pious men. <span class=\"citation\">Y. M. Kat. III, 82ᵇ</span> bot. <span dir=\"rtl\">איכריו וסַפָּנָיו וכ׳</span> (not <a href=\"#\" data-headword=\"איבריו\">איבריו</a>) his farm-hands, and the sailors and camel drivers in his employment.</div>","alt":[]},"19877":{"h":"סַפָּנָא","r":"O01389","html":"<div class=\"sense\"> <span class=\"citation\">Bekh. 8ᵇ</span> bot. <span dir=\"rtl\">א&quot;ל לספו׳ וכ׳</span> he said to the captain, untie thy ship.—Pl. <span dir=\"rtl\">סַפָּנִין</span>, <span dir=\"rtl\">סַפָּנַיָּא</span>, <a href=\"#\" data-headword=\"סַפּוֹנָא\">סַפּוֹנָאֵי</a>. <span class=\"citation\">Targ. I Kings IX, 27</span>. <span class=\"citation\">Targ. Jon. I, 5</span>. <span class=\"citation\">Ib. 6</span> (not <a href=\"#\" data-headword=\"סִיפּוּק\">סְפָ׳</a>); a. e.—<span class=\"citation\">B. Mets. 84ᵇ</span> <span dir=\"rtl\">ספונאי</span>; <span class=\"citation\">Yalk. Prov. 964</span> <span dir=\"rtl\">סַפָּנָאֵי</span>. <span class=\"citation\">Ned. 50ᵃ</span>, sq.</div>","alt":["סַפּוֹנָא"]},"19878":{"h":"סַפְנָא","r":"O01390","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"סְפַן\">סְפַן</a>; cmp. <a href=\"#\" data-headword=\"סְפִינָה\">סְפִינָה</a>) <i>store-room, hold</i>. <span class=\"citation\">Snh. 108ᵇ</span> <span dir=\"rtl\">ס׳ דתיבותא</span> the hold of the ark.</div>","alt":[]},"19879":{"h":"ספסוניא","r":"O01391","html":"<div class=\"sense\">, <span class=\"citation\">Yalk. Ps. 656</span>, v. <a href=\"#\" data-headword=\"סִימְפּוֹנְיָא\">סִימְפּוֹנְיָא</a></div>","alt":[]},"19880":{"h":"סַפְסוּפָא","r":"O01392","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (= <span dir=\"rtl\">אספס׳</span>; <span dir=\"rtl\">אסף</span>) <i>riotous gathering</i>, or <i>indiscriminate capture</i> of people during a riot. <span class=\"citation\">Y. Ter. VIII, 46ᵇ</span> bot. <span dir=\"rtl\">איתציד בס׳</span> was caught in a riot.</div>","alt":["סַפְסוּפָה"]},"19881":{"h":"סַפְסִיל","r":"O01393","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"סַפְסָל\">סַפְסָל</a></div>","alt":[]},"19882":{"h":"סַפְסֵירָא","r":"O01394","html":"<div class=\"sense\"> c. (<a href=\"#\" data-headword=\"סְפַר\">סְפַר</a>; cmp. σαμψῆρα Jos. Ant. XX, 2, 2) <i>sword</i>. <span class=\"citation\">Targ. Prov. XII, 18</span>. <span class=\"citation\">Targ. Esth. VIII, 15</span>; a. e.—<span class=\"citation\">B. Bath. 21ᵇ</span> <span dir=\"rtl\">שקל ס׳ למיקטליה</span> he took up a sword to kill him. <span class=\"citation\">Y. Ter. VIII, 46ᵇ</span> bot. <span dir=\"rtl\">טעין חד סַפְסֵר</span> carrying a sword; <span dir=\"rtl\">בהדא ס׳ וכ׳</span> with this sword did Bar N. kill his brother. <span class=\"citation\">Snh. 7ᵃ</span> <span dir=\"rtl\">כי רחימתין עזיזא אפותיא דס׳ וכ׳</span> when our love was strong, we found room to sleep on the broadside of a sword &amp;.; a. e.—Pl. <span dir=\"rtl\">סַפְסֵירֵי</span>. <span class=\"citation\">Targ. Prov. XXX, 14</span> Ms. (ed. <span dir=\"rtl\">סַפְסְרֵי</span>).</div>","alt":[]},"19883":{"h":"סַפְסִירָא","r":"O01395","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> = h. <a href=\"#\" data-headword=\"סַפְסָר\">סַפְסָר</a>, <i>accountant, a middleman, broker</i>. <span class=\"citation\">B. Mets. 42ᵇ</span> <span dir=\"rtl\">ס׳ דזבין וכ׳</span> middleman who buys here and sells there (immediately). <span class=\"citation\">Ib. 63ᵇ</span> <span dir=\"rtl\">והא בעי למיתב זוזי לס׳</span> but would he not have had to pay the broker?, i.e. has he not the advantage of saving the broker’s fee?</div>","alt":[]},"19884":{"h":"סַפְסִירוּתָא","r":"O01396","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"סַפְסִירָא\">preced.</a>) <i>broker’s work, agency</i>. <span class=\"citation\">B. Mets. 63ᵇ</span> <span dir=\"rtl\">זוזי … סַפְסִירוּתֵיה</span> a man’s money does the brokerage for him, i.e. dealers come to the capitalist directly.</div>","alt":[]},"19885":{"h":"סַפְסָל","r":"O01397","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"סֵפֶל\">סֵפֶל</a></div><div class=\"sense\"><b>2)</b> <i>frame, bench, stool</i>. <span class=\"citation\">Kidd. 70ᵃ</span> <span dir=\"rtl\">ס׳ דאמור רבנן וכ׳</span> call it <i>safsal</i> (Hebrew) as the scholars do, or &amp;c. (v. <a href=\"#\" data-headword=\"אִיסְטְבָא\">אִיסְטְבָא</a> 2). <span class=\"citation\">Kel. XXII, 3</span> <span dir=\"rtl\">ס׳ שניטל וכ׳</span> a bench (long board) which has lost one of its ends (supports). <span class=\"citation\">Tosef. Kel. B. Bath. I, 12</span> <span dir=\"rtl\">ס׳ שנתפרק</span> a frame which has fallen apart. <span class=\"citation\">Mikv. V, 2</span>; a. fr.—Pl. <span dir=\"rtl\">סַפְסַלִּים</span>, <span dir=\"rtl\">סַפְסַלִּין</span>. <span class=\"citation\">Y. Ber. IV, 7ᵈ</span> top <span dir=\"rtl\">שמנים ס׳ היו שם של וכ׳</span> eighty benches (forms) of students were there. Tosef. l. c. 11 <span dir=\"rtl\">הס׳ שבפונדקאות</span> the (movable) benches in inns; <span dir=\"rtl\">הס׳ של מלמדי וכ׳</span> the school teachers’ benches (open frames serving as foot-rests for those behind). <span class=\"citation\">Kel. XXII, 10</span> <span dir=\"rtl\">ס׳ שבמרחץ</span> (used as singular) the (marble) board-frame (with wooden supports). <span class=\"citation\">B. Bath. IV, 6</span> <span dir=\"rtl\">לא מכר … הס׳</span> (Babli ed. 67ᵇ <span dir=\"rtl\">הסְפָלִין</span>) has not sold (with the bath-house) the boards of the seats. Ib. 67ᵇ בית הס׳ Ms. H. a. R. (ed. <span dir=\"rtl\">הספלים</span>) the room where the seats are kept. <span class=\"citation\">Pes. 51ᵃ</span> <span dir=\"rtl\">סַפְסַלֵּי נכרים</span> the frames on which gentiles spread their goods. <span class=\"citation\">Snh. 104ᵇ</span> <span dir=\"rtl\">לחכה אש בסַפְסִילֵיהֶן</span> (some ed. <span dir=\"rtl\">בסַפְסַלֵּיהָם</span>). fire lapped their benches; a. fr.</div>","alt":[]},"19886":{"h":"סַפְסְלָא","r":"O01398","html":"<div class=\"sense\"> <span class=\"citation\">Sabb. 29ᵇ</span> <span dir=\"rtl\">גרר ס׳</span> dragged in a form (for the students to sit on). Y. ib. XV, beg. 15ᵃ <span dir=\"rtl\">הן דמקפל על ס׳</span> he who folds a garment over a frame; a. fr.—Pl. <span dir=\"rtl\">סַפְסְלִין</span>, <span dir=\"rtl\">סַפְסְלַיָּא</span>, <span dir=\"rtl\">סַפְסְלַיָּיה</span>, <span dir=\"rtl\">סַפְסְלֵי</span>. <span class=\"citation\">Targ. Y. II, Gen. XV, 17</span>.—<span class=\"citation\">Ber. 28ᵃ</span>, v. <a href=\"#\" data-headword=\"יְסַף\">יְסַף</a>. <span class=\"citation\">Y. Sot. I, 16ᵈ</span> bot., v. <a href=\"#\" data-headword=\"מַרְצְעָא\">מַרְצְעָא</a>; a. e.</div>","alt":["סַפְסְלָה","סִיפְ׳"]},"19887":{"h":"סִפְסֵף","r":"O01399","html":"<div class=\"sense\"> (denom. of <a href=\"#\" data-headword=\"סוֹף\">סוֹף</a>) <i>to cut the ends of, trim; to graze</i>. <span class=\"citation\">Naz. VI, 3</span> (<span class=\"citation\">39ᵃ</span>) <span dir=\"rtl\">או שסי׳ כל שהוא</span> (Bart. <span dir=\"rtl\">ששִׂיפְשֵׂף</span>, cmp. <a href=\"#\" data-headword=\"שָׂפָה\">שָׂפָה</a>) or trimmed his hair ever so little. Ib. 39ᵇ. Y. ib. VI, 55ᵃ bot. <span dir=\"rtl\">לרבות את המְסַפְסֵף</span> to include (in the prohibition) him who trims his hair. <span class=\"citation\">Y. B. Kam. VI, 5ᶜ</span> top <span dir=\"rtl\">סִיפְסְפָה אבניו</span> if the fire grazed his stones. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">או מְסַפְסֵף והולך וכ׳</span> or it went on grazing (objects) even to a mile’s distance; v. <a href=\"#\" data-headword=\"סִכְסֵךְ II\"><span dir=\"rtl\">סִכְסֵךְ</span> II</a>.—<span class=\"citation\">Y. Bets. IV, 62ᶜ</span> bot. <span dir=\"rtl\">אין מְסַפְסְפִין אותה באור</span> you must not trim the ends of a wick by burning it (Bab. <span class=\"citation\">ib. 32ᵇ</span> <span dir=\"rtl\">מהבהבין</span>); v. <a href=\"#\" data-headword=\"פִּסְפֵּס II\"><span dir=\"rtl\">פִּסְפֵּס</span> II</a>.</div>","alt":["סִיפְ׳"]},"19888":{"h":"סַפְסָר","r":"O01400","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (reduplic. of <a href=\"#\" data-headword=\"סָפַר\">סָפַר</a>) <i>accountant, expert in prices, speculator</i>. <span class=\"citation\">B. Mets. 51ᵃ</span> <span dir=\"rtl\">בתגר ס׳ וכ׳</span> it means a speculating trader … he knows well what his goods is worth &amp;c.—V. <a href=\"#\" data-headword=\"סַפְסִירָא\">סַפְסִירָא</a>.</div>","alt":[]},"19889":{"h":"סַפְסֵר","r":"O01401","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"סַפְסֵירָא\">ספְסֵירָא</a></div>","alt":[]},"19890":{"h":"סָפַק I","r":"O01402","html":"<div class=\"sense\"> , <i>Pi.</i> <a href=\"#\" data-headword=\"סָפַק II\">סִיפֵּק</a> </div><div class=\"sense\"><b>1)</b> <i>to strike, clap</i>, esp. <i>to clap the hands against the hips to a certain tune</i> in mourning or in rejoicing; cmp. <a href=\"#\" data-headword=\"טָפַח I\"><span dir=\"rtl\">טָפַח</span> I</a>. <span class=\"citation\">Bets. V, 2</span> (<span class=\"citation\">36ᵇ</span>) <span dir=\"rtl\">ולא מְסַפְּקִין וכ׳</span> you must not clap or dance (on the Sabbath or Holy Day). <span class=\"citation\">Tosef. Sabb. VI</span> (<span class=\"citation\">VII), 2</span> <span dir=\"rtl\">המְסַפֵּק וכ׳</span> he who strikes the hip, claps hands or dances by a flame (a superstitious practice); a. e.—V. <a href=\"#\" data-headword=\"סִיפּוּק ²\"><span dir=\"rtl\">סִיפּוּק</span> I</a>.</div><div class=\"sense\"><b>—2)</b>  (cmp. <a href=\"#\" data-headword=\"נָקַף I\">נָקַף</a>, <a href=\"#\" data-headword=\"נָקַשׁ\">נָקַשׁ</a>) <i>to join closely; to attach; to engraft</i> <span class=\"citation\">Y. Sabb. V, beg. 7ᵇ</span> <span dir=\"rtl\">במְסַפֵּק חבל על חבל</span> when he ties a rope to a rope (of the halter). <span class=\"citation\">Kil. VI, 9</span> <span dir=\"rtl\">סִפְּקָהּ בחבל וכ׳</span> if, in training the vine, he attached to it a rope or a reed (with which he fastened it to a plant). <span class=\"citation\">Par. XII, 1</span> <span dir=\"rtl\">האזוב … מְסַפְּקוֹ וכ׳</span> if the hyssop is too short, he ties it to a thread &amp;c. <span class=\"citation\">Y. Orl. I, 61ᵃ</span> bot. <span dir=\"rtl\">ילדה שסִיפְּקָהּ</span> a young plant (subject to ‘Orlah) which one engrafted on an old tree; a. fr.—V. <a href=\"#\" data-headword=\"סִיפּוּק ²\"><span dir=\"rtl\">סִיפּוּק</span> I</a>.</div>","alt":[]},"19891":{"h":"סְפַק","r":"O01403","html":"<div class=\"sense\">, <i>to strike, knock</i>. <span class=\"citation\">Targ. Job XXXIV, 26</span> <span dir=\"rtl\">סְפֵיקִינוּן</span> ed. Lag. (ed. Wil. <span dir=\"rtl\">סַפְּקִי׳</span> <i>Pa</i>.).—Esp. <i>to clap hands</i>. <span class=\"citation\">Targ. Lam. II, 15</span> (ed. Lag. a. oth. <span dir=\"rtl\">שָׂ׳</span>); a. e.—[<span class=\"citation\">Targ. Koh. IV, 16</span> <span dir=\"rtl\">לאסתפקא</span>, read with ed. Lag. <span dir=\"rtl\">לאִסְתַּקָּפָא</span>, v. <a href=\"#\" data-headword=\"סְקַף I\"><span dir=\"rtl\">סְקַף</span> I</a>.]</div>","alt":["סְפֵיק"]},"19892":{"h":"סָפַק II","r":"O01404","html":"<div class=\"sense\"><i>to divide, distribute; to supply;to suffice</i>. Mekh. B’shall., Vayass‘a, s. 1 <span dir=\"rtl\">ולא סָפְקוּ אלא וכ׳</span> and they supplied water for only seventy date trees; <span dir=\"rtl\">כיון … וספקו להם ושנו וכ׳</span> when the Israelites came and six hundred thousand men encamped around them, they supplied them (with drinking water), and this a second and a third time.</div><div class=\"sense\"><b>Pi. סִיפֵּק</b> <div class=\"sense\"> to <i>supply</i>, <i>furnish</i>. Ib. s. 6 <span dir=\"rtl\">אם מְסַפֵּק לנו צרכנו וכ׳</span> (ed. Weiss <span dir=\"rtl\">מַסְפִּיק</span>, <i>Hif.</i>) if he supplies our wants, we shall serve him &amp;c. <span class=\"citation\">B. Mets. IX, 1</span> (<span class=\"citation\">103ᵇ</span>) <span dir=\"rtl\">שניהם מְסַפְּקִין את הקנים</span> the two together have to furnish the needed poles. <span class=\"citation\">Sot. 11ᵇ</span> <span dir=\"rtl\">היו מְסַפְּקוֹת להם מים ומזון</span> they supplied them with water and food; a. fr.—[<span class=\"citation\">Midr. Till. to Ps. XCII</span> <span dir=\"rtl\">לספק לו</span>, v. <a href=\"#\" data-headword=\"סְפִיקוּלָא I\"><span dir=\"rtl\">סְפִיקוּלָא</span> I</a>.]—V. <a href=\"#\" data-headword=\"סִיפּוּק ²\"><span dir=\"rtl\">סִיפּוּק</span> II</a>.</div></div><div class=\"sense\"><b>Hif. הִסְפִּיק</b> <div class=\"sense\"><b>1)</b> <i>to distribute, supply</i>. <span class=\"citation\">Lev. R. s. 4</span> (ref. to <span dir=\"rtl\">יספוק</span>, <span class=\"citation\">Job XXXIV, 37</span>) <span dir=\"rtl\">אתה מַסְפִּיק בנינו וכ׳</span> thou distributest thy sins among us, i.e. we have to suffer for thy sins; <span class=\"citation\">Yalk. Job 920</span> <span dir=\"rtl\">משתיק</span> (corr. acc.; Var. <span dir=\"rtl\">משְׂפִּיק</span>). Mekh. l. c., v. supra; a. e.</div><div class=\"sense\"><b>—2)</b>  (with <span dir=\"rtl\">ביד</span>) <i>to give sufficient time</i> or <i>power; to allow</i> an opportunity. <span class=\"citation\">Ab. V, 18</span> <span dir=\"rtl\">אין מַסְפִּיקִין בידו וכ׳</span> no time (or opportunity) will be given him to do repentance; <span class=\"citation\">Yoma 87ᵃ</span>; Tosef. ib. V (IV), 11. Ib. 10 <span dir=\"rtl\">אין מספיקין בידו וכ׳</span> he will be given no opportunity (temptation) to sin; a. fr.</div><div class=\"sense\"><b>—3)</b> <i>to have sufficient time, power</i> &amp;c.; <i>to succeed, finish</i>. <span class=\"citation\">Taan. 21ᵃ</span> לא הִסְפַּקְתִּי לפרוק וכ׳ I had not yet finished unloading when &amp;c. Y. Ber. IX, 14ᵇ bot. <span dir=\"rtl\">לא ה׳ לומר עד וכ׳</span> he had not yet finished saying Sh’m‘a, when he expired; a. fr.—[Ib. 14ᵃ <span dir=\"rtl\">מספיק למדינה</span>, v. <a href=\"#\" data-headword=\"סָפַח\">סָפַח</a>.]</div></div><div class=\"sense\"><b>Hitpa. הִסְתַּפֵּק</b> <div class=\"sense\"><i>Nithpa.</i> <a href=\"#\" data-headword=\"סָלַק\">נִסְתַּפֵּק</a> </div><div class=\"sense\"><b>1)</b> <i>to be supplied, to supply one’s self</i>. <span class=\"citation\">Pes. 8ᵃ</span> <span dir=\"rtl\">במִסְתַּפֵּק</span> when it is a store-room from which supplies are taken for the table; <span class=\"citation\">ib. 8ᵇ</span>. Y. Ab. Zar. V, 44ᵈ bot. <span dir=\"rtl\">אבותיכם היו מִסְתַּפְּקִין משלנו וכ׳</span> (not <span dir=\"rtl\">בשלנו</span>) your fathers used to buy supplies (of wine) of our fathers, why do you not buy of us? Y. Dem. III, 23ᶜ, a. e. <span dir=\"rtl\">מִסְתַּפֶּקֶת</span>, v. <a href=\"#\" data-headword=\"סִידְקִי\">סִידְקִי</a>. <span class=\"citation\">Erub. 88ᵃ</span> <span dir=\"rtl\">אדם עשוי להִסְתַּפֵּק סאתים וכ׳</span> a person usually consumes two S’ah of water a day (from the supply in the cistern &amp;c.); a. fr.—<span class=\"citation\">Der. Er. ch. VII</span> <span dir=\"rtl\">ונִסְתַּפְּקוּ</span> they ate and were amply supplied (enjoyed their meal).</div><div class=\"sense\"><b>—2)</b>  (cmp. <a href=\"#\" data-headword=\"סָפֵק\">סָפֵק</a>) <i>to be doubtful</i> Y. Yeb. XI, end, 12ᵇ <span dir=\"rtl\">נ׳ לו</span> he was in doubt.</div></div>","alt":[]},"19893":{"h":"סְפַק ²","r":"O01405","html":"<div class=\"sense\"><b>1)</b> <i>to supply, furnish; to give an opportunity</i>. <span class=\"citation\">Targ. Y. II, Num. XXIV, 6</span>. <span class=\"citation\">Targ. Y. II, Deut. XXVIII, 32</span>.</div><div class=\"sense\"><b>—2)</b> <i>to be sufficient; to have enough; to have done</i>. <span class=\"citation\">Targ. I Kings XX, 10</span>. <span class=\"citation\">Targ. I Chr. XXVII, 24</span>. <span class=\"citation\">Targ. O. Gen. XXIV, 19</span> <span dir=\"rtl\">דִּיסָפְקוּן</span> ed. Berl. (oth. <span dir=\"rtl\">דיסַפְּקוּן</span>, <i>Pa</i>.; Y. <span dir=\"rtl\">די ספְקוּן</span>); a. fr.—[<span class=\"citation\">Targ. Lam. II, 11</span> <span dir=\"rtl\">ספקו בדמען וכ׳</span> my eyes have done shedding tears; prob. to be read: <span dir=\"rtl\">פסקו</span>; h. text <a href=\"#\" data-headword=\"כָּלוּ\">כלו</a>.]</div><div class=\"sense\"><b>Pa. סַפֵּיק</b> <div class=\"sense\"><b>1)</b> <i>to distribute, supply</i>. <span class=\"citation\">Targ. O. Deut. II, 7</span> <a href=\"#\" data-headword=\"סָפַק I\">סַפֶּק</a> (ed. Berl. <a href=\"#\" data-headword=\"סוֹפֵיק\">סוֹפֵיק</a> <i>Poël</i>; Y. ed. Vien. <a href=\"#\" data-headword=\"סוֹפֵיק\">סוּפֵיק</a>, read: <a href=\"#\" data-headword=\"סוּטְרָא\">סוֹ׳</a>). <span class=\"citation\">Targ. Hos. II, 7</span>; a. fr.</div><div class=\"sense\"><b>—2)</b> <i>to be sufficient</i>. <span class=\"citation\">Targ. Jud. XXI, 14</span>. <span class=\"citation\">Targ. Num. XI, 22</span>; a. e.—Esp. (with <a href=\"#\" data-headword=\"יַד\">ידא</a>; interch. with <i>Pe.</i>) <i>to be able, afford</i>, <span class=\"citation\">Targ. Y. Lev. XIV, 21</span>, sq.; <span class=\"citation\">30</span>, sq.—V. <a href=\"#\" data-headword=\"מְסַפְּקָא\">מְסַפְּקָא</a>.</div><div class=\"sense\"><b>—3)</b> <i>to divide</i>.—Part. pass. <a href=\"#\" data-headword=\"מִסְפְּק\">מְסַפַּק</a>, <a href=\"#\" data-headword=\"מְסַפְּקָא\">מְסַפְּקָא</a> <i>divided</i> in opinion, <i>doubtful</i>, <i>questionable</i>. <span class=\"citation\">Targ. Lam. V, 3</span> <span dir=\"rtl\">מס׳ להון</span> they are in doubt.—<span class=\"citation\">Bets. 4ᵇ</span> ר׳ אסי סַפּוּקֵי מס׳ ליה R. A. was undecided in his opinion. <span class=\"citation\">Pes. 117ᵃ</span> <span dir=\"rtl\">אלמא מס׳ ליה</span> which proves that he was undecided; a. fr.—Hence: </div><div class=\"sense\"><b>4)</b> <i>to create a doubt, make doubtful, treat as doubtful</i>. <span class=\"citation\">Kidd. 39ᵃ</span> (ref. to doubtful ‘Orlah fruit outside of Palestine) <span dir=\"rtl\">סַפֵּק לי וכ׳</span> make them doubtful for me (pluck them in my absence), and I shall eat them. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">מְסַפְּקוּ סַפּוּקֵי להדדי</span> they made (the fruit) doubtful to one another (by exchanging fruit cut by the one in the absence of the other). <span class=\"citation\">Bekh. 49ᵃ</span> <span dir=\"rtl\">מְסַפְּקִינָן ליה</span> we treat it as doubtful.</div></div><div class=\"sense\"><b>Poël. סוֹפֵיק  סוֹפָק</b> <div class=\"sense\"><i>to supply</i>. <span class=\"citation\">Targ. Hos. XIII, 5</span>. <span class=\"citation\">Targ. Deut. II, 7</span>, v. supra.</div></div><div class=\"sense\"><b>Af. אַסְפֵּיק</b> <div class=\"sense\"><b>1)</b>  <a href=\"#\" data-headword=\"סָפַק II\">same</a>, <a href=\"#\" data-headword=\"סָפַק II\">same</a>, <i>to supply; to be sufficient</i>. <span class=\"citation\">Targ. Y. II, Gen. XLIX, 20</span>. <span class=\"citation\">Targ. Josh. XVII, 16</span>; a. e.</div><div class=\"sense\"><b>—2)</b> <i>to divide, distribute</i>. <span class=\"citation\">Targ. Job XXXIV, 37</span> (v. <span class=\"citation\">Lev. R. s. 4</span>, quot. in <a href=\"#\" data-headword=\"סָפַק II\">preced.</a>).</div></div>","alt":["סְפֵיק"]},"19894":{"h":"סֵפֶק","r":"O01406","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"סְפַק ²\">preced.</a>) <i>sufficiency</i>, v. <a href=\"#\" data-headword=\"סְפֵיקָה I\"><span dir=\"rtl\">סְפֵיקָה</span> I</a>, a. <a href=\"#\" data-headword=\"סִיפּוּק ²\"><span dir=\"rtl\">סִיפּוּק</span> II</a>.—[<span class=\"citation\">Midr. Till. to Ps. LXXXI, 4</span> <span dir=\"rtl\">ס׳ ידים</span>, v. <a href=\"#\" data-headword=\"סַלְפִּינְגָּס\">סַלְפִּינְגָּס</a>.]</div>","alt":[]},"19895":{"h":"סָפֵק","r":"O01407","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"סֵפֶק\">preced.</a> wds.) </div><div class=\"sense\"><b>1)</b> <i>division</i>, <i>doubt</i>, opp. <a href=\"#\" data-headword=\"וַדַּאי\">וַדַּאי</a>. <span class=\"citation\">Ker. IV, 1</span> <span dir=\"rtl\">ס׳ אכל ס׳ לא אכל</span> if there is a doubt whether or not he has eaten forbidden fat; <span dir=\"rtl\">ס׳ יש בו וכ׳</span> if there is a doubt whether it was the legally required quantity. <span class=\"citation\">B. Bath. 10ᵃ</span> <span dir=\"rtl\">ס׳ מקבלין … ס׳ אין וכ׳</span> it is uncertain whether it will be accepted from him or not. <span class=\"citation\">Ab. Zar. 41ᵃ</span> <span dir=\"rtl\">הוי ס׳ וכ׳</span>, v. <a href=\"#\" data-headword=\"וַדַּאי\">וַדַּאי</a>. <span class=\"citation\">Y. Bets. I, 60ᵇ</span> bot. <span dir=\"rtl\">סְפֵיקוֹ</span>, <a href=\"#\" data-headword=\"סְפֵיקָה I\">סְפֵיקָהּ</a> where there is a doubt about it, v. <a href=\"#\" data-headword=\"וַדַּאי\">וַדַּאי</a>. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">מאי ס׳ וש שם</span> what is the doubt there? i. fr. what difference does it make in practice?—<span class=\"citation\">Yeb. 37ᵇ</span>, a. fr. <span dir=\"rtl\">ממון המוטל בס׳</span>, v. <a href=\"#\" data-headword=\"מָמוֹן\">מָמוֹן</a>. <span class=\"citation\">Ker. VI, 3</span> (<span class=\"citation\">25ᵃ</span>) <span dir=\"rtl\">המתן עד שתכנס לס׳</span> (Var. in Talm. ed. <span dir=\"rtl\">לבית הס׳</span>) wait until you arrive at a condition of doubt, i.e. until you are in doubt as to having committed a sin requiring a sacrifice. Ib. 2 <span dir=\"rtl\">כִּפְּרָה סְפֵיקָהּ וכ׳</span> the heifer has atoned for the doubt for which it has been put to death, and is gone (i.e. at the time of its being thrown down the murderer was unknown); ib. 25ᵃ <span dir=\"rtl\">עדיין לא כיפרה סְפֵיקָתָהּ</span> it had not yet atoned for the doubt for which it was to be put to death; a. v. fr.—Pl. <span dir=\"rtl\">סְפֵיקוֹת</span>, <span dir=\"rtl\">סְפֵק׳</span> (<i>fem</i>.). <span class=\"citation\">Kidd. IV, 3</span> <span dir=\"rtl\">ואלו הן הס׳</span> and these are the cases of uncertain parentage. <span class=\"citation\">B. Mets. 83ᵇ</span> <span dir=\"rtl\">ס׳ שלכם</span> cases in which you act on doubts (mere suspicion), v. <a href=\"#\" data-headword=\"וַדָּאָה\">וַדָּאָה</a>. <span class=\"citation\">Y. Keth. I, beg. 24ᵈ</span> <span dir=\"rtl\">שתי ס׳</span> a double doubt, v. <a href=\"#\" data-headword=\"סְפֵקָא\">next w.</a>; a. e.</div><div class=\"sense\"><b>—2)</b> <i>dilemma</i>, <i>difficulty</i>. <span class=\"citation\">Cant. R. to VII, 8</span> <span dir=\"rtl\">למה באו ישראל בס׳ וכ׳</span> why did the Israelites get into trouble in the days of Haman?</div>","alt":[]},"19896":{"h":"סְפֵקָא","r":"O01408","html":"<div class=\"sense\"> <span class=\"citation\">Targ. Y. Lev. VIII, 15</span> <a href=\"#\" data-headword=\"סְפֵיק\">סְפֵיק</a> (<a href=\"#\" data-headword=\"סָפַק I\">סְפֵק</a>) constr.—<span class=\"citation\">Ber. 3ᵇ</span> <span dir=\"rtl\">מי איכא ס׳ קמי וכ׳</span> is there a doubt before God?; <span class=\"citation\">Gitt. 6ᵇ</span>. <span class=\"citation\">Ker. 21ᵃ</span>, a. e. <span dir=\"rtl\">כוי ס׳ הוא</span> the Koy is a doubtful animal (as to classification), v. <a href=\"#\" data-headword=\"כּוֹי\">כּוֹי</a>. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">אצטריך קרא למיסר ס׳</span> does it need a special intimation in the Biblical text to forbid the blood of an animal of doubtful classification?; <span class=\"citation\">Yoma 74ᵇ</span> <span dir=\"rtl\">אצטריך קרא לרבויי ס׳</span> does it need an intimation in order to include an animal of doubtful classification (i.e. is it doubtful with God who revealed the Law)?; a. v. fr.—<span dir=\"rtl\">(<a href=\"#\" data-headword=\"סָפַק I\">סְפֵק</a>) <span dir=\"rtl\">סְפֵיק ס׳</span></span> the doubt of a doubt, <i>double doubt</i>. <span class=\"citation\">Ab. Zar. 70ᵃ</span> bot. <span dir=\"rtl\">הוי ליה ס׳ ס׳</span> it is a doubly doubtful case (first, whether a Jew or a gentile opened the cask, and secondly, if a gentile, whether he touched the wine). <span class=\"citation\">Keth. 9ᵃ</span>; a. fr.—Pl. <span dir=\"rtl\">סְפֵקי</span>, <a href=\"#\" data-headword=\"סְפֵקָא\">סְפֵי׳</a>. <span class=\"citation\">Ḥull. 18ᵇ</span> <span dir=\"rtl\">דאפילו ס׳ דגברי גריס</span> who records even the doubts as to the authorities of a Halakhah. <span class=\"citation\">Ib. 95ᵇ</span> <span dir=\"rtl\">תליסר גמלי ס׳ וכ׳</span> thirteen camel loads of questionable cases of <i>t’refah</i>; a. e.</div>","alt":["סְפֵי׳"]},"19897":{"h":"סְפֵקָה","r":"O01409","html":"<div class=\"sense\">, pl. <span dir=\"rtl\">סְפֵקוֹת</span>, v. <a href=\"#\" data-headword=\"סָפֵק\">סָפֵק</a>.</div>","alt":[]},"19898":{"h":"סְפִקוּלָא","r":"O01410","html":"<div class=\"sense\"> …, v. <a href=\"#\" data-headword=\"סְפִיקוּלָא I\">סְפִיקוּלָא</a></div>","alt":["ספקלא","לה"]},"19899":{"h":"סְפִקְלָאטוֹר","r":"O01411","html":"<div class=\"sense\"> masc. (speculator, v. <a href=\"#\" data-headword=\"אִיסְפִּקְלָטוֹר\">אִיסְפִּקְלָטוֹר</a>) <i>executioner</i>. <span class=\"citation\">Sifré Num. 91</span>. <span class=\"citation\">Lev. R. s. 26</span> <span dir=\"rtl\">נעשה ס׳ לכל וכ׳</span> (the serpent) has become the executioner for all who break down fences (of customs, with ref. to <span class=\"citation\">Koh. X, 8</span>). <span class=\"citation\">Lam. R. to II, 1</span>; a. fr.—Pl. <span dir=\"rtl\">סְפִקְלָטוֹרִים</span>, <span dir=\"rtl\">סְפִקְלָטוֹרִין</span>. Ib. introd. (R. <span class=\"citation\">Josh. 2</span>) <span dir=\"rtl\">לפתח … ספקלטרים</span> ‘to open the mouth for murder’ (<span class=\"citation\">Ezek. XXI, 27</span>) refers to the executioners. <span class=\"citation\">Pirké d’R. El. ch. XLVIII</span> <span dir=\"rtl\">סְפִקְלָטוֹרֵי פרעה</span> (not <a href=\"#\" data-headword=\"סנקלוס\">סנקלטורי</a>) Pharaoh’s executioners; a. e.</div>","alt":["סְפִקְלָטוֹר"]},"19900":{"h":"ספקלטרים","r":"O01412","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"סְפִקְלָאטוֹר\">preced.</a></div>","alt":[]},"19901":{"h":"*ספקלי","r":"O01413","html":"<div class=\"sense\">, <span class=\"citation\">Koh. R. to IX, 18</span> (expl. <span dir=\"rtl\">על הבית</span> <span class=\"citation\">II Kings XVIII, 37</span>), a corruption, prob. to be read <span dir=\"rtl\">פילקס</span> (φύλαξ) <i>chief of the guard</i> (excubitor).—V. <a href=\"#\" data-headword=\"*סִקְרִיפְטוֹר\">סִקְרִיפְטוֹר</a>.</div>","alt":[]},"19902":{"h":"סְפַקְלַרְיָא","r":"O01414","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (specularia) <i>window-panes; mirror</i>. <span class=\"citation\">Y. Ber. VIII, 12ᵇ</span> bot. <span dir=\"rtl\">נר … בתוך ס׳</span> a light in one’s lap, in a lantern, or seen in a mirror. <span class=\"citation\">Kel. XXX, 2</span> <span dir=\"rtl\">תמחוי שעשאו ס׳</span> ed. Dehr., v. <a href=\"#\" data-headword=\"אִסְפַּקְלַרְיָא\">אִסְפַּקְלַרְיָא</a>. Tosef. Erub. XI (VIII), 17 <span dir=\"rtl\">מלבן של ס׳</span> a frame with glass, i.e. a glass window; a. e.</div>","alt":[]},"19903":{"h":"סָפַר","r":"O01415","html":"<div class=\"sense\"> (b. h.) [<i>to cut; to mark</i>,] </div><div class=\"sense\"><b>1)</b> <i>to write; to count</i>. <span class=\"citation\">Y. Kil. VII, end, 31ᵃ</span> <span dir=\"rtl\">יִסְפּוֹר</span> he (who is in possession of property bought from an oppressor, v. <a href=\"#\" data-headword=\"אַנָּס\">אַנָּס</a>) must count (settle with the original owner according to rules, v. <a href=\"#\" data-headword=\"גּוֹרְדְּיָינִי\">גוֹרְדְּיָינִי</a>), opp. <span dir=\"rtl\">יחזיר</span> he must return the property; <span class=\"citation\">ib.</span> <span dir=\"rtl\">יִסְפֹּר</span> (or <span dir=\"rtl\">יְסַפֵּר</span> <i>Pi.</i>). <span class=\"citation\">Kidd. 30ᵃ</span> <span dir=\"rtl\">שהיו סוֹפְרִים</span>, v. <a href=\"#\" data-headword=\"סוֹפֵר\">סוֹפֵר</a>. <span class=\"citation\">Nidd. 69ᵃ</span> <span dir=\"rtl\">סוֹפַרְתָּן למנין וכ׳</span> she counts them in with the requisite number of seven days. <span class=\"citation\">Ib. 31ᵃ</span> <span dir=\"rtl\">יושב וסוֹפֵר וכ׳</span> sits and records the copulations &amp;c. <span class=\"citation\">Men. 65ᵇ</span>, v. <a href=\"#\" data-headword=\"סְפִירָה\">סְפִירָה</a>; a. v. fr.—[<span class=\"citation\">Sifré Deut. 33</span> <span dir=\"rtl\">סופרה</span>; read: <span dir=\"rtl\">סופנה</span>, v. <a href=\"#\" data-headword=\"סָפַן\">סָפַן</a>.]—Part. pass. <a href=\"#\" data-headword=\"סָפוּר\">סָפוּר</a>, q. v.</div><div class=\"sense\"><b>—2)</b> <i>to cut, shear</i>, v. infra.</div><div class=\"sense\"><b>Nif. נִסְפַּר</b> <div class=\"sense\"><i>to be counted</i>. <span class=\"citation\">Bekh. 45ᵃ</span> <span dir=\"rtl\">שנִסְפֶּרֶת ע&quot;ג היד</span> when the additional finger is counted (is in a line) with the others; <span class=\"citation\">Yalk. Sam. 156</span>.</div></div><div class=\"sense\"><b>Pi. סִיפֵּר</b> <div class=\"sense\"><b>1)</b> <i>to cut, shear</i>. <span class=\"citation\">Sot. 49ᵇ</span>, a. fr. <span dir=\"rtl\">מְסַפֵּר קומי</span>, v. <a href=\"#\" data-headword=\"קוֹמִי I\"><span dir=\"rtl\">קוֹמִי</span> I</a>. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">התירו</span> (<span dir=\"rtl\">לו</span>)<span dir=\"rtl\">לסַפֵּר וכ׳</span> they allowed him to cut his hair in gentile fashion, because of his connections with royalty. Sifra Aḥăré, Par. 9, ch. XIII <span dir=\"rtl\">תִּסְפּוֹר</span>, v. <a href=\"#\" data-headword=\"קוֹמִי I\"><span dir=\"rtl\">קוֹמִי</span> I</a>. <span class=\"citation\">Tosef. Bets. III, 19</span> <span dir=\"rtl\">אין מְסַפְּרִין הירק וכ׳</span> you must not no trim vegetables with the clipper (on the Holy Day) &amp;c.; a. fr.</div><div class=\"sense\"><b>—2)</b> <i>to tell, speak, count</i>. Y. Kil. l. c., v. supra. <span class=\"citation\">Gen. R. s. 78</span> (ref. to <span dir=\"rtl\">אברם</span> in place of <span dir=\"rtl\">אברהם</span>, <span class=\"citation\">Neh. IX, 7</span>) <span dir=\"rtl\">סיפור הוא מְסַפֵּר וכ׳</span> he states a historical fact, saying &amp;c. Y. Ber. IX, beg. 12ᵈ <span dir=\"rtl\">אם בא אדם לסַפֵּר וכ׳</span> if one were to undertake to count the mighty deeds of the Lord, he would be ruined (ref. to <span class=\"citation\">Job XXXVII, 20</span>); <span dir=\"rtl\">המספר בשבחו וכ׳</span> he who tells the praise of the Lord more than is becoming. Ib. <span dir=\"rtl\">מכאן … אסור לסַפֵּר וכ׳</span> beyond that (which has been adopted in ritual prayers) one must not tell &amp;c. <span class=\"citation\">Arakh. 16ᵃ</span> <span dir=\"rtl\">לעולם אל יְסַפֵּר אדם בטובתו וכ׳</span> man should not count up his neighbor’s good qualities, for he may be induced to speak of his shortcomings; <span class=\"citation\">B. Bath. 164ᵇ</span>. <span class=\"citation\">Sot. 42ᵃ</span> <span dir=\"rtl\">מְספְּרֵי לשון הרע</span> gossipers. <span class=\"citation\">Snh. 38ᵇ</span> <span dir=\"rtl\">בלשון ארמי סי׳</span> spoke Aramæan; a. v. fr.—<span class=\"citation\">Ib. 52ᵇ</span> <span dir=\"rtl\">סי׳ הימנו</span> if he (the scholar) holds conversation with him.</div></div><div class=\"sense\"><b>Hithpa. הִסְתַּפֵּר</b> <div class=\"sense\"><i>to have one’s hair cut</i>. <span class=\"citation\">Ab. Zar. II, 2</span> <span dir=\"rtl\">אין מִסְתַּפְּרִין מהן וכ׳</span> you must not have your hair cut by them in any place (on account of danger to life). <span class=\"citation\">Tosef. ib. III, 5</span> <span dir=\"rtl\">ישראל המִסְתַּפֵּר וכ׳</span> if an Israelite has his hair cut by a gentile, he must look into the mirror; <span class=\"citation\">Ab. Zar. 29ᵃ</span>; a. fr.</div></div>","alt":[]},"19904":{"h":"סְפַר","r":"O01416","html":"<div class=\"sense\"><b>1)</b> <i>to count, mark, write</i>, v. <a href=\"#\" data-headword=\"סָפַר ²\"><span dir=\"rtl\">סַפְרָא</span> I</a>. I.</div><div class=\"sense\"><b>—2)</b> <i>to shear</i>, v. infra.</div><div class=\"sense\"><b>Pa. סַפֵּר</b> <div class=\"sense\"><i>to cut, shear, shave</i>. <span class=\"citation\">Targ. Job I, 20</span> (Ms. <a href=\"#\" data-headword=\"סְפַר\">סְפַר</a> <i>Pe.</i>). <span class=\"citation\">Targ. Y. Lev. XIII, 33</span> (not <span dir=\"rtl\">יַסְפֵּר</span>); <span class=\"citation\">ib. XIV, 8</span>, sq. (h. text <span dir=\"rtl\">גלח</span>); a. fr.—<span class=\"citation\">Lev. R. s. 28</span>, end <span dir=\"rtl\">יתיב ומְסַפֵּר ליה</span> (Haman) sat down and cut his (Mordecai’s) hair; <span class=\"citation\">ib.</span> <span dir=\"rtl\"><span dir=\"rtl\">מן דחסל</span> (<span dir=\"rtl\">מן</span>) <span dir=\"rtl\">מְסַפְּרָא ליה</span></span> when he had done cutting his hair; a. fr.—Part. pass. <span dir=\"rtl\">מְסַפֵּר</span>. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">אית בר נש … ולא מ׳</span> is there a man who putts the royal crown on his head without having his hair cut?; <span class=\"citation\">Esth. R. to VI, 10</span>.</div></div>","alt":[]},"19905":{"h":"סַפָּר","r":"O01417","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"סְפַר\">preced.</a> wds.) </div><div class=\"sense\"><b>1)</b>  (v. <a href=\"#\" data-headword=\"סֵפֶר\">סֵפֶר</a>) <i>Bible teacher</i>. <span class=\"citation\">Y. Maasr. III, 50ᵈ</span> <span dir=\"rtl\">בית … טובלין לס׳ ולמַשְׁנֶה</span> (not <span dir=\"rtl\">ולא למש׳</span>) school houses for Bible and Talmud make fruits <i>ṭebel</i> for the Bible teacher and for the Talmud teacher. [Perh. to be read: <a href=\"#\" data-headword=\"סָפַר\">סָפַר</a> Chald. form.]</div><div class=\"sense\"><b>—2)</b> <i>hair-cutter, barber</i>. <span class=\"citation\">Sabb. I, 2</span> <span dir=\"rtl\">לא ישב אדם לפני הס׳ וכ׳</span> one must not sit down for the hair-cutter near Minḥah time beforesaying the prayer. <span class=\"citation\">Shebi. VIII, 5</span>; a. e.—Pl. <span dir=\"rtl\">סַפָּרִים</span>, <span dir=\"rtl\">סַפָּרִין</span>. <span class=\"citation\">Kel. XIII, 1</span> <span dir=\"rtl\">זוג של ס׳</span> the barbers’ scissors. <span class=\"citation\">Sabb. 9ᵇ</span>. v. <a href=\"#\" data-headword=\"מַעֲפוֹרֶת\">מַעֲפוֹרֶת</a>; a. e.</div>","alt":[]},"19906":{"h":"סַפָּר ²","r":"O01418","html":"<div class=\"sense\">, <i>hair-cutter</i>. Targ. II Esth. VI, 12.—<span class=\"citation\">Lev. R. s. 28</span>, end; <span class=\"citation\">Esth. R. to VI, 10</span>. <span class=\"citation\">Lev. R. s. 14</span>, end <span dir=\"rtl\">לית ס׳ דמספר לגרמיה</span> no hair-cutter can cut his own hair (i.e. the female sperm begets the male embryo and vice versa); a. e.</div>","alt":["סַפָּרָא"]},"19907":{"h":"סְפָר","r":"O01419","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"סָפַר\">סָפַר</a>) [<i>mark</i>, <i>march</i>,] <i>boundary, border district</i>. <span class=\"citation\">Yeb. 48ᵇ</span> <span dir=\"rtl\">עיר הסמוכה לס׳</span> a town near the boundary. <span class=\"citation\">Sot. 42ᵃ</span> <span dir=\"rtl\">פעמים מדבר עמו אחת בס׳ וכ׳</span> the priest addressed the people twice, once on the border line (before entering the enemy’s land) and once before the battle. <span class=\"citation\">Tosef. Erub. IV</span> (<span class=\"citation\">III), 5</span> <span dir=\"rtl\">באו … הסמוכות לס׳</span> if the enemy invades towns near the boundary (of Palestine); Y. ib. IV, 21ᵈ bot.; Bab. <span class=\"citation\">ib. 45ᵃ</span>. <span class=\"citation\">Ib.</span> <span dir=\"rtl\">ובבל כעיר הסמוכה לס׳ וכ׳</span> and Babylonia is (as regards the duty of defence) like a town near the boundary, which was interpreted to mean Neharde‘a. <span class=\"citation\">Num. R. s. 16</span> <span dir=\"rtl\">מה ראה לישב לו על הס׳ וכ׳</span> what reason had he (Amalek) to settle on the border, on the way of the entrance of the Israelites into the land?; a. e.—<i>Pi.</i> <span dir=\"rtl\">סְפָרִים</span>, constr. <span dir=\"rtl\">סִפְרֵי</span>. <span class=\"citation\">Y. Ḥall. II, 58ᵇ</span> bot. <span dir=\"rtl\">ס׳ א&quot;י</span> Palestinian districts, <span dir=\"rtl\">ס׳ חוצה לארץ</span> foreign districts (conquered by Israelites).</div>","alt":[]},"19908":{"h":"סְפַר ²","r":"O01420","html":"<div class=\"sense\"> constr. <a href=\"#\" data-headword=\"סְפַר\">סְפַר</a>, same; <span dir=\"rtl\">ס׳ יַמָּא</span> <i>sea-district</i>. <span class=\"citation\">Targ. O. Gen. XLIX, 13</span> (h. text <a href=\"#\" data-headword=\"חָף\">חֹף</a>); a. fr.—Pl. <span dir=\"rtl\">סַפְרַיָּא</span>, constr. <span dir=\"rtl\">סַפְרֵי</span>. Targ. Y. ib.—[<span class=\"citation\">Targ. Y. Lev. XIII, 45</span> <span dir=\"rtl\">ספריא</span>, some ed., v. <a href=\"#\" data-headword=\"סָפְדָּא\">סָפְדָּא</a>.]</div>","alt":[]},"19909":{"h":"סָפֵר","r":"O01421","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"סְפַר ²\">preced.</a> wds.) = <a href=\"#\" data-headword=\"סְפִירָה\">סְפִירָה</a>, <i>counting</i>. <span class=\"citation\">Naz. VII, 3</span> (<span class=\"citation\">54ᵃ</span>) <span dir=\"rtl\">ימי סְפֵרוֹ</span> (comment. <span dir=\"rtl\">סְפֵירוֹ</span>; Y. ed. <span dir=\"rtl\">ספורו</span>) the days which the cured leper has to count (<span class=\"citation\">Lev. XIV, 8</span>); Y. ib. 56ᶜ bot. <span dir=\"rtl\">ספירו</span>.</div>","alt":[]},"19910":{"h":"סֵפֶר","r":"O01422","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> <a href=\"#\" data-headword=\"סָפֵר\">preced.</a> wds.) <i>letter, document, book</i>. <span class=\"citation\">Erub. 15ᵇ</span>; <span class=\"citation\">Gitt. 21ᵇ</span>; <span class=\"citation\">Succ. 24ᵇ</span>, v. <a href=\"#\" data-headword=\"סְפִירָה\">סְפִירָה</a>. <span class=\"citation\">Eduy. I, 12</span>, a. fr. <span dir=\"rtl\">ס׳ כתובה</span> the formula of a <i>Kethubah</i>. <span class=\"citation\">Y. Sot. IX, end, 24ᶜ</span> <span dir=\"rtl\">משמת ר&quot;א נגנז ס׳ החכמה</span> with the death of R. El. a book of wisdom disappeared; Bab. <span class=\"citation\">Sot. 49ᵇ</span> <span dir=\"rtl\">נגנז ס׳ תורה</span>; <span class=\"citation\">Tosef. ib. XV, 3</span> <span dir=\"rtl\">בטל ס׳ תורה</span>. <span class=\"citation\">Gen. R. s. 24</span> <span dir=\"rtl\">סִפְרוֹ של אה&quot;ר</span> the book of Adam (the destinies of humanity); <span class=\"citation\">Ex. R. s. 40</span>; <span class=\"citation\">Lev. R. s. 15</span> beg.; a. fr.—Esp. a <i>Biblical book</i>. <span class=\"citation\">B. Bath. 15ᵃ</span> ירמיה כתב ספרו וס׳ מלכים וכ׳ Jeremiah wrote his book (the prophecies of Jerem.) and the Book of Kings and the Lamentations. Ib. 14ᵇ משה כתב ספרו וכ׳ Moses wrote his own book, and the Section of Balaam (the chapters on B., <span class=\"citation\">Num. XXII, 2</span>—XXIV, 25) and Job; <span class=\"citation\">Y. Sot. V, end, 20ᵈ</span>; a. v. fr.—<span dir=\"rtl\">ס׳ תורה</span> (abbrev. <span dir=\"rtl\">ס&quot;ת</span>) (or <a href=\"#\" data-headword=\"ס׳\">ס׳</a> only) <i>the Pentateuch</i> in a scroll. <span class=\"citation\">Ab. Zar. 18ᵃ</span> <span dir=\"rtl\">כרכוהו בס&quot;ת וכ׳</span> they wrapped him up in the scroll &amp;c. <span class=\"citation\">Sabb. 116ᵃ</span> <span dir=\"rtl\">ס&quot;ת שנמחק</span> a scroll of the Pentateuch the writing of which is effaced; <span class=\"citation\">Yad. III, 5</span> <span dir=\"rtl\">ס׳ שנמחק</span>; a. v. fr.—<span class=\"citation\">Kel. XV, 6</span>, a. e. <span dir=\"rtl\">ס׳ העזרה</span> the Pentateuch kept in the Temple court, v. <a href=\"#\" data-headword=\"עֲזָרָה\">עֲזָרָה</a>.—<span dir=\"rtl\">ס׳ הוא</span>, <span dir=\"rtl\">ס׳ זעטוטים</span> &amp;c., v. respective determinants.—<a href=\"#\" data-headword=\"סַלּוּנִי\">בֵּית סֵ׳</a>, <span dir=\"rtl\">בֵּית הַסֵּ׳</span> the school in which the Bible is taught, secondary school, contrad. to <span dir=\"rtl\">בית תלמוד</span> Talmud school. <span class=\"citation\">Y. Maasr. III, 50ᵈ</span>, v. <a href=\"#\" data-headword=\"סַפָּר\">סַפָּר</a> 1. <span class=\"citation\">Midr. Till. to XCII, 16</span> שתולים … אלו התינוקות שבבית הס׳ ‘planted in the house of the Lord’ (<span class=\"citation\">ib. 14</span>), that means the children at school; a. fr.—Pl. <span dir=\"rtl\">סְפָרִים</span>, constr. <span dir=\"rtl\">סִפְרֵי</span>, <a href=\"#\" data-headword=\"סִפְלָא\">סִיפְ׳</a>. <span class=\"citation\">Ex. R. s. 41</span> <span dir=\"rtl\">זריז בכ&quot;ד ס׳</span> well-versed in the twenty-four books of the Scripture. <span class=\"citation\">Sabb. 116ᵃ</span> <span dir=\"rtl\">(<span dir=\"rtl\">ס׳ צדוקים</span>) <span dir=\"rtl\">ס׳ מינים</span></span> heretical books, v. <a href=\"#\" data-headword=\"מִין III\"><span dir=\"rtl\">מִין</span> III</a>. <span class=\"citation\">Snh. 68ᵃ</span> <span dir=\"rtl\">שתי … כשני ס׳ תורה וכ׳</span> my two arms which are like two rolled up scrolls of the Torah, a. v. fr.—Ch. <a href=\"#\" data-headword=\"סִפְרָא\">סִפְרָא</a>, constr. <a href=\"#\" data-headword=\"סֵפֶר\">סֵפֶר</a>.</div>","alt":[]},"19911":{"h":"סָפַר ²","r":"O01423","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> = h. <a href=\"#\" data-headword=\"סוֹפֵר\">סוֹפֵר</a>, </div><div class=\"sense\"><b>1)</b> <i>scribe, writer of documents; copyist</i>. <span class=\"citation\">Targ. Jer. XXXVI, 20</span>, sq.; a. fr.—<span class=\"citation\">Ab. Zar. 9ᵃ</span>, v. <a href=\"#\" data-headword=\"בַּצִּירָא\">בַּצִּירָא</a>, <span class=\"citation\">Ib. 10ᵃ</span>, v. <a href=\"#\" data-headword=\"דַּוְקָנָא\">דַּוְקָנָא</a>. <span class=\"citation\">Ḥull. 64ᵇ</span>, sq. <span dir=\"rtl\">פסיק להו ס׳ וכ׳</span> the copyist (of the Scriptures) divides them into two words. <span class=\"citation\">Y. Succ. II, 53ᵃ</span> top <span dir=\"rtl\">סַפְרָה דגופתא</span> the scribe of Gufta; a. fr.</div><div class=\"sense\"><b>—2)</b> <i>scholar</i>, <i>teacher</i>. <span class=\"citation\">Targ. Is. III, 2</span> (h. text <span dir=\"rtl\">נביא</span>); <span class=\"citation\">ib. IX, 14</span>. <span class=\"citation\">Targ. O. Gen. XLIX, 10</span> (h. text <span dir=\"rtl\">מחקק</span>); a. fr.—<span class=\"citation\">Gen. R. s. 70</span>, end <span dir=\"rtl\">אית ס׳ דלית וכ׳</span> is there a teacher that has no pupils?, i.e. I (Laban) learned trickery from you (Jacob).—Esp. <i>Bible teacher</i>. <span class=\"citation\">Y. Ḥag. I, 76ᶜ</span>, a. e., v. <a href=\"#\" data-headword=\"מַתְנְיָין\">מַתְנְיָין</a>; a. fr.—<span dir=\"rtl\">ס׳ מתא</span>, v. <a href=\"#\" data-headword=\"סוֹפֵר\">סוֹפֵר</a>.—Pl. <span dir=\"rtl\">סַפְרַיָּא</span>, <span dir=\"rtl\">סַפְרַיָּיא</span>, <span dir=\"rtl\">סַפְרִין</span>, <span dir=\"rtl\">סַפְרֵי</span>. <span class=\"citation\">Targ. Y. I Gen. XLIX, 10</span>. <span class=\"citation\">Targ. I Sam. X, 15</span> (h. text <span dir=\"rtl\">נביאים</span>); a. fr.—<span class=\"citation\">Sot. IX, 5</span> (<span class=\"citation\">49ᵃ</span>), v. <a href=\"#\" data-headword=\"חַכִּים II\">חַכִּימָא</a>. <span class=\"citation\">Midr. Till. to Ps. XCI, 6</span> <span dir=\"rtl\">מפקיד לס׳ וכ׳</span> ordered the school teachers to let the children go free (during the summer) from the fourth to the ninth hour of the day; <span class=\"citation\">Lam. R. to I, 3</span>; <span class=\"citation\">Num. R. s. 12</span> <span dir=\"rtl\">לסַפְרַיָּה</span>; a. fr.</div>","alt":["סַפְרָא I"]},"19912":{"h":"סַפְרָא II","r":"O01424","html":"<p class=\"morphology\">pr. n. m.</p><div class=\"sense\"><i>Safra</i>, an Amora. <span class=\"citation\">Pes. 52ᵇ</span>. <span class=\"citation\">Ḥull. 110ᵇ</span>; a. fr.—V. Fr. M’bo, p. 119ᵃ</div>","alt":[]},"19913":{"h":"סַפָּרָא","r":"O01425","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"סַפָּר\">סַפָּר</a> ch.</div>","alt":[]},"19914":{"h":"סִפְרָא","r":"O01426","html":"<div class=\"sense\"> constr. <a href=\"#\" data-headword=\"סְפַר\">סְפִר</a>, <a href=\"#\" data-headword=\"סֵפֶר\">סֵפֶר</a>, </div><div class=\"sense\"><b>1)</b>  = h. <a href=\"#\" data-headword=\"סֵפֶר\">סֵפֶר</a>. <span class=\"citation\">Targ. Is. XXIX, 11</span>, sq. <span class=\"citation\">Targ. Ex. XVII, 14</span>. <span class=\"citation\">Targ. II Chr. XXXIV, 15</span>; a. fr.—<span class=\"citation\">B. Mets. 85ᵇ</span> bot. <span dir=\"rtl\">ס׳ דאדה&quot;ר</span> the book of Adam, v. <a href=\"#\" data-headword=\"סֵפֶר\">סֵפֶר</a>. <span class=\"citation\">Ber. 23ᵃ</span> <span dir=\"rtl\">ס׳ דאגדתא</span> a homiletical book, v. <a href=\"#\" data-headword=\"אֲגַדְתָּא\">אֲגַדְתָּא</a>; a. fr.—Esp. <i>Biblical book; Pentateuch</i>. <span class=\"citation\">Snh. 93ᵇ</span> <span dir=\"rtl\">מאי טעמא לא איקרי ס׳ על שמיה</span> why was the book (of Ezra) not named from him (Nehemiah)? <span class=\"citation\">Meg. 22ᵃ</span> <span dir=\"rtl\">קרא בס׳</span> he read from the Law. <span class=\"citation\">B. Kam. 82ᵃ</span> <span dir=\"rtl\">דנין … דשכיחי דאתו למקרא בס׳</span> court is held on Mondays and Thursdays, because they (the villagers) are accustomed to come (to town) for the reading of the Law; a. fr.—Pl. <span dir=\"rtl\">סִפְרַיָּא</span>, <span dir=\"rtl\">סִפְרַיָּיא</span>, <span dir=\"rtl\">סִפְרֵי</span>, <a href=\"#\" data-headword=\"סִבְכָא\">סִי׳</a>. <span class=\"citation\">Targ. Koh. XII, 9</span>; <span class=\"citation\">12</span>.—<span class=\"citation\">Y. Maasr. III, end, 51ᵃ</span> <span dir=\"rtl\">וצווח להון ס׳ קוסמי</span> called them (the books of Agadah) books of sorcery; a. fr.</div><div class=\"sense\"><b>—2)</b>  <span dir=\"rtl\">ספרא דבי רב</span>, or <a href=\"#\" data-headword=\"ס׳\">ס׳</a> <i>Sifra</i> (<i>of the school</i>), also called <span dir=\"rtl\">תּוֹרַת כֹּהֲנִים</span>, a halakhic commentary on Leviticus. <span class=\"citation\">Targ. I Chr. XI, 22</span>.—<span class=\"citation\">Ber. 18ᵇ</span>. <span class=\"citation\">Ib. 11ᵇ</span>; a. fr.—Pl. <span dir=\"rtl\">סִפְרֵי</span> <i>Sifré</i> (<i>d’Be Rab</i>), a halakhic commentary on Numbers and Deuteronomy. <span class=\"citation\">Snh. 86ᵃ</span> <span dir=\"rtl\">סתם סיפרא … ס׳ וכ׳</span> an anonymous tradition in Sifra belongs to R. Judah, in Sifré, to R. S.—<span class=\"citation\">Yoma 74ᵃ</span> <span dir=\"rtl\">בשאר ס׳ דבי רב</span> in a fragment of the books of Be Rab (ref. to Sifra Emor, Par. 11, ch. XIV).</div>","alt":["סִי׳"]},"19915":{"h":"ספרגוס","r":"O01427","html":"<div class=\"sense\">, read:</div>","alt":[]},"19916":{"h":"סְפַרְגִּיס","r":"O01428","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (σφραγίς) <i>seal</i>. <span class=\"citation\">Gen. R. s. 32</span> <span dir=\"rtl\">נתן ס׳ שלו עליו</span> he put his seal on it (the prison door); ib. s. 49; <span class=\"citation\">Yalk. Gen. 34</span> <a href=\"#\" data-headword=\"אִיסְפַּרְגּוֹס\">איספרגוס</a>. <span class=\"citation\">Midr. Till. to Ps. XVII</span>, beg. <span dir=\"rtl\">שמו של הקב&quot;ה חקוק … כמין איסטירטיגוס</span> (ed. Bub. <span dir=\"rtl\">איסטרטיגוס</span>; corr. acc.) the name of the Lord is impressed upon the hearts of the angels like a seal.</div>","alt":[]},"19917":{"h":"סַפְרָה","r":"O01429","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"סָפַר ²\">ספְרָא</a></div>","alt":[]},"19918":{"h":"ספרווה","r":"O01430","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"כרפוונה\">כרפוונה</a></div>","alt":[]},"19919":{"h":"סַפְרוּתָא","r":"O01431","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (denom. of <a href=\"#\" data-headword=\"סָפַר ²\">סַפְרָא</a>) <i>teacher’s office</i>. <span class=\"citation\">Y. Meg. IV, 75ᵇ</span> bot. <span dir=\"rtl\">שרון ליה מן ספְרוּתֵה</span> they discharged him from the teacher’s office.</div>","alt":["סַפְרוּתָה"]},"19920":{"h":"סַפִּרִינוֹן","r":"O01432","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"סַמְפִּירִינוֹן\">סַמְפִּירִינוֹן</a></div>","alt":[]},"19921":{"h":"סַפְרִיקִין","r":"O01433","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"סְפַרְקִין\">סְפַרְקִין</a></div>","alt":[]},"19922":{"h":"ספרכיתא","r":"O01434","html":"<div class=\"sense\">, <span class=\"citation\">Targ. Prov. II, 12</span> (ed. Wil. <span dir=\"rtl\">מפ׳</span>), read with ed. Lag. <a href=\"#\" data-headword=\"הֲפֵיכְתָּא\">הֲפִיכָתָא</a> or <span dir=\"rtl\">הֲפִיכְיָתָא</span>; Ms. <span dir=\"rtl\">תַּהֲפוּכְיָתָא</span>; v. <a href=\"#\" data-headword=\"הָפִיכָא\">הָפִיכָא</a>.</div>","alt":[]},"19923":{"h":"סַפְרָנָא","r":"O01435","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> = <a href=\"#\" data-headword=\"סָפַר ²\">ספְרָא</a>, <i>scribe</i>, <i>secretary</i>. <span class=\"citation\">Targ. Esth. V, 11</span>.</div>","alt":[]},"19924":{"h":"סְפַרְקִין","r":"O01436","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"> (<i>Saf.</i> of <span dir=\"rtl\">פרק</span>; cmp. <a href=\"#\" data-headword=\"*אַוְורַקְסִין\">אַוְורַקְסִין</a>) a sort of <i>trousers</i>. <span class=\"citation\">Sabb. 120ᵃ</span>; Y. ib. XVI, 15ᵈ <a href=\"#\" data-headword=\"סַבְרִיקִים\">סַבְרִיקִין</a> (<a href=\"#\" data-headword=\"בְּרַק I\">ברק</a> = <span dir=\"rtl\">פרק</span>; cmp. <span dir=\"rtl\">בקר</span> = <span dir=\"rtl\">פקר</span>). <span class=\"citation\">Kel. XXIX, 2</span> <a href=\"#\" data-headword=\"סוּבְרִיקִין\">סוּבְרִיקִין</a> (Var. <a href=\"#\" data-headword=\"סַוְורִיקִין\">סַוְורִיקִין</a>, <a href=\"#\" data-headword=\"סַפְרִיקִין\">ספְרִיקִין</a>); Sifra M’tsor‘a, Neg., Par. 7, ch. V. <a href=\"#\" data-headword=\"סַבְרִיקִים\">סַבְרִיקִים</a>.</div>","alt":[]},"19925":{"h":"סָפַת","r":"O01437","html":"<div class=\"sense\"> (cmp. <a href=\"#\" data-headword=\"סְפֵי\">סְפֵי</a>) <i>to cut, chip, slice; to take a chip, a slice</i>. <span class=\"citation\">Tosef. Sabb. XIV</span> (<span class=\"citation\">XV), 2</span> <span dir=\"rtl\">לא יִסְפּוֹת הימנה וכ׳</span> one must not take a chip of it (the broken cask) as a support to &amp;c.; <span class=\"citation\">Sabb. 124ᵇ</span> <span dir=\"rtl\">ולא יספות ממנה שבר וכ׳</span> he must not trim a fragment of it (break off its projecting points, Rashi) to cover with it &amp;c. <span class=\"citation\">Tosef. Kel. B. Mets. I, 12</span> <span dir=\"rtl\">ס׳ הימנו</span> if he cut a piece off it. Ab. Zar. 80ᵇ <span dir=\"rtl\">ס׳ לה צואה</span> if he offered to it (the idol) excrements (in the place of cakes, flesh &amp;c.); a. e.—Esp. (with or without <span dir=\"rtl\">במלח</span>) <i>to cut slices</i> (<i>of melons</i>) <i>and salt them; to make an incision in olives and salt them</i>. <span class=\"citation\">Sabb. 145ᵃ</span> <span dir=\"rtl\">המפצע … לסוֹפְתָן במלח</span> (Ar. <span dir=\"rtl\">לסופגן</span>) if one bursts olives open … with the intention of salting them. <span class=\"citation\">Maasr. II, 6</span> <span dir=\"rtl\">סוֹפֵת ואוכל</span> (Var. <span dir=\"rtl\">כופף</span>) he slices (and salts) and eats. <span class=\"citation\">Tosef. ib. II, 14</span> <span dir=\"rtl\">לא יספות במלח וכ׳</span> the laborer must not cut and salt (the fruits on which he works) and eat, unless the employer has given him permission. Y. Mass. Sh. II, 50ᵃ top <span dir=\"rtl\">אבטיח שס׳ בו וכ׳</span> a melon in which he made a cut, however small &amp;c.—[<span class=\"citation\">Midr. Till. to Ps. IV</span>, ed. Bub. <span dir=\"rtl\">לספות</span>, v. <a href=\"#\" data-headword=\"ספי\">סָפָה</a>.]</div>","alt":[]},"19926":{"h":"סִפְתָא","r":"O01438","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"סִיפְתָא\">סִיפְתָא</a></div>","alt":[]},"19927":{"h":"סַק I","r":"O01439","html":"<div class=\"sense\"> imper. of <a href=\"#\" data-headword=\"נְסַק\">נְסַק</a>.</div>","alt":[]},"19928":{"h":"סַק II","r":"O01440","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> = <a href=\"#\" data-headword=\"שַׂק\">שַׂק</a>, <i>sack</i>, <i>sackcloth</i>.—Pl. <span dir=\"rtl\">סַקִּים</span>, <span dir=\"rtl\">סַקִּין</span>. <span class=\"citation\">Tosef. Sabb. V</span> (<span class=\"citation\">VI), 13</span> (<span class=\"citation\">Sabb. 62ᵃ</span> <span dir=\"rtl\">שַׂקִּין</span>).—V. <a href=\"#\" data-headword=\"שַׂק\">שַׂק</a>.—[<span class=\"citation\">Sifré Num. 89</span> <span dir=\"rtl\">סק בקוטלא</span>, v. <a href=\"#\" data-headword=\"סְקוּטְלָא\">סְקוּטְלָא</a>.]</div>","alt":[]},"19929":{"h":"סַק","r":"O01441","html":"<div class=\"sense\"> <span class=\"citation\">Targ. Am. VIII, 10</span>. <span class=\"citation\">Targ. Ps. XXXV, 13</span>. <span class=\"citation\">Targ. O. Gen. XLII, 25</span> (Y. <a href=\"#\" data-headword=\"סָהֲדָא\">שַׂ׳</a>); a. e.—<span class=\"citation\">Lev. R. s. 36</span>; <span class=\"citation\">Ruth R. to I, 1</span>, v. <a href=\"#\" data-headword=\"סָאתָא I\"><span dir=\"rtl\">סָאתָא</span> I</a>; (Y. Snh. X, 27ᵈ <a href=\"#\" data-headword=\"סָהֲדָא\">שַׂ׳</a>). <span class=\"citation\">Sabb. 152ᵃ</span> <span dir=\"rtl\">שרי שַׂקָּיךְ וכ׳</span> untie thy bag (open thy mouth) and put in food; a. fr.—Pl. <span dir=\"rtl\">סַקִּין</span>, <span dir=\"rtl\">סַקַּיָּא</span>, <a href=\"#\" data-headword=\"סָהֲדָא\">שַׂ׳</a> <span class=\"citation\">Targ. O. Gen. XLII, 35</span> (ed. Berl. <a href=\"#\" data-headword=\"סָהֲדָא\">שַׂ׳</a>; Y. <span dir=\"rtl\">דיסקי׳</span>). <span class=\"citation\">Targ. Joel I, 13</span>; a. e.</div>","alt":["סַקָּא"]},"19930":{"h":"סַקָּאָה","r":"O01442","html":"<div class=\"sense\"> m. ch. = h. <a href=\"#\" data-headword=\"סַקָּי II\"><span dir=\"rtl\">סַקָּי</span> II</a>. <span class=\"citation\">Targ. O. Deut. XXVIII, 42</span>; quot. <span class=\"citation\">B. Kam. 116ᵇ</span></div>","alt":[]},"19931":{"h":"סַקָּאי","r":"O01443","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"סַקָּי I\">סַקָּי</a></div>","alt":[]},"19932":{"h":"סְקַב","r":"O01444","html":"<div class=\"sense\">, <i>Pa</i>. <span dir=\"rtl\">סַקֵּיב</span> (Saf. of <span dir=\"rtl\">נ־קב</span>; cmp. <a href=\"#\" data-headword=\"נָקַף I\">נקף</a> I a. <span dir=\"rtl\">נגף</span>) <i>to make sore</i>. <span class=\"citation\">B. Mets. 27ᵇ</span> [read:] <span dir=\"rtl\">לא שאילי אינשי אוכפא משום דמְסַקֵּב ליה לחמרא</span> people do not borrow a saddle, because it makes sore the ass’ back (which it does not fit; Ms. M. <span dir=\"rtl\">לא שיילי … דמְסַקֵּיב להו לחמרייהו</span> people do not lend …, for it makes their asses’ backs sore, after having been worn by a strange ass; v. Rabb. D. S. a. l. note); <span class=\"citation\">Yeb. 120ᵇ</span> <span dir=\"rtl\">לא שיולו … דמסקיב וכ׳</span> (read <span dir=\"rtl\">שיילי</span>).</div>","alt":[]},"19933":{"h":"סַקְבָּא","r":"O01445","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"סְקַב\">preced.</a>) <i>sore spot</i>. <span class=\"citation\">Kidd. 81ᵃ</span> <span dir=\"rtl\">ס׳ דשתא ריגלא</span> the sorest spot of the year (the time of the greatest danger to chastity) is the festive season (when people of all sorts congregate).</div>","alt":[]},"19934":{"h":"סַקָּבָא","r":"O01446","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"סַקְבָּנָא\">סַקְבָּנָא</a></div>","alt":[]},"19935":{"h":"סקבטרין","r":"O01447","html":"<div class=\"sense\">, <span class=\"citation\">Lev. R. s. 21</span>; Pesik. Aḥăré, p. 175ᵃ; 175ᵇ Ar., v. <a href=\"#\" data-headword=\"אֶגְסִיטֵרִין\">אֶגְסִיטֵרִין</a>.</div>","alt":[]},"19936":{"h":"סַקְבֵּל","r":"O01448","html":"<div class=\"sense\"> (<i>Saf.</i> of <span dir=\"rtl\">קבל</span>), <i>Ittaf.</i> אִסְתַּקְבֵּל <i>to come to meet</i>. <span class=\"citation\">Targ. Prov. XII, 27</span> (h. text <span dir=\"rtl\">יחרך</span>; v. Pesh.).</div>","alt":[]},"19937":{"h":"סַקְבָּנָא","r":"O01449","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"סְקַב\">סְקַב</a>) <i>sufferer from sores</i>.—Pl. <span dir=\"rtl\">סַקְבָּנֵי</span>. <span class=\"citation\">Snh. 98ᵃ</span> יתיב ביני ס׳ דרומאי Ar. ed. Koh. (some ed. <span dir=\"rtl\">סַקָּבֵי</span>; Talm. ed. … <span dir=\"rtl\">עניי סובלי חלאים</span>) he (the Messiah) is seated among the sore-stricken of the Romans.</div>","alt":[]},"19938":{"h":"סקבס","r":"O01450","html":"<div class=\"sense\"> Ar., v. <a href=\"#\" data-headword=\"סְקִיבָס\">סְקִיבָס</a></div>","alt":[]},"19939":{"h":"סְקַד","r":"O01451","html":"<div class=\"sense\">, <i>Pa</i>. <span dir=\"rtl\">סַקֵּיד</span> (<i>Saf.</i> of <a href=\"#\" data-headword=\"נָקַד I\"><span dir=\"rtl\">נ־קד</span> I</a>; interch. with <span dir=\"rtl\">סקר</span>, cmp. <a href=\"#\" data-headword=\"נָקַר I\"><span dir=\"rtl\">נקר</span> I</a>) <i>to sting, goad; to drive, train</i>. <span class=\"citation\">Targ. Y. Deut. VIII, 5</span> (some ed. <span dir=\"rtl\">מְסַקֵּר</span>; incorr. <span dir=\"rtl\">מַסְקַר</span>; h. text <span dir=\"rtl\">יסר</span>).—Pesik. Baḥod. p. 153ᵃ (ref. to <span dir=\"rtl\">מלמדך</span>, <span class=\"citation\">Is. XLVIII, 17</span>; cmp. <a href=\"#\" data-headword=\"מַלְמֵד\">מַלְמַד</a>) [read:] <span dir=\"rtl\">מְסַקֵּיד לך כמא דהדין מסאסא מסקיד להדא פרתא</span> who trains thee (through sufferings) as the goad trains the cow; [Ar. s. v. <span dir=\"rtl\">מסקיד</span>: <span dir=\"rtl\">מְסַקִּידְנָא וכ׳</span> I train thee &amp;c.]; <span class=\"citation\">Lev. R. s. 29</span>; <span class=\"citation\">Yalk. Num. 782</span>; <span class=\"citation\">Yalk. Lev. 645</span> <span dir=\"rtl\">מְסַקֵּר</span>.</div>","alt":[]},"19940":{"h":"סקווטריס","r":"O01452","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אֶגְסִיטֵרִין\">אֶגְסִיטֵרִין</a></div>","alt":["סקויטריס"]},"19941":{"h":"סַקְוַוסְתָּן","r":"O01453","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"סָקִיסְתָּן\">סְקִיסְתָּן</a></div>","alt":[]},"19942":{"h":"סְקוּטְלָא","r":"O01454","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (scutella, σκοῦτλον) = <a href=\"#\" data-headword=\"אִסְקוּטְלָא II\"><span dir=\"rtl\">אִסְקוּטְלָא</span> II</a>, <i>salver</i>, <i>tray</i>. <span class=\"citation\">Sifré Num. 89</span> <span dir=\"rtl\">כגליד … ונעשה לארץ כמין ס׳ וכ׳</span> (not <span dir=\"rtl\">סק בקוטלא</span>) first (the dew) came down like a frozen mass, and on the ground became like a tray, upon which the mannah then fell; <span class=\"citation\">Yalk. Num. 735</span> <span dir=\"rtl\">כמין אסקוטלא</span>.</div>","alt":[]},"19943":{"h":"סקוטראק","r":"O01455","html":"<div class=\"sense\">, <span class=\"citation\">Treat. Sof’rim ch. XIII, 6</span> <span dir=\"rtl\">ס׳ נטריא</span>, a corruption, v. <a href=\"#\" data-headword=\"קוּנְטְרָא\">קוּנְטְרָא</a></div>","alt":[]},"19944":{"h":"סִקּוּל","r":"O01456","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<i>Saf.</i> of <span dir=\"rtl\">קלל</span>) <i>mishap</i>, <i>accident</i>. <span class=\"citation\">Targ. Y. I Lev. X, 19</span>. <span class=\"citation\">Targ. Y. Gen. XLII, 4</span>; <span class=\"citation\">38</span> סְקַל Ar. (ed. <a href=\"#\" data-headword=\"מוֹמָתָא\">מותא</a>; Sam. <span dir=\"rtl\">אסקל</span>; h. text <a href=\"#\" data-headword=\"אָסוֹן\">אסון</a>).</div>","alt":[]},"19945":{"h":"סְקוּנְדְּרֵי","r":"O01457","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אִיסְקוּנְדְּרֵי\">אִיסְקוּנְדְּרֵי</a></div>","alt":[]},"19946":{"h":"סקוסים","r":"O01458","html":"<div class=\"sense\">, v. sub <span dir=\"rtl\">סִיק׳</span>.</div>","alt":["סקוסין"]},"19947":{"h":"סְקוֹף","r":"O01459","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"סְקוּפָה\">next w.</a>) <i>lintel</i>, <i>threshold</i>. <span class=\"citation\">Targ. Y. Num. IX, 10</span> (ed. Vien. <a href=\"#\" data-headword=\"סְקִיף\">סְקִיף</a>); <span class=\"citation\">ib. 13</span> (ed. Vien. <a href=\"#\" data-headword=\"סִיקוּף\">סִיקוּף</a>). <span class=\"citation\">Targ. Ez. IX, 3</span> Kimḥi (ed. <span dir=\"rtl\">סְקוֹפַת</span>); a. e.—Pl. <span dir=\"rtl\">סְקוֹפַיָּיא</span>. <span class=\"citation\">Targ. II Chr. III, 7</span>. <span class=\"citation\">Targ. II Kings XVIII, 16</span>; a. e.—V. <a href=\"#\" data-headword=\"סְקוּפְתָּא\">סְקוּפְתָּא</a>, a. <a href=\"#\" data-headword=\"שַׁקְפָא\">שַׁקְפָא</a>.</div>","alt":["(סִקּוּף)"]},"19948":{"h":"סְקוּפָה","r":"O01460","html":"<div class=\"sense\"> f. h. (<a href=\"#\" data-headword=\"סְקַף I\">סקף</a>, v. <a href=\"#\" data-headword=\"שָׁקַף I\"><span dir=\"rtl\">שָׁקַף</span> I</a>, a. <a href=\"#\" data-headword=\"אִסְקוּפָה\"><a href=\"#\" data-headword=\"אִסְקוּפָה\">אִסְקוּפָה</a>)</a> same. <span class=\"citation\">Lev. R. s. 34</span> <span dir=\"rtl\">כמין ס׳ התחתונה</span> like the lowest door-sill.</div>","alt":[]},"19949":{"h":"סקופוטי","r":"O01461","html":"<div class=\"sense\">, Pesik. Baḥod., p. 103ᵃ, v. <a href=\"#\" data-headword=\"אִסְקְפַסְטִי\">אִסְקְפַסְטִי</a></div>","alt":[]},"19950":{"h":"סְקוּפְתָּא","r":"O01462","html":"<div class=\"sense\"> = h. <a href=\"#\" data-headword=\"סְקוּפָה\">סְקוּפָה</a>. <span class=\"citation\">Targ. I Sam. V, 4</span> (ed. Lag. <a href=\"#\" data-headword=\"אִיסְקוּנְדְּרֵי\">אִיסְק׳</a>). <span class=\"citation\">Ib. 5</span> <a href=\"#\" data-headword=\"סְקוּפָה\">סְקוּפַת</a> constr. (ed. Lag. <span dir=\"rtl\">איסק׳</span>). <span class=\"citation\">Targ. Ez. IX, 3</span> (v. <a href=\"#\" data-headword=\"סְקוֹף\">סְקוֹף</a>). <span class=\"citation\">Ib. XLI, 25</span> (h. text <a href=\"#\" data-headword=\"עָב I\">עב</a>); a. fr.—Pl. <a href=\"#\" data-headword=\"סְקוּפְתָּא\">סְקוּפָתָא</a> <span class=\"citation\">Ib. 36</span> (ed. Lag. <span dir=\"rtl\">סְקוֹפַיָּא</span>; some ed. <a href=\"#\" data-headword=\"סַקֵּיפְתָּא\">סַקִּיפְתָּא</a>, corr. acc.; h. text <span dir=\"rtl\">עבים</span>).</div>","alt":[]},"19951":{"h":"סקורדקין","r":"O01463","html":"<div class=\"sense\">, <span class=\"citation\">Gen. R. s. 45</span> Ar., v. <a href=\"#\" data-headword=\"קוּרְדְּקִין\">קוֹרדְּקִין</a></div>","alt":[]},"19952":{"h":"סְקוֹרְטְיָא","r":"O01464","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (scortea, sub. vestis; v. <a href=\"#\" data-headword=\"אִיסְקוֹרטְיָא\">אִיסְקוֹרְטְיָא</a>) <i>leather coat;also leather apron.</i> <span class=\"citation\">Kel. XVI, 4</span> (Maim. <i>leather table-cover</i>, v. <a href=\"#\" data-headword=\"צִיצָה\">צִיצָה</a>). Ib. XXVI, 5 (6) <span dir=\"rtl\">עור ס׳</span> the skin intended for a <i>scortea.</i> Ohol. VIII, 1 ס׳ <i>a leather bed-sheet</i>. <span class=\"citation\">Tosef. Sabb. V (VI), 14. Ned. 5</span>5ᵇ, [read as:] Y. ib. VII, end, 40ᶜ; <span class=\"citation\">Tosef. ib. IV, 3</span><span class=\"citation\">Ned. 55ᵇ</span>, [read as:] Y. ib. VII, end, 40ᶜ; <span class=\"citation\">Tosef. ib. IV, 3</span> <span dir=\"rtl\">איסק׳</span>; a. e. [Ned. l. c. <span dir=\"rtl\">מאי איסק׳ כיתונא דצלא</span> <i>scortea</i> is a leather coat.]</div>","alt":["סְקוֹרְטְיָה"]},"19953":{"h":"*סָקוֹת","r":"O01465","html":"<p class=\"morphology\">f. pl.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"נָסַק\">נָסַק</a>) <i>fire-brands</i>. Tanḥ. <span class=\"citation\">Mishp. 18</span> <span dir=\"rtl\">היו … כמו ס׳ מכבשן האש</span> their faces became black like brands out of a furnace.</div>","alt":[]},"19954":{"h":"סַקָּי I","r":"O01466","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (denom. of <a href=\"#\" data-headword=\"סַק\">סַק</a>) <i>sack-maker; sack-carrier.</i>—Pl. <span dir=\"rtl\">סַקָּיִין</span>, <span dir=\"rtl\">סַקָּאִין</span>. <span class=\"citation\">Kel. XIII, 5</span> <span dir=\"rtl\">(<span dir=\"rtl\">מחט</span>) <span dir=\"rtl\">של ס׳</span></span> the sack-makers’ needle. <span class=\"citation\">Tosef. Kel. B. Mets. VII, 1</span>; <span class=\"citation\">Bekh. 22ᵃ</span> <span dir=\"rtl\">כפיקה גדולה של ס׳</span> of the size of a large stopper (seal) of the sack-carriers; a. e.</div>","alt":[]},"19955":{"h":"סַקָּי II","r":"O01467","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"סַקָּי I\">preced.</a>) name of a <i>locust</i> or a <i>beetle</i> (<i>sack-carrier</i>), supposed to be the <i>cricket</i>. <span class=\"citation\">Sifré Deut. 42</span> <span dir=\"rtl\">מעלה ס׳</span> (some ed. <a href=\"#\" data-headword=\"סַקָּאי\">סַקָּאי</a>) (the late rain) brings the cricket.—Pl. <span dir=\"rtl\">סַקָּיִּין</span>, <span dir=\"rtl\">סַקָּאִין</span>. <span class=\"citation\">Taan. 6ᵃ</span>; <span class=\"citation\">Yalk. Deut. 863</span>.</div>","alt":[]},"19956":{"h":"סְקִיבָס","r":"O01468","html":"<div class=\"sense\"> m., v. <a href=\"#\" data-headword=\"סְטִיבָס\">סְטִיבָס</a></div>","alt":[]},"19957":{"h":"סקיווי","r":"O01469","html":"<div class=\"sense\">, <span class=\"citation\">Koh. R. to IX, 18</span> <span dir=\"rtl\">ס׳ פטריי</span> ed., Mus. <a href=\"#\" data-headword=\"*סִקְרִיפְטוֹר\">סִקְרִיפְטוֹר</a> q. v.</div>","alt":[]},"19958":{"h":"סקילא","r":"O01470","html":"<div class=\"sense\">, read <span dir=\"rtl\">סְקָלָא</span> (scala) <i>a ship’s ladder</i>. <span class=\"citation\">Tosef. Sabb. XIII</span> (<span class=\"citation\">XIV), 11</span> <span dir=\"rtl\">עשה ס׳ וירד בו</span> (read <a href=\"#\" data-headword=\"בָּהוּ\">בָּהּ</a>) a gentile made (threw out) a ladder and went down on it; [ed. Zuck. <a href=\"#\" data-headword=\"כֵּבַשׁ I\">כבש</a>; v. <span class=\"citation\">Sabb. XVI, 8</span>].</div>","alt":["סיקלא"]},"19959":{"h":"סְקִילָה","r":"O01471","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (<a href=\"#\" data-headword=\"סָקַל\">סָקַל</a>) <i>stoning, execution by stoning</i>. <span class=\"citation\">Snh. VII, 1</span>. <span class=\"citation\">Ib. 9</span> <span dir=\"rtl\">בס׳</span> (sub. <a href=\"#\" data-headword=\"דִּין I\">נידון</a>) is to be put to death by stoning. <span class=\"citation\">Ib. IX, 3</span> <span dir=\"rtl\">נידונין בס׳</span>. Ib. <span dir=\"rtl\">הס׳ חמורה</span> stoning is the severer punishment; a. v. fr.—<span dir=\"rtl\">בית הס׳</span> the place of stoning, a scaffolding from which the culprit was thrown down. Ib. VI, 1. Ib. 4 <span dir=\"rtl\">בית הס׳ היה וכ׳</span> the scaffolding was two (men’s) statures high; a. e.</div>","alt":[]},"19960":{"h":"סקילוס","r":"O01472","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"סְלִיקְיָא\">סְלִיקְיָא</a></div>","alt":[]},"19961":{"h":"*סְקִימְיוֹן","r":"O01473","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (a corrupt. of <i>xenium</i>) <i>a host’s</i> or <i>king’s gift, donation indefinite as to time and amount</i>. <span class=\"citation\">Taan. 19ᵇ</span> מיום שחרב … נעשו הגשמים ס׳ וכ׳ Ar. (ed. <span dir=\"rtl\">צימוקין</span>; Ms. M. <span dir=\"rtl\">צומוקין</span>, Rashi ed. Pes. <span dir=\"rtl\">צומוקיון</span>, substitutes for the unintelligible <a href=\"#\" data-headword=\"ס׳\">ס׳</a>) since the destruction of the Temple the rains have become irregular and arbitrary gifts, in some years rains are abundant, in others, scanty; in some years rains are in season &amp;c. [Compare the simile: <span dir=\"rtl\">לעבד שנתן לו רבו פרנסתו</span>.]</div>","alt":[]},"19962":{"h":"סקיסאות","r":"O01474","html":"<div class=\"sense\">, <span class=\"citation\">Yalk. Num. 713</span>, read: <span dir=\"rtl\">סְקִיפַסְטָאוֹת</span>, v. <a href=\"#\" data-headword=\"אִסְקְפַסְטִי\">אִסְקְפַסְטִי</a></div>","alt":[]},"19963":{"h":"סָקִיסְתָּן","r":"O01475","html":"<p class=\"morphology\">pr. n.</p><div class=\"sense\"> (Σακαστηνή) <i>Saḳistan</i> (Segestan), a district of Drangiana in the Persian empire, occupied by the Sacæ or Scythians. <span class=\"citation\">Yoma 10ᵃ</span> (ref. to <span dir=\"rtl\">סבתה … וסבתכא</span>, <span class=\"citation\">Gen. X, 7</span>) <span dir=\"rtl\">ס׳ גוייתא וס׳ ברייתא וכ׳</span> Ms. M. 2 <span dir=\"rtl\">סָגִיסְתָּאן</span>, v. Rabb. D. S. a. l. note 9; Ar. <a href=\"#\" data-headword=\"סַקְוַוסְתָּן\">סַקְוַוסְתָּן</a></div>","alt":[]},"19964":{"h":"סְקִיף","r":"O01476","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"סְקוֹף\">סְקוֹף</a></div>","alt":[]},"19965":{"h":"סְקִיפְטוֹרִין","r":"O01477","html":"<p class=\"morphology\">m. pl.</p><div class=\"sense\"> (exceptores) <i>short-hand writers, clerks in court</i>. Pesik. Haḥod., p. 53ᵇ sq. [read:] <span dir=\"rtl\">העמידו סניגורין ויעמדו ס׳</span> summon the advocates and let the clerks be ready; ib. <span dir=\"rtl\">העבירו … ויעברו ס׳</span> dismiss the advocates and let the clerks go; <span class=\"citation\">Yalk. Ex. 190</span> <a href=\"#\" data-headword=\"ספיקטורין\">ספיקטורין</a>; <span class=\"citation\">Yalk. Ps. 831</span> <span dir=\"rtl\">ספיקטרין</span>, <span dir=\"rtl\">ספיקטו׳</span> (corr. acc.); (<span class=\"citation\">Y. R. Hash. I, 57ᵇ</span> top <span dir=\"rtl\">קטיגורין</span>).</div>","alt":[]},"19966":{"h":"סקיפטיות","r":"O01478","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אִסְקְפַסְטִי\">אִסְקְפַסְטִי</a></div>","alt":[]},"19967":{"h":"סקיפנטום","r":"O01479","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"סְקִיפַנְטְיָא\">next w.</a></div>","alt":[]},"19968":{"h":"סְקִיפַנְטְיָא","r":"O01480","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (συκοφαντία) <i>false accusation</i>. <span class=\"citation\">Sifré Deut. 349</span> (ref. to <span dir=\"rtl\">תריבהו</span>, <span class=\"citation\">Deut. XXXIII, 8</span>) <span dir=\"rtl\">ס׳ נסתקפה לו וכ׳</span> (ed. Fr.) false denunciation turned against him (Aaron); if Moses said …, what have Aaron and Miriam done?; (oth. ed. <span dir=\"rtl\">סקיפנטום נסתקפת</span>, read: <span dir=\"rtl\">סְקִיפַנְטֵיס</span> (συκοφάντης) <i>an informer</i>, v. <a href=\"#\" data-headword=\"סָקַף\">סָקַף</a>); [<span class=\"citation\">Yalk. Deut. 954</span> <span dir=\"rtl\">תסקופים נסתקפת</span> (ed. Lemb. <span dir=\"rtl\">תשק׳</span>); Naḥm. to Deut. l. c. <span dir=\"rtl\">סקופים נסתקפו לו</span>, v. <a href=\"#\" data-headword=\"סָקַף\">סָקַף</a> a. <a href=\"#\" data-headword=\"תַּסְקוּפִים\">תַּסקוּפִים</a>].</div>","alt":[]},"19969":{"h":"סְקִיפַס","r":"O01481","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (denom. of <a href=\"#\" data-headword=\"סְקִיף\">סְקִיף</a> or <a href=\"#\" data-headword=\"שְׁקוֹף\">שְׁקוֹף</a>) <i>one whose occiput has the shape of a lintel</i> (having an angular projection). <span class=\"citation\">Bekh. VII, 1</span> (<span class=\"citation\">43ᵃ</span>) (Mish. a. Ar. <a href=\"#\" data-headword=\"ש׳\">ש׳</a>). Ib. 43ᵇ ס׳ מאחוריו וכ׳ <i>s’ḳifas</i> refers to the hinder part of the head, as people say <span dir=\"rtl\">ש̇ק̇יל פ̇יס̇א</span>, a piece is taken off.</div>","alt":["שְׁקִי׳"]},"19970":{"h":"סְקִיפַּסְטִי","r":"O01482","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"אִסְקְפַסְטִי\">אִסְקְפַסְטִי</a></div>","alt":[]},"19971":{"h":"סַקֵּיפְתָּא","r":"O01483","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"סְקוּפְתָּא\">סְקוּפְתָּא</a></div>","alt":[]},"19972":{"h":"סְקִירָה","r":"O01484","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (סָקַר II) <i>look</i>, <i>glance</i>. <span class=\"citation\">R. Hash. 18ᵃ</span>, v. <a href=\"#\" data-headword=\"סָקַר II\"><span dir=\"rtl\">סָקַר</span> II</a>.</div>","alt":[]},"19973":{"h":"סָקַל","r":"O01485","html":"<div class=\"sense\"> (b. h.) <i>to stone, put to death by stoning</i>. <span class=\"citation\">Snh. VI, 1</span> (<span class=\"citation\">42ᵇ</span>); <span dir=\"rtl\">מוציאין אותו לסוֹקְלוֹ</span> (Mish. ed. <span dir=\"rtl\">לסָקְלוֹ</span>) they take him out (from the court) to execute him. Ib. 46ᵃ <span dir=\"rtl\">וסְקָלוּהוּ</span> and they condemned him to be stoned; a. fr.—<span class=\"citation\">Tosef. Sabb. VI</span> (<span class=\"citation\">VII), 5</span> <span dir=\"rtl\">האומר סִקְלוּ תרנגול זה וכ׳</span> (not <a href=\"#\" data-headword=\"תַּרְנְגוֹלֶת\">תרנגולת</a>) ed. Zuck. (Var. <span dir=\"rtl\">שחטו</span>) if one says, stone this cock, for he crowed at evening,—that is a superstitious practice (v. <a href=\"#\" data-headword=\"אֱמוֹרִי\">אֱמוֹרִי</a>).</div><div class=\"sense\"><b>Nif. נִסְקַל</b> <div class=\"sense\"><i>to be stoned, be condemned to death by stoning</i>. <span class=\"citation\">Snh. 43ᵃ</span> <span dir=\"rtl\">אבן שנ׳ בה</span> the stone with which the culprit is to be put to death. <span class=\"citation\">Ib. VI, 1</span> <span dir=\"rtl\">יוצא לִיסָּקֵל</span> is taken out to be stoned. <span class=\"citation\">Ib. 3</span> <span dir=\"rtl\">האיש נ׳ ערום ואין האשה נִסְקֶלֶת וכ׳</span> the male convict is put to death undressed, but not so the woman. <span class=\"citation\">Ib. 4</span> <span dir=\"rtl\">כל הנִסְקָלִין נתלין</span> all those executed by stoning are afterwards hanged; a. fr.—<span dir=\"rtl\">שור הנִסְקָל</span> the ox that is to be, or has been put to death by stoning, having killed a human being (<span class=\"citation\">Ex. XXI, 28</span>). Ib. I, 4 <span dir=\"rtl\">שור הנ׳ וכ׳</span> the case of an ox to be stoned is argued before a court of twenty-three. Mekh. Misp., Nziḳin, s. 10; a. fr.</div></div><div class=\"sense\"><b>Pi. סִיקֵּל</b> <div class=\"sense\"><i>to clear of stones.</i> <span class=\"citation\">Shebi. II, 3</span> <span dir=\"rtl\">מְסַקְּלִין עד וכ׳</span> you may clear fields of stones (in the sixth year) up to the beginning of the Sabbatical year. <span class=\"citation\">Tosef. B. Kam. II, 12</span> <span dir=\"rtl\">כדרך … לא יְסַקֵּל ואם סי׳ וכ׳</span> as one has no right to put dung on the public road, so one must not clear his field and deposit the stones on the road, and if he does clear it, he must carry the stones to &amp;c. <span class=\"citation\">Ib. 13</span> (to one who deposited stones on the road) <span dir=\"rtl\">מפני מה אתה מְסַקֵּל מתוך וכ׳</span> why dost thou remove the stones from a place which is not thine to a place which is thine?; a. fr.</div></div>","alt":[]},"19974":{"h":"סְקַל I","r":"O01486","html":"<div class=\"sense\"> <span class=\"citation\">B. Kam. 41ᵃ</span> <span dir=\"rtl\">היכא דסַקְלֵיה מִסְקַל</span> after one has stoned him (the ox).</div>","alt":[]},"19975":{"h":"סְקַל II","r":"O01487","html":"<div class=\"sense\"> m., v. <a href=\"#\" data-headword=\"סִקּוּל\">סִקּוּל</a></div>","alt":[]},"19976":{"h":"*סַקְלוּנְקִית","r":"O01488","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (= <span dir=\"rtl\">סקלוקית</span>, reduplic. of <a href=\"#\" data-headword=\"סָקַל\">סקל</a>) <i>a hard blow with the fist</i>. Y. B. Kam. VIII, end, 6ᶜ, v. <a href=\"#\" data-headword=\"סִנּוֹקֶרֶת\">סִנּוֹקֶרֶת</a>.</div>","alt":[]},"19977":{"h":"*סקליטין","r":"O01489","html":"<div class=\"sense\">, Midr. Hashkem, Vayaḳhel, quot. in Ar. and expl. as <i>court</i> or <i>palace</i>, prob. meant for <span dir=\"rtl\">סִיקְרִיטוֹן</span> (secretum) <i>secluded place</i>; v. Koh. Ar. Compl. s. v.</div>","alt":[]},"19978":{"h":"סקנדרוס","r":"O01490","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"סִנְקַתִּדְרוֹס\">סִנְקתִּדְרוֹס</a></div>","alt":[]},"19979":{"h":"סַקְסְנָאָה","r":"O01491","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> of <i>Sacassana</i> (Σακασσήνη), a province of Armenia. <span class=\"citation\">Nidd. 65ᵃ</span> מנימין ס׳ Miniamin of S., v. <a href=\"#\" data-headword=\"*גִּנְזַכָּיָיה\">גִּנְזַכָּיָיה</a>.</div>","alt":[]},"19980":{"h":"סָקַף","r":"O01492","html":"<div class=\"sense\"> (Saf. of <a href=\"#\" data-headword=\"נָקַף I\">נ־קף</a>, v. <a href=\"#\" data-headword=\"נָקַף II\"><span dir=\"rtl\">נָקַף</span> II</a>) <i>to go around</i>.</div><div class=\"sense\"><b>Hithpa. הִסְתַּקֵּף</b> </div><div class=\"sense\"><b>Nithpa. נִסְתַּקֵּף</b> <div class=\"sense\"><b>1)</b> <i>to come in turn; to be arranged; to happen</i> (cmp. <a href=\"#\" data-headword=\"סִבָּה\">סִבָּה</a>); </div><div class=\"sense\"><b>2)</b>  (of persons) <i>to turn around;</i> (= <a href=\"#\" data-headword=\"הָפַךְ\">נהפך</a>) <i>to change</i>. <span class=\"citation\">Sifré Deut. 349</span> ed. Fr. <span dir=\"rtl\">נִסְתַּקְּפָה</span>, v. <a href=\"#\" data-headword=\"סְקִיפַנְטְיָא\">סְקִיפַנְטְיָא</a>; ed. Radwill a. oth. <span dir=\"rtl\">סקפנטיס נִיסְתַּקַּפְתָּ לו</span> (not <span dir=\"rtl\">טום …</span>) thou hast turned informer against him; <span class=\"citation\">Yalk. Deut. 954</span> <span dir=\"rtl\">תסקופים ניסתקפת לו</span> (some ed. <span dir=\"rtl\">תשק׳</span>, read <span dir=\"rtl\">נִיסתַּקְּפוּ</span>), v. <a href=\"#\" data-headword=\"תַּסְקוּפִים\">תּסְקוּפִים</a>.</div></div>","alt":[]},"19981":{"h":"סְקַף I","r":"O01493","html":"<div class=\"sense\"><b>Pa. סַקֵּף</b> <div class=\"sense\"><i>to turn over, transfer</i>. <span class=\"citation\">Targ. I Chr. X, 14</span> (h. text <span dir=\"rtl\">ויסב</span>).</div></div><div class=\"sense\"><b>Ithpa. אִסְתַּקַּף</b> </div><div class=\"sense\"><b>Ithpe. אִסְתְּקַף</b> <div class=\"sense\"><b>1)</b> <i>to be turned; to pass over</i>. <span class=\"citation\">Targ. Y. Num. XXXVI, 7</span> <span dir=\"rtl\">תיתקף</span> (read <span dir=\"rtl\">תִיסְתְּקַף</span>; h. text <span dir=\"rtl\">תִסֹּב</span>, v. supra).</div><div class=\"sense\"><b>—2)</b> <i>to be brought about; to happen</i>. <span class=\"citation\">Targ. Y. Gen. XLV, 8</span>. <span class=\"citation\">Targ. Y. Num. V, 15</span>. <span class=\"citation\">Targ. Esth. VII, 7</span>; a. e.</div><div class=\"sense\"><b>—3)</b> <i>to be visited with</i>. <span class=\"citation\">Targ. O. Num. XI, 1</span> <span dir=\"rtl\">כד מִסְתַּקְּפִין ביש</span> as though an evil (mourning) had befallen them (h. text <span dir=\"rtl\">מתאננים</span>, v. <a href=\"#\" data-headword=\"אוֹנֵן\">אוֹנָן</a>).</div><div class=\"sense\"><b>—4)</b> <i>to be the cause of</i>. Targ. Y. ib. IV, 18. <span class=\"citation\">Targ. Koh. IV, 12</span>. <span class=\"citation\">Ib. 16</span> ed. Lag. (oth. ed. <span dir=\"rtl\">לאסתפקא</span>, corr. acc.); a. e.</div><div class=\"sense\"><b>—5)</b> <i>to turn against, seek occasion</i> (v. <a href=\"#\" data-headword=\"עלי\">עִילָּה</a>). <span class=\"citation\">Targ. Lam. I, 22</span> (h. text <a href=\"#\" data-headword=\"עוֹלָל\">עולל</a>). <span class=\"citation\">Targ. O. Gen. XLIII, 18</span> (h. text <span dir=\"rtl\">התגולל</span>; v. <a href=\"#\" data-headword=\"עֲקַף\">עֲקַף</a>).</div></div>","alt":[]},"19982":{"h":"סְקַף II","r":"O01494","html":"<div class=\"sense\"> (<i>Saf.</i> of <a href=\"#\" data-headword=\"נָקַף I\">נ־קף</a>, v. <a href=\"#\" data-headword=\"נָקַף I\"><span dir=\"rtl\">נקף</span> I</a>) <i>to bring close together, knock, clap</i>. <span class=\"citation\">Targ. O. Num. XXIV, 10</span> ed. Lsb. (ed. Berl. a. oth. <span dir=\"rtl\">שקפ׳</span>; Ms. I <span dir=\"rtl\">שפק׳</span>).</div><div class=\"sense\"><b>Pa. סַקֵּיף</b> <div class=\"sense\"> <a href=\"#\" data-headword=\"סְקַף I\">same</a>. <span class=\"citation\">Targ. Job XXVII, 23</span> Ms. (ed. <span dir=\"rtl\">ישקוף</span>; ed. Lag. a. oth. <span dir=\"rtl\">ישפיק</span>).—V. <a href=\"#\" data-headword=\"שְׁקַף\">שְׁקַף</a></div></div>","alt":["(שְׁקַף)"]},"19983":{"h":"סְקִפְטוֹרִין","r":"O01495","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"סְקִיפְטוֹרִין\">סְקִיפְטוֹרִין</a></div>","alt":[]},"19984":{"h":"סָקַר I","r":"O01496","html":"<div class=\"sense\"> (v. <a href=\"#\" data-headword=\"זָקַר\">זָקַר</a>) <i>to thrust</i>.</div><div class=\"sense\"><b>Nif. נִסְקַר</b> <div class=\"sense\"><i>to stagger</i>. <span class=\"citation\">Cant. R. to III, 6</span> <span dir=\"rtl\">נִסְקָרִין וכ׳</span>, v. <a href=\"#\" data-headword=\"בַּת II\"><span dir=\"rtl\">בַּת</span> II</a>.—[<span class=\"citation\">R. Hash. 18ᵃ</span>, v. next w.]</div></div>","alt":[]},"19985":{"h":"סָקַר II","r":"O01497","html":"<div class=\"sense\"> [<i>to blink, shine</i>; denom. <a href=\"#\" data-headword=\"סִיקְרָא I\">סִיקְרָא</a>] </div><div class=\"sense\"><b>1)</b> <i>to look, gaze</i>. <span class=\"citation\">Y. Nidd. III, 50ᶜ</span> bot. <span dir=\"rtl\">סוֹקְרִין לפניהן כאדם</span> they look forward (have their eyes in front of the head) like human beings (v. Bab. <span class=\"citation\">Nidd. 23ᵃ</span>).</div><div class=\"sense\"><b>—2)</b>  (denom. of <a href=\"#\" data-headword=\"סִיקְרָא I\">סִיקְרָא</a>) <i>to paint red, mark with siḳra</i>. <span class=\"citation\">Bekh. IX, 7</span> (<span class=\"citation\">58ᵇ</span>) <span dir=\"rtl\">היוצא … סוֹקְרוֹ בסיקרא</span> (Talm. ed. <span dir=\"rtl\">סוֹקֵר</span>) he marks every tenth lamb that goes forth; ib. <span dir=\"rtl\">לא סְקָרוֹ וכ׳</span> (Talm. ed. <span dir=\"rtl\">סוקרו</span>) if he failed to mark it. <span class=\"citation\">Sabb. 67ᵃ</span> <span dir=\"rtl\">סוקרו בסיקרא</span> (v. Rabb. D. S. a. l. note 50); <span class=\"citation\">Ḥull. 77ᵇ</span>; a. e.</div><div class=\"sense\"><b>Pi. סִיקֵּר</b> <div class=\"sense\"><i>to paint</i> (the eyes). Pesik. Vattom. p. 132ᵃ (ref. to <span class=\"citation\">Is. III, 16</span>) <span dir=\"rtl\">שהיו מְסַקְּרוֹת וכ׳</span> Ar. (ed. <span dir=\"rtl\">סוֹקְרוֹת</span>) they painted their eyes with <i>siḳra</i>; <span class=\"citation\">Lam. R. to IV, 15</span> <span dir=\"rtl\">מְשַׂקְּרוֹת</span>; <span class=\"citation\">Lev. R. s. 16</span>; <span class=\"citation\">Yalk. Lam. 1030</span> <span dir=\"rtl\">מְשַׂקֶּרֶת עיניה וכ׳</span> (not <span dir=\"rtl\">משקרות</span></div></div><div class=\"sense\"><b>Nif. נִסְקַר</b> <div class=\"sense\"><i>to be overlooked, reviewed</i>. <span class=\"citation\">R. Hash. 18ᵃ</span> <span dir=\"rtl\">כולן נִסְקָרִין בסקירה אחת</span> they are all reviewed with one glance; v. <a href=\"#\" data-headword=\"זָקַר\">זָקַר</a>.</div></div>","alt":[]},"19986":{"h":"סְקַר I","r":"O01498","html":"<div class=\"sense\">, <i>to look at</i>. <span class=\"citation\">Targ. Job XX, 9</span>; <span class=\"citation\">XXVIII, 7</span> (h. text <span dir=\"rtl\">שזִפתו</span>).—(With <a href=\"#\" data-headword=\"ב\">ב</a>) <span class=\"citation\">Lev. R. s. 22</span> <span dir=\"rtl\">ס׳ בההוא חויא</span> he looked at the (dead) serpent; <span class=\"citation\">Gen. R. s. 10</span> <span dir=\"rtl\">קַם למִסְקַר וכ׳</span>. <span class=\"citation\">Koh. R. to XI, 9</span> <span dir=\"rtl\">לחבושי לית את ס׳</span>, v. <a href=\"#\" data-headword=\"חֲבוּשָׁא\">חֲבוּשָׁא</a>.</div>","alt":[]},"19987":{"h":"סְקַר II","r":"O01499","html":"<div class=\"sense\">, <i>Pa</i>. <span dir=\"rtl\">סַקֵּר</span> <i>to sting, goad</i>, v. <a href=\"#\" data-headword=\"סְקַד\">סְקַד</a>.</div>","alt":[]},"19988":{"h":"סִקְרָא","r":"O01500","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"סִיקְרָא I\">סִיקְרָא</a></div>","alt":[]},"19989":{"h":"סקרדין","r":"O01501","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"סַקְרָרִין\">סַקְרָרִין</a></div>","alt":[]},"19990":{"h":"*סִקְרִיפְטוֹר","r":"O01502","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (scriptor) <i>scribe</i>, <i>secretary</i>. <span class=\"citation\">Koh. R. to IX, 18</span> (ref. to <span dir=\"rtl\">הספר</span>, <span class=\"citation\">II Kings XVIII, 37</span>) <a href=\"#\" data-headword=\"ס׳\">ס׳</a> Mus. (ed. <span dir=\"rtl\">סקיווי פטריי</span>). [The entire passage seems to be a corrupt gloss; v. <a href=\"#\" data-headword=\"*ספקלי\">ספקלי</a>, a. <a href=\"#\" data-headword=\"סַכְיָא\">סַכְיָא</a>.]</div>","alt":[]},"19991":{"h":"סקרידין","r":"O01503","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"סַקְרָרִין\">סקְרָרִין</a></div>","alt":["סקרירין"]},"19992":{"h":"סַקְרָנִית","r":"O01504","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (סָקַר II) <i>looking around, coquettish</i>. <span class=\"citation\">Gen. R. s. 18</span> Eve was not made of Adam’s eye <span dir=\"rtl\">שלא תהא ס׳</span> (Ar. <a href=\"#\" data-headword=\"סוּטְרָא\">סוֹ׳</a>) that she might not be a coquette; <span dir=\"rtl\">והרי היא ס׳</span> and yet she (woman) is coquettish; Yalk. ib. 24 (not <span dir=\"rtl\">נות …</span>, <span dir=\"rtl\">ניות …</span>); <span class=\"citation\">Yalk. Is. 265</span>; Tanḥ. Vayesh. 6.</div>","alt":[]},"19993":{"h":"סַקְרָרִין","r":"O01505","html":"<p class=\"morphology\">m.</p><div class=\"sense\"> (sacrarium) <i>shrine</i> in a temple or in a house. <span class=\"citation\">Gen. R. s. 89</span> <span dir=\"rtl\">שכך מוכתב בס׳ וכ׳</span> (ed. <a href=\"#\" data-headword=\"סקרידין\">סקרידין</a>, <a href=\"#\" data-headword=\"סקרידין\">סקרירין</a>) for thus is it recorded in the <i>aerarium</i> of the Pharaoh that a slave cannot obtain an office &amp;c. (v. Sm. Ant. s. v. Aerarium); <span class=\"citation\">Yalk. ib. 147</span> <span dir=\"rtl\">בסיקררין שלהם</span>; (Tanḥ. Mick. 3 <span dir=\"rtl\">בספריו</span>).</div>","alt":[]},"19994":{"h":"סְקַרְתָּא","r":"O01506","html":"<p class=\"morphology\">f.</p><div class=\"sense\"> (v. <a href=\"#\" data-headword=\"סָקַר II\"><span dir=\"rtl\">סָקַר</span> II</a>) <i>red paint</i>. <span class=\"citation\">Gitt. 19ᵃ</span> (expl. <a href=\"#\" data-headword=\"סִיקְרָא I\">סיקרא</a>) <span dir=\"rtl\">ס׳ שמה</span> its name is <i>s’ḳarta</i>.—Esp. <i>marking with siḳra</i>. <span class=\"citation\">Bekh. 58ᵃ</span> <span dir=\"rtl\">אי אפשר … משום ס׳</span> you cannot tithe sheep on the Holy Day on account of the required marking with paint; <span class=\"citation\">Ḥag. 8ᵃ</span>. <span class=\"citation\">Naz. 39ᵃ</span> <span dir=\"rtl\">תא שמע מס׳ וכ׳</span> come, learn it (that the hair grows from the root) from the mark on sheep, where you can see that the wool beneath is loose (while that on top is matted).</div>","alt":[]},"19995":{"h":"סַר","r":"O01507","html":"<div class=\"sense\"> = <a href=\"#\" data-headword=\"עֲסַר\">עֲסַר</a>, <i>ten</i>, v. <a href=\"#\" data-headword=\"חַדְסַר\">חַדְסַר</a>.</div>","alt":[]},"19996":{"h":"סָר","r":"O01508","html":"<p class=\"morphology\">m.</p><div class=\"sense\"><i>one whom courage has left, low-spirited</i> (v. <span class=\"citation\">I Kings XXI, 5</span>). <span class=\"citation\">Ex. R. s. 2</span> (ref. to <a href=\"#\" data-headword=\"סָר\">סָר</a>, <span class=\"citation\">Ex. III, 4</span>) <span dir=\"rtl\">סד וזעף הוא זה וכ׳</span></div>","alt":[]},"19997":{"h":"סָר ²","r":"O01509","html":"<div class=\"sense\"> pr. n., v. <a href=\"#\" data-headword=\"*אָפִיס\">אָפִיס</a></div>","alt":["סָר אָפִיס"]},"19998":{"h":"סְרָא","r":"O01510","html":"<div class=\"sense\">, v. <a href=\"#\" data-headword=\"סְרֵי II\"><span dir=\"rtl\">סְרֵי</span> II</a></div>","alt":[]},"19999":{"h":"סָרַב","r":"O01511","html":"<div class=\"sense\">, <i>Pi.</i> <span dir=\"rtl\">סֵירֵב</span> (<i>Saf.</i> of <a href=\"#\" data-headword=\"רַב\">רָב</a>) </div><div class=\"sense\"><b>1)</b> <i>to assume importance, to allow one’s self to be coaxed; to decline an office</i>. <span class=\"citation\">Pes. 86ᵇ</span> <span dir=\"rtl\">מְסָרְבִין לקטן וכ׳</span> you may decline an offer from an inferior person than yourself, but not &amp;c. <span class=\"citation\">Ber. 34ᵃ</span> … <span dir=\"rtl\">העובר צריך לסָרֵב</span> he who is asked to say the prayers, must first decline (wait to be asked again); <span dir=\"rtl\">ואם אינו מְסָרֵב וכ׳</span> and if he does not decline, he is like a dish without salt; <span dir=\"rtl\">ואם מסרב יותר מדאי וכ׳</span> but if he allows himself to be coaxed more than proper &amp;c. Ib. <span dir=\"rtl\">פעם ראשונה יְסָרֵב וכ׳</span> when asked for the first time, he must decline, the second time &amp;c., v. <a href=\"#\" data-headword=\"הִבְהֵב I\">הִבְהֵב</a>; Y. ib. V, 9ᶜ bot. <span dir=\"rtl\">בתחלה מסרב וכ׳</span>.</div><div class=\"sense\"><b>—2)</b>  (with <a href=\"#\" data-headword=\"ב\">ב</a>; v. <a href=\"#\" data-headword=\"סִרְהֵב\">סִרְהֵב</a>) [<i>to be imperious</i>,] <i>to press, urge</i>. <span class=\"citation\">Y. Dem. IV, 24ᵃ</span> bot. <span dir=\"rtl\">לא יְסָרֵב וכ׳</span> one must not urge his neighbor to be his guest, when he knows that he will not accept; <span class=\"citation\">Tosef. B. Kam. VII, 8</span> <span dir=\"rtl\">המְסָרֵב בחבירו וכ׳</span> he who urges his neighbor to be his guest, when in his heart he does not mean to invite him; <span class=\"citation\">Y. Ab. Zar. I, 39ᶜ</span> bot.; <span class=\"citation\">Tosef. B. Bath. VI, 14</span>; <span class=\"citation\">Treat. Der. Er. ch. VIII</span>; (<span class=\"citation\">Ḥull. 94ᵃ</span> <span dir=\"rtl\">יסרהב</span>). <span class=\"citation\">Tosef. Ned. IV</span>, 8ᵃ; <span class=\"citation\">Ned. 21</span>; a. e.</div><div class=\"sense\"><b>—3)</b>  (= <a href=\"#\" data-headword=\"מרי II\">מָרָה</a>) <i>to rebel</i>. <span class=\"citation\">Koh. R. to I, 16</span> <span dir=\"rtl\">הלב מסרב וכ׳</span> the heart is rebellious, as we read (<span class=\"citation\">Jer. V, 23</span>). Midr, Till. to <span class=\"citation\">Ps. V, 11</span> (expl. <span dir=\"rtl\">מרו</span>, ib.) <span dir=\"rtl\">שסֵרְבוּ כנגדך</span> ed. Bub. (oth. ed. <span dir=\"rtl\">שרבו</span>, corr. acc.) they rebelled against thee; <span class=\"citation\">Yalk. ib. 632</span>; a. e.</div>","alt":[]}};
